window.__X_NEWS__ = {"updated_at": "2026-10-22 07:12 Asia/Shanghai", "updated_at_iso": "2026-10-21T23:12:32.000Z", "count": 91, "domains": ["科技", "商业", "中国", "国际", "体育", "娱乐", "科学"], "items": [{"id": "2112386205996245100", "domain": "科技", "title_en": "Sam Altman Outlines Three Paths for Safe Advanced AI Development", "title_zh": "奥特曼勾勒先进 AI 安全发展的三条路径", "hook_en": "Sam Altman gathered OpenAI staff to map out three stark options for handling super-smart AI, right as the Trump administration steps in with its own oversight plans.", "hook_zh": "萨姆·奥特曼召集 OpenAI 员工讨论应对超强 AI 的三条截然不同选项，恰逢特朗普政府推出自有监管计划。", "summary_en": "Last week, Altman described an international body like the IAEA to enforce safety at frontier labs, which he favors; a CERN-style merger of AI labs to share models, known as the 'Demis plan'; and a rejected idea of one lab dominating by disabling rivals' hardware, dubbed the 'Eliezer plan.' He stressed OpenAI must pick a path within a year to avoid falling behind competitors amid safety pressures. The talk coincides with the Trump administration's new Super Intelligence Force, using existing laws to tackle national security and civil liberties risks from advanced AI. Reports from The Information have sparked online talks on AI's future, blending safety concerns with hopes for shared prosperity.", "summary_zh": "上周奥特曼描述了三条路径：他倾向的类似国际原子能机构的国际机构以约束前沿实验室安全；被称为「Demis 方案」的类 CERN 实验室合并以共享模型；以及被否决的「Eliezer 方案」——由单一实验室通过瘫痪对手硬件来主导。他强调 OpenAI 须在一年内选定路径，以免在安全压力下落后于竞争对手。谈话正值特朗普政府成立「超级智能部队」，拟用现有法律应对先进 AI 带来的国家安全与公民自由风险。《The Information》相关报道引发网上对 AI 未来的讨论，交织安全关切与共享繁荣期待。", "body_en": "Sam Altman Outlines Three Paths for Safe Advanced AI Development.\n\nSam Altman gathered OpenAI staff to map out three stark options for handling super-smart AI, right as the Trump administration steps in with its own oversight plans.\n\nLast week, Altman described an international body like the IAEA to enforce safety at frontier labs, which he favors; a CERN-style merger of AI labs to share models, known as the 'Demis plan'; and a rejected idea of one lab dominating by disabling rivals' hardware, dubbed the 'Eliezer plan.' He stressed OpenAI must pick a path within a year to avoid falling behind competitors amid safety pressures.\n\nThe talk coincides with the Trump administration's new Super Intelligence Force, using existing laws to tackle national security and civil liberties risks from advanced AI. Reports from The Information have sparked online talks on AI's future, blending safety concerns with hopes for shared prosperity.", "body_zh": "奥特曼勾勒先进 AI 安全发展的三条路径。\n\n萨姆·奥特曼召集 OpenAI 员工讨论应对超强 AI 的三条截然不同选项，恰逢特朗普政府推出自有监管计划。\n\n上周奥特曼描述了三条路径：他倾向的类似国际原子能机构的国际机构以约束前沿实验室安全；被称为「Demis 方案」的类 CERN 实验室合并以共享模型；以及被否决的「Eliezer 方案」——由单一实验室通过瘫痪对手硬件来主导。他强调 OpenAI 须在一年内选定路径，以免在安全压力下落后于竞争对手。\n\n谈话正值特朗普政府成立「超级智能部队」，拟用现有法律应对先进 AI 带来的国家安全与公民自由风险。《The Information》相关报道引发网上对 AI 未来的讨论，交织安全关切与共享繁荣期待。", "url": "https://x.com/i/trending/2112386205996245100", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-20T14:10:55.000Z"}, {"id": "2112895365657567737", "domain": "科技", "title_en": "Micron Reaches Labor Deal at Taiwan's Taichung Plant, Averting Strike", "title_zh": "美光与台中厂达成劳资协议，罢工风险缓解", "hook_en": "Workers at Micron's key Taichung chip plant in Taiwan can breathe easier after signing a labor agreement that pulls back from a looming strike.", "hook_zh": "美光台湾关键台中芯片厂劳资双方签署协议，此前一触即发的罢工警报得以缓和。", "summary_en": "The deal at the Taichung facility, Micron's largest in Taiwan and a hub for DRAM and high-bandwidth memory chips vital to AI servers, resolves tensions and cancels mediation set for October 22. It covers multiple issues, with both sides calling talks constructive, though details will go directly to the roughly 15,000 employees across Taiwan sites in coming days. Unions pushed for a permanent profit-sharing plan modeled on rivals like Samsung and SK Hynix, potentially worth billions annually. A separate Taoyuan union still plans a one-day warning strike on October 22, but the Taichung progress eases risks amid tight AI-driven memory demand, boosting Micron shares.", "summary_zh": "台中厂是美光在台最大据点，也是服务 AI 服务器的 DRAM 与高带宽内存枢纽。协议化解紧张，原定 10 月 22 日的调解取消。双方称谈判具建设性，细节将在未来数日直接通报全台约 1.5 万名员工。工会曾争取比照三星、SK 海力士的永久利润分享方案，潜在金额可达每年数十亿。桃园另一工会仍计划 10 月 22 日举行一日警告性罢工，但台中进展在 AI 存储需求紧张背景下降低风险，美光股价亦获提振。", "body_en": "Micron Reaches Labor Deal at Taiwan's Taichung Plant, Averting Strike.\n\nWorkers at Micron's key Taichung chip plant in Taiwan can breathe easier after signing a labor agreement that pulls back from a looming strike.\n\nThe deal at the Taichung facility, Micron's largest in Taiwan and a hub for DRAM and high-bandwidth memory chips vital to AI servers, resolves tensions and cancels mediation set for October 22. It covers multiple issues, with both sides calling talks constructive, though details will go directly to the roughly 15,000 employees across Taiwan sites in coming days.\n\nUnions pushed for a permanent profit-sharing plan modeled on rivals like Samsung and SK Hynix, potentially worth billions annually. A separate Taoyuan union still plans a one-day warning strike on October 22, but the Taichung progress eases risks amid tight AI-driven memory demand, boosting Micron shares.", "body_zh": "美光与台中厂达成劳资协议，罢工风险缓解。\n\n美光台湾关键台中芯片厂劳资双方签署协议，此前一触即发的罢工警报得以缓和。\n\n台中厂是美光在台最大据点，也是服务 AI 服务器的 DRAM 与高带宽内存枢纽。协议化解紧张，原定 10 月 22 日的调解取消。\n\n双方称谈判具建设性，细节将在未来数日直接通报全台约 1.5 万名员工。工会曾争取比照三星、SK 海力士的永久利润分享方案，潜在金额可达每年数十亿。桃园另一工会仍计划 10 月 22 日举行一日警告性罢工，但台中进展在 AI 存储需求紧张背景下降低风险，美光股价亦获提振。", "url": "https://x.com/i/trending/2112895365657567737", "category": "News", "topics": ["Business & Finance"], "updated_at": "2026-10-21T13:20:26.000Z"}, {"id": "2112176711844458620", "domain": "科技", "title_en": "Anthropic Commits Shares to Public Benefit Fund", "title_zh": "Anthropic 将股份拨入公益基金", "hook_en": "Anthropic's pledge to dedicate 5% of its shares to public good initiatives feels like a direct response to AI's promise of abundance for everyone.", "hook_zh": "Anthropic 承诺拿出 5% 股份用于公益，被视作对 AI「丰裕」承诺的回应。", "summary_en": "The AI company behind Claude models announced a Public Benefit Fund starting with 5% of shares, pending stockholder approval, which could grow by up to 2% for every 50% valuation increase above a baseline. Combined with prior pledges, this totals about 20% of shares for purposes like nonprofit donations, aid to affected groups, or addressing AI's job impacts—building on a $200 million labor study commitment, with no funds for lobbying. Elon Musk replied that this is what he will do, later specifying 'universal high income,' fueling talk of AI-driven prosperity shared widely, though some see it as flexible public benefit rather than formal income programs.", "summary_zh": "公益基金起步拟配置 5% 股份（待批准）；叠加此前承诺，约 20% 股份将用于非营利捐赠与就业冲击援助。", "body_en": "Anthropic Commits Shares to Public Benefit Fund.\n\nAnthropic's pledge to dedicate 5% of its shares to public good initiatives feels like a direct response to AI's promise of abundance for everyone.\n\nThe AI company behind Claude models announced a Public Benefit Fund starting with 5% of shares, pending stockholder approval, which could grow by up to 2% for every 50% valuation increase above a baseline.\n\nCombined with prior pledges, this totals about 20% of shares for purposes like nonprofit donations, aid to affected groups, or addressing AI's job impacts—building on a $200 million labor study commitment, with no funds for lobbying. Elon Musk replied that this is what he will do, later specifying 'universal high income,' fueling talk of AI-driven prosperity shared widely, though some see it as flexible public benefit rather than formal income programs.", "body_zh": "Anthropic 将股份拨入公益基金。\n\nAnthropic 承诺拿出 5% 股份用于公益，被视作对 AI「丰裕」承诺的回应。\n\n公益基金起步拟配置 5% 股份（待批准）；叠加此前承诺，约 20% 股份将用于非营利捐赠与就业冲击援助。", "url": "https://x.com/i/trending/2112176711844458620", "category": "News", "topics": ["Business & Finance", "Technology"], "updated_at": "2026-10-20T21:34:55.000Z"}, {"id": "2112595601669919101", "domain": "科技", "title_en": "OpenAI Quiets Support for AI Chip Export Limits to China", "title_zh": "OpenAI 淡化对输华 AI 芯片出口限制的支持", "hook_en": "OpenAI once pushed hard for strict U.S. limits on advanced AI chips heading to China. Now, the company has gone quiet, leaving policymakers surprised and critics pointing fingers.", "hook_zh": "OpenAI 曾力推美国严格限制先进 AI 芯片流向中国，如今却噤声，令政策制定者意外，批评者纷纷指责。", "summary_en": "Last year, OpenAI lobbied for curbs on sales of Nvidia's advanced processors to Beijing-backed AI labs to protect U.S. interests. Capitol Hill aides note the firm has stopped advocating, a shift that aids Nvidia—which opposes tighter rules—and aligns with broader political approaches amid a major 2025 infrastructure partnership worth up to $100 billion. Critics like Samuel Hammond call it shortsighted for U.S. AI dominance and security, while OpenAI stresses maintaining a compute lead through effective controls as part of strategy. Rival Anthropic continues backing restriction bills as lawmakers eye defense bill amendments.", "summary_zh": "去年 OpenAI 曾游说限制英伟达先进处理器售予有北京背景的 AI 实验室，以维护美方利益。国会山助手称公司已停止倡议；这一转向有利于反对加严规则的英伟达，也契合更广政治取态，并与 2025 年一项最高可达 1000 亿美元的重大基础设施合作相呼应。Samuel Hammond 等批评者称其短视，有损美国 AI 主导与安全；OpenAI 则强调通过有效管制保持算力领先。对手 Anthropic 仍支持限制法案，议员正关注国防授权法案修正案。", "body_en": "OpenAI Quiets Support for AI Chip Export Limits to China.\n\nOpenAI once pushed hard for strict U.S. limits on advanced AI chips heading to China. Now, the company has gone quiet, leaving policymakers surprised and critics pointing fingers.\n\nLast year, OpenAI lobbied for curbs on sales of Nvidia's advanced processors to Beijing-backed AI labs to protect U.S. interests. Capitol Hill aides note the firm has stopped advocating, a shift that aids Nvidia—which opposes tighter rules—and aligns with broader political approaches amid a major 2025 infrastructure partnership worth up to $100 billion.\n\nCritics like Samuel Hammond call it shortsighted for U.S. AI dominance and security, while OpenAI stresses maintaining a compute lead through effective controls as part of strategy. Rival Anthropic continues backing restriction bills as lawmakers eye defense bill amendments.", "body_zh": "OpenAI 淡化对输华 AI 芯片出口限制的支持。\n\nOpenAI 曾力推美国严格限制先进 AI 芯片流向中国，如今却噤声，令政策制定者意外，批评者纷纷指责。\n\n去年 OpenAI 曾游说限制英伟达先进处理器售予有北京背景的 AI 实验室，以维护美方利益。国会山助手称公司已停止倡议；这一转向有利于反对加严规则的英伟达，也契合更广政治取态，并与 2025 年一项最高可达 1000 亿美元的重大基础设施合作相呼应。\n\nSamuel Hammond 等批评者称其短视，有损美国 AI 主导与安全；OpenAI 则强调通过有效管制保持算力领先。对手 Anthropic 仍支持限制法案，议员正关注国防授权法案修正案。", "url": "https://x.com/i/trending/2112595601669919101", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-20T17:34:14.000Z"}, {"id": "2112188369618784335", "domain": "科技", "title_en": "DHS Orders Federal Agencies to Remove DeepSeek AI Products", "title_zh": "美国国土安全部令联邦机构清除 DeepSeek AI 产品", "hook_en": "The U.S. Department of Homeland Security just drew a firm line on Chinese AI tools in government systems, citing risks of data flowing to China and hidden security threats.", "hook_zh": "美国国土安全部划下红线：以数据流向中国与潜在安全风险为由，要求联邦系统清除中国 AI 工具。", "summary_en": "Under a new Federal Register notice dated October 20, 2026, DHS directed civilian federal agencies to halt procurement from Hangzhou DeepSeek Artificial Intelligence Co. and remove all its products, including those embedded in third-party services. The order highlights dangers like sensitive data transfers mandated by Chinese law, collection of personal information, and potential malware in the models. DeepSeek, known for efficient open-weight AI models that run well on modest hardware, now faces these restrictions amid broader U.S. limits on Chinese tech, though defense and intelligence systems remain separately regulated.", "summary_zh": "根据2026年10月20日的新联邦公报通知，国土安全部指示民事联邦机构停止从杭州DeepSeek人工智能公司采购，并删除其所有产品，包括嵌入第三方服务的产品。该命令强调了中国法律规定的敏感数据传输、个人信息收集以及模型中潜在的恶意软件等危险。 DeepSeek以高效的开放式重量级人工智能模型而闻名，这些模型在中等硬件上运行良好，但由于美国对中国技术的更广泛限制， DeepSeek现在面临这些限制，尽管国防和情报系统仍然受到单独监管。", "body_en": "DHS Orders Federal Agencies to Remove DeepSeek AI Products.\n\nThe U.S. Department of Homeland Security just drew a firm line on Chinese AI tools in government systems, citing risks of data flowing to China and hidden security threats.\n\nUnder a new Federal Register notice dated October 20, 2026, DHS directed civilian federal agencies to halt procurement from Hangzhou DeepSeek Artificial Intelligence Co. and remove all its products, including those embedded in third-party services.\n\nThe order highlights dangers like sensitive data transfers mandated by Chinese law, collection of personal information, and potential malware in the models. DeepSeek, known for efficient open-weight AI models that run well on modest hardware, now faces these restrictions amid broader U.S. limits on Chinese tech, though defense and intelligence systems remain separately regulated.", "body_zh": "美国国土安全部划下红线：以数据流向中国与潜在安全风险为由，要求联邦系统清除中国 AI 工具。\n\n根据2026年10月20日的新联邦公报通知，国土安全部指示民事联邦机构停止从杭州DeepSeek人工智能公司采购，并删除其所有产品，包括嵌入第三方服务的产品。\n\n该命令强调了中国法律规定的敏感数据传输、个人信息收集以及模型中潜在的恶意软件等危险。DeepSeek以高效的开放式重量级人工智能模型而闻名，这些模型在中等硬件上运行良好，但由于美国对中国技术的更广泛限制， DeepSeek现在面临这些限制，尽管国防和情报系统仍然受到单独监管。", "url": "https://x.com/i/trending/2112188369618784335", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-21T11:44:28.000Z"}, {"id": "2112613033243721837", "domain": "科技", "title_en": "OpenAI Acquires Orchestra Bio to Speed Drug Development", "title_zh": "OpenAI收购Orchestra Bio以加快药物开发", "hook_en": "OpenAI just brought in a team that's all about wrangling the chaos of drug development, folding their know-how into AI tools that could get treatments to patients faster.", "hook_zh": "OpenAI刚刚引入了一个团队，致力于解决药物开发的混乱局面，将他们的专业知识整合到人工智能工具中，从而更快地为患者提供治疗。", "summary_en": "On October 20, 2026, OpenAI announced it acquired Orchestra Bio, a four-year-old startup that helps biopharma teams track studies, timelines, and setbacks like failed manufacturing batches. The deal integrates Orchestra's platform into OpenAI's Rosalind suite, which powers biology and chemistry reasoning for customers including Moderna and Novo Nordisk. Founder Ashoka Rajendra celebrated the milestone on the company's anniversary, excited to scale their mission with OpenAI's AI agents. President Greg Brockman called it a key step in accelerating discoveries into real treatments.", "summary_zh": "2026年10月20日， OpenAI宣布收购Orchestra Bio ，这是一家成立四年的初创公司，帮助生物制药团队跟踪研究、时间表和失败的生产批次等挫折。该交易将Orchestra的平台整合到OpenAI的Rosalind套件中，该套件为Moderna和Novo Nordisk等客户的生物和化学推理提供支持。 创始人Ashoka Rajendra庆祝了公司成立周年的里程碑，很高兴能与OpenAI的人工智能代理一起扩大他们的使命。总裁格雷格·布罗克曼（ Greg Brockman ）称之为加速发现真正治疗方法的关键一步。", "body_en": "OpenAI Acquires Orchestra Bio to Speed Drug Development.\n\nOpenAI just brought in a team that's all about wrangling the chaos of drug development, folding their know-how into AI tools that could get treatments to patients faster.\n\nOn October 20, 2026, OpenAI announced it acquired Orchestra Bio, a four-year-old startup that helps biopharma teams track studies, timelines, and setbacks like failed manufacturing batches. The deal integrates Orchestra's platform into OpenAI's Rosalind suite, which powers biology and chemistry reasoning for customers including Moderna and Novo Nordisk.\n\nFounder Ashoka Rajendra celebrated the milestone on the company's anniversary, excited to scale their mission with OpenAI's AI agents. President Greg Brockman called it a key step in accelerating discoveries into real treatments.", "body_zh": "OpenAI刚刚引入了一个团队，致力于解决药物开发的混乱局面，将他们的专业知识整合到人工智能工具中，从而更快地为患者提供治疗。\n\n2026年10月20日， OpenAI宣布收购Orchestra Bio ，这是一家成立四年的初创公司，帮助生物制药团队跟踪研究、时间表和失败的生产批次等挫折。该交易将Orchestra的平台整合到OpenAI的Rosalind套件中，该套件为Moderna和Novo Nordisk等客户的生物和化学推理提供支持。\n\n创始人Ashoka Rajendra庆祝了公司成立周年的里程碑，很高兴能与OpenAI的人工智能代理一起扩大他们的使命。总裁格雷格·布罗克曼（ Greg Brockman ）称之为加速发现真正治疗方法的关键一步。", "url": "https://x.com/i/trending/2112613033243721837", "category": "News", "topics": ["Technology", "Biotech"], "updated_at": "2026-10-21T12:34:03.000Z"}, {"id": "2112891431501390231", "domain": "科技", "title_en": "NVIDIA Unveils OpenShell to Secure Enterprise AI Agents", "title_zh": "NVIDIA推出OpenShell以保护企业AI代理", "hook_en": "At GTC Berlin, NVIDIA CEO Jensen Huang showed how businesses can now run AI agents freely—yet safely—by setting strict boundaries that stop them cold if crossed.", "hook_zh": "在GTC柏林， NVIDIA首席执行官Jensen Huang展示了企业现在如何通过设置严格的界限，在跨越界限时阻止他们自由运行AI代理，从而安全地运行AI代理。", "summary_en": "The OpenShell Reference Architecture pairs NVIDIA's Vera Rubin systems, Vera CPUs, and BlueField-4 DPUs with Sentry software for real-time monitoring, quarantining rogue agents in milliseconds. It builds on prior safety work, enforces zero-trust policies where permissions are denied by default, and is open source under Apache 2.0. Over 100 partners like Anthropic, AWS, Microsoft, and OpenAI are adopting it, with banks and firms like SAP integrating for edge and enterprise use. Huang emphasized accelerating AI safety alongside capability to deploy billions of agents responsibly.", "summary_zh": "OpenShell参考架构将NVIDIA的Vera Rubin系统、Vera CPU和BlueField-4 DPU与Sentry软件配对，用于实时监控，在毫秒内隔离流氓代理。它建立在先前的安全工作的基础上，在默认情况下拒绝权限的情况下执行零信任策略，并且在Apache 2.0下是开源的。 Anthropic、AWS、Microsoft和OpenAI等100多个合作伙伴正在采用它， SAP等银行和公司整合了边缘和企业用途。Huang强调了加速人工智能安全以及负责任地部署数十亿代理的能力。", "body_en": "NVIDIA Unveils OpenShell to Secure Enterprise AI Agents.\n\nAt GTC Berlin, NVIDIA CEO Jensen Huang showed how businesses can now run AI agents freely—yet safely—by setting strict boundaries that stop them cold if crossed.\n\nThe OpenShell Reference Architecture pairs NVIDIA's Vera Rubin systems, Vera CPUs, and BlueField-4 DPUs with Sentry software for real-time monitoring, quarantining rogue agents in milliseconds. It builds on prior safety work, enforces zero-trust policies where permissions are denied by default, and is open source under Apache 2.0.\n\nOver 100 partners like Anthropic, AWS, Microsoft, and OpenAI are adopting it, with banks and firms like SAP integrating for edge and enterprise use. Huang emphasized accelerating AI safety alongside capability to deploy billions of agents responsibly.", "body_zh": "在GTC柏林， NVIDIA首席执行官Jensen Huang展示了企业现在如何通过设置严格的界限，在跨越界限时阻止他们自由运行AI代理，从而安全地运行AI代理。\n\nOpenShell参考架构将NVIDIA的Vera Rubin系统、Vera CPU和BlueField-4 DPU与Sentry软件配对，用于实时监控，在毫秒内隔离流氓代理。它建立在先前的安全工作的基础上，在默认情况下拒绝权限的情况下执行零信任策略，并且在Apache 2.0下是开源的。\n\nAnthropic、AWS、Microsoft和OpenAI等100多个合作伙伴正在采用它， SAP等银行和公司整合了边缘和企业用途。Huang强调了加速人工智能安全以及负责任地部署数十亿代理的能力。", "url": "https://x.com/i/trending/2112891431501390231", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-21T19:02:53.000Z"}, {"id": "2112575527206969617", "domain": "科技", "title_en": "Google's Gemini 4 Argon Processes 25 Trillion Tokens in First 72 Hours", "title_zh": "谷歌的Gemini 4 Argon在前72小时内处理了25万亿个代币", "hook_en": "Google's new Gemini 4 Argon model hit the ground running, handling a massive 25 trillion tokens right after launch. One fun demo even built a 3D periodic table dancing to Tom Lehrer's 'The Elements' song.", "hook_zh": "谷歌的新Gemini 4 Argon型号在推出后立即投入使用，处理了25万亿个代币。一个有趣的演示甚至为Tom Lehrer的“The Elements”歌曲制作了一个3D元素周期表。", "summary_en": "Launched globally in mid-October 2026 via Gemini API, AI Studio, the app for paid users, and Google Antigravity, Argon excels in coding, finance, legal, science, and cybersecurity with its 1-million-token context window. It leads benchmarks like Isoquant's 4.38x speedup, Ramp's Accounting Bench at 61.1%, and Google's Vals Index, though T3 Code users hit 36.5 trillion tokens in the same period. Gemini 4 Carbon is already in early testing, showing gains in 3D tasks but running slower, as user feedback mixes praise for creativity with reports of crashes and quotas.", "summary_zh": "Argon于2026年10月中旬通过Gemini API、AI Studio、付费用户应用程序和Google Antigravity在全球推出，凭借其100万代币的上下文窗口， Argon在编码、金融、法律、科学和网络安全方面表现出色。它引领了Isoquant的4.38倍加速、Ramp's Accounting Bench的61.1%和谷歌的Vals Index等基准，尽管T3 Code用户在同一时期达到了36.5万亿个代币。 Gemini 4 Carbon已经处于早期测试阶段，显示3D任务有所增加，但运行速度较慢，因为用户反馈将对创造力的赞扬与崩溃和配额的报告相结合。", "body_en": "Google's new Gemini 4 Argon model hit the ground running, handling a massive 25 trillion tokens right after launch. One fun demo even built a 3D periodic table dancing to Tom Lehrer's 'The Elements' song.\n\nLaunched globally in mid-October 2026 via Gemini API, AI Studio, the app for paid users, and Google Antigravity, Argon excels in coding, finance, legal, science, and cybersecurity with its 1-million-token context window.\n\nIt leads benchmarks like Isoquant's 4.38x speedup, Ramp's Accounting Bench at 61.1%, and Google's Vals Index, though T3 Code users hit 36.5 trillion tokens in the same period. Gemini 4 Carbon is already in early testing, showing gains in 3D tasks but running slower, as user feedback mixes praise for creativity with reports of crashes and quotas.", "body_zh": "谷歌的新Gemini 4 Argon型号在推出后立即投入使用，处理了25万亿个代币。一个有趣的演示甚至为Tom Lehrer的“The Elements”歌曲制作了一个3D元素周期表。\n\nArgon于2026年10月中旬通过Gemini API、AI Studio、付费用户应用程序和Google Antigravity在全球推出，凭借其100万代币的上下文窗口， Argon在编码、金融、法律、科学和网络安全方面表现出色。\n\n它引领了Isoquant的4.38倍加速、Ramp's Accounting Bench的61.1%和谷歌的Vals Index等基准，尽管T3 Code用户在同一时期达到了36.5万亿个代币。Gemini 4 Carbon已经处于早期测试阶段，显示3D任务有所增加，但运行速度较慢，因为用户反馈将对创造力的赞扬与崩溃和配额的报告相结合。", "url": "https://x.com/i/trending/2112575527206969617", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-21T17:22:34.000Z"}, {"id": "2113035835780001819", "domain": "科技", "title_en": "Demis Hassabis Shortens AGI Timeline to Two or Three Years", "title_zh": "哈萨比斯将 AGI 时间表缩短至两到三年", "hook_en": "Demis Hassabis just pulled his AGI prediction closer, now seeing it in just two to three years. It's a shift that's got people talking about how fast AI might match human smarts.", "hook_zh": "谷歌 DeepMind 联合创始人德米斯·哈萨比斯把通用人工智能到来时间再次提前，称大约只需两到三年。", "summary_en": "In a Wall Street Journal profile on October 21, Google DeepMind co-founder Demis Hassabis updated his artificial general intelligence timeline from three to five years down to two or three, saying it's moving 'nearer and nearer.' He defines AGI as a system matching the full cognitive range of the human brain and proposed a test: recreating Einstein's 1905 relativity papers from pre-1901 knowledge. Hassabis, now Alphabet's chief scientist and focused on AI drug discovery at Isomorphic Labs, stressed safely stewarding AGI for humanity's benefit, comparing its impact to '10 times the industrial revolution at 10 times the speed.' Reactions ranged from excitement over even shorter timelines to skepticism about past overhyped predictions like self-driving cars.", "summary_zh": "在 10 月 21 日《华尔街日报》人物特写中，哈萨比斯把原先三到五年的 AGI 预估收紧为两到三年，并称它「越来越近」。他把 AGI 定义为能覆盖人脑全部认知范围的系统，并提出测试：仅凭 1901 年前的知识复现爱因斯坦 1905 年相对论论文。现任 Alphabet 首席科学家、主导 Isomorphic Labs AI 药物发现的他强调，需为人类福祉安全引导 AGI，并将其影响比作「十倍工业革命、十倍速度」。外界有人兴奋于更短时间表，也有人对自动驾驶等过往高估保持怀疑。", "body_en": "Demis Hassabis Shortens AGI Timeline to Two or Three Years.\n\nDemis Hassabis just pulled his AGI prediction closer, now seeing it in just two to three years. It's a shift that's got people talking about how fast AI might match human smarts.\n\nIn a Wall Street Journal profile on October 21, Google DeepMind co-founder Demis Hassabis updated his artificial general intelligence timeline from three to five years down to two or three, saying it's moving 'nearer and nearer.' He defines AGI as a system matching the full cognitive range of the human brain and proposed a test: recreating Einstein's 1905 relativity papers from pre-1901 knowledge. Hassabis, now Alphabet's chief scientist and focused on AI drug discovery at Isomorphic Labs, stressed safely stewarding AGI for humanity's benefit, comparing its impact to '10 times the industrial revolution at 10 times the speed.' Reactions ranged from excitement over even shorter timelines to skepticism about past overhyped predictions like self-driving cars.", "body_zh": "哈萨比斯将 AGI 时间表缩短至两到三年。\n\n谷歌 DeepMind 联合创始人德米斯·哈萨比斯把通用人工智能到来时间再次提前，称大约只需两到三年。\n\n在 10 月 21 日《华尔街日报》人物特写中，哈萨比斯把原先三到五年的 AGI 预估收紧为两到三年，并称它「越来越近」。他把 AGI 定义为能覆盖人脑全部认知范围的系统，并提出测试：仅凭 1901 年前的知识复现爱因斯坦 1905 年相对论论文。\n\n现任 Alphabet 首席科学家、主导 Isomorphic Labs AI 药物发现的他强调，需为人类福祉安全引导 AGI，并将其影响比作「十倍工业革命、十倍速度」。外界有人兴奋于更短时间表，也有人对自动驾驶等过往高估保持怀疑。", "url": "https://x.com/i/trending/2113035835780001819", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-21T22:40:44.000Z"}, {"id": "2112883740699480270", "domain": "科技", "title_en": "OpenAI Partners with Google Cloud for Model Access", "title_zh": "OpenAI 与谷歌云合作，前沿模型将入驻 Model Garden", "hook_en": "Enterprises on Google Cloud can now tap OpenAI's latest models without switching platforms. This deal opens up powerful AI tools right where teams already work.", "hook_zh": "GPT-6 Astra 等 OpenAI 强模型即将登陆谷歌云，企业可在同一平台调用顶尖 AI 工具，不必再多端切换。", "summary_en": "OpenAI and Google Cloud announced a partnership bringing models like GPT-6 Astra, GPT-6.1 Sol, and GPT-6 Luna, plus Codex coding workflows, to Google Cloud’s Model Garden. It marks OpenAI's expansion to all three major U.S. cloud providers after Azure exclusivity ended in April 2026, with private previews underway and general availability soon. Google Cloud now offers the top closed-source models—Gemini, Claude, and OpenAI's GPT lineup—on one platform, easing access for regulated industries through existing commitments and strong governance.", "summary_zh": "谷歌云今日宣布，企业客户很快可在 Model Garden 中直接使用 OpenAI 前沿模型，包括 GPT-6 Astra 与 Codex 智能体工作流，并与 Gemini、Claude 及逾 200 款其他模型并列。企业可通过谷歌云 Marketplace 采购、沿用既有消费承诺，并接入 Google Antigravity、Gemini Agent 等工具灵活处理任务。此举使 OpenAI 在微软 Azure 之外拓展云端触达——Azure 现已非独家——也为受监管行业提供更强数据治理与高性能部署选项。分析人士认为，这有利于多模型策略，并降低 AI 落地门槛。", "body_en": "OpenAI Partners with Google Cloud to Offer Frontier Models in Model Garden.\n\nOpenAI's powerful models like GPT-6 Astra are landing on Google Cloud, giving businesses a unified spot to access top AI tools without juggling platforms.\n\nGoogle Cloud announced today that enterprise customers can soon use OpenAI's frontier models, including GPT-6 Astra and Codex agentic workflows, directly in its Model Garden alongside Gemini, Claude, and over 200 others. Businesses can purchase through the Google Cloud Marketplace, apply existing spending commitments, and integrate into tools like Google Antigravity and Gemini Agent for flexible task handling.\n\nThis expands OpenAI's reach beyond Microsoft Azure—now non-exclusive—to more cloud options, supporting regulated industries with strong data governance and high-performance setup. Analysts see it as a win for multi-model strategies and easier AI adoption.", "body_zh": "OpenAI 与谷歌云合作，前沿模型将入驻 Model Garden。\n\nGPT-6 Astra 等 OpenAI 强模型即将登陆谷歌云，企业可在同一平台调用顶尖 AI 工具，不必再多端切换。\n\n谷歌云今日宣布，企业客户很快可在 Model Garden 中直接使用 OpenAI 前沿模型，包括 GPT-6 Astra 与 Codex 智能体工作流，并与 Gemini、Claude 及逾 200 款其他模型并列。企业可通过谷歌云 Marketplace 采购、沿用既有消费承诺，并接入 Google Antigravity、Gemini Agent 等工具灵活处理任务。\n\n此举使 OpenAI 在微软 Azure 之外拓展云端触达——Azure 现已非独家——也为受监管行业提供更强数据治理与高性能部署选项。分析人士认为，这有利于多模型策略，并降低 AI 落地门槛。", "url": "https://x.com/i/trending/2112883740699480270", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-21T22:41:25.000Z"}, {"id": "2112579117904535807", "domain": "科技", "title_en": "Micron Funds New York Minerals Processing for AI Chip Supplies", "title_zh": "美光资助纽约关键矿物加工，保障 AI 存储芯片原料", "hook_en": "Micron is stepping up to secure vital materials for its AI memory chips right at home in New York. The move aims to cut reliance on overseas sources amid surging demand.", "hook_zh": "美光加码在纽约本地保障 AI 内存芯片关键材料，以降低对海外供应的依赖。", "summary_en": "Micron Technology announced strategic funding for Indium Corporation to expand refining of critical minerals like indium at its Rome, New York facility, paired with a long-term supply agreement. This supports Micron's $3 billion U.S. semiconductor supply chain investment and addresses China's dominance in key materials production. Despite the positive step for national security and AI growth, shares dipped 2-3% that day amid concerns over AI spending, Taiwan strikes, and competition.", "summary_zh": "美光宣布战略资助 Indium Corporation，扩大其纽约罗马工厂对铟等关键矿物的精炼，并签订长期供应协议。此举支撑美光约 30 亿美元的美国半导体供应链投入，意在应对中国在关键材料领域的优势地位。消息公布当日美光股价仍下跌约 2%–3%，市场同时消化 AI 开支、台海相关扰动与竞争等担忧。", "body_en": "Micron Funds New York Minerals Processing for AI Chip Supplies.\n\nMicron is stepping up to secure vital materials for its AI memory chips right at home in New York. The move aims to cut reliance on overseas sources amid surging demand.\n\nMicron Technology announced strategic funding for Indium Corporation to expand refining of critical minerals like indium at its Rome, New York facility, paired with a long-term supply agreement. This supports Micron's $3 billion U.S.\n\nsemiconductor supply chain investment and addresses China's dominance in key materials production. Despite the positive step for national security and AI growth, shares dipped 2-3% that day amid concerns over AI spending, Taiwan strikes, and competition.", "body_zh": "美光资助纽约关键矿物加工，保障 AI 存储芯片原料。\n\n美光加码在纽约本地保障 AI 内存芯片关键材料，以降低对海外供应的依赖。\n\n美光宣布战略资助 Indium Corporation，扩大其纽约罗马工厂对铟等关键矿物的精炼，并签订长期供应协议。\n\n此举支撑美光约 30 亿美元的美国半导体供应链投入，意在应对中国在关键材料领域的优势地位。消息公布当日美光股价仍下跌约 2%–3%，市场同时消化 AI 开支、台海相关扰动与竞争等担忧。", "url": "https://x.com/i/trending/2112579117904535807", "category": "News", "topics": ["Technology"], "updated_at": "2026-10-20T16:26:46.000Z"}, {"id": "2112630070984802593", "domain": "科技", "title_en": "OpenAI Launches Locked Chats for Private ChatGPT Conversations", "title_zh": "OpenAI 推出「锁定对话」，保护私密 ChatGPT 聊天", "hook_en": "Ever had a ChatGPT chat too personal to leave in plain view? OpenAI's new Locked Chats let you tuck it away, protected by a PIN or your fingerprint.", "hook_zh": "把屏幕递给别人前，想先藏起敏感对话？锁定对话用 PIN 就能搞定。", "summary_en": "The feature hides selected chats from history, pins, and searches, making them accessible only through a four-digit PIN on all platforms or biometrics on supported phones. It rolled out starting October 20 across Free, Plus, Pro, Business, Enterprise, and Edu plans on web, desktop, and mobile. Locked chats keep new messages in a separate memory section without affecting regular ones, though they lack end-to-end encryption and can't be recovered if the PIN is reset. This adds device-level privacy amid discussions on ChatGPT's memory system, where a study found most entries include psychological insights or personal data created automatically.", "summary_zh": "用户可将选定聊天从历史、置顶和搜索中隐藏，仅能通过四位 PIN（全平台）或支持手机上的生物识别解锁。功能自 10 月 20 日起覆盖免费到企业、教育各档，支持网页、桌面与移动端。锁定对话的新消息进入独立记忆区，不影响普通聊天；但不提供端到端加密，重置 PIN 后亦无法恢复。此举在设备层增加隐私保护，正值外界讨论 ChatGPT 记忆系统——一项研究称多数记忆条目含心理洞察或自动生成的个人数据。", "body_en": "OpenAI Launches Locked Chats for Private ChatGPT Conversations.\n\nEver had a ChatGPT chat too personal to leave in plain view? OpenAI's new Locked Chats let you tuck it away, protected by a PIN or your fingerprint.\n\nThe feature hides selected chats from history, pins, and searches, making them accessible only through a four-digit PIN on all platforms or biometrics on supported phones. It rolled out starting October 20 across Free, Plus, Pro, Business, Enterprise, and Edu plans on web, desktop, and mobile.\n\nLocked chats keep new messages in a separate memory section without affecting regular ones, though they lack end-to-end encryption and can't be recovered if the PIN is reset. This adds device-level privacy amid discussions on ChatGPT's memory system, where a study found most entries include psychological insights or personal data created automatically.", "body_zh": "OpenAI 推出「锁定对话」，保护私密 ChatGPT 聊天。\n\n把屏幕递给别人前，想先藏起敏感对话？锁定对话用 PIN 就能搞定。\n\n用户可将选定聊天从历史、置顶和搜索中隐藏，仅能通过四位 PIN（全平台）或支持手机上的生物识别解锁。功能自 10 月 20 日起覆盖免费到企业、教育各档，支持网页、桌面与移动端。\n\n锁定对话的新消息进入独立记忆区，不影响普通聊天；但不提供端到端加密，重置 PIN 后亦无法恢复。此举在设备层增加隐私保护，正值外界讨论 ChatGPT 记忆系统——一项研究称多数记忆条目含心理洞察或自动生成的个人数据。", "url": "https://x.com/i/trending/2112630070984802593", "category": "News", "topics": ["Technology"], "updated_at": "2026-10-21T08:41:04.000Z"}, {"id": "2112540739628630161", "domain": "科技", "title_en": "Amazon Explores Offloading $8 Billion in Nvidia Chips to Investors", "title_zh": "亚马逊探讨将约 80 亿美元英伟达芯片转售给投资者", "hook_en": "Amazon has thousands of cutting-edge Nvidia chips ready for its U.S. data centers, but power shortages mean many sit unused in warehouses.", "hook_zh": "亚马逊美国数据中心备好大批尖端英伟达芯片，却因电力短缺，不少仍堆在仓库闲置。", "summary_en": "The company is in talks to shift about $8 billion worth of Grace Blackwell chips into a special-purpose vehicle, which would lease them back to Amazon and raise funds through debt and a small equity stake. This comes as internal documents reveal a massive influx of Nvidia GB300 racks—$5 billion in one month alone—piling up due to insufficient power and infrastructure in data centers across Nevada and Virginia. Observers note the timing raises questions about Amazon's AI hardware glut amid its $220 billion capital spending push, though some see the move as smart financing to keep using the chips without owning them outright.", "summary_zh": "公司正洽谈把约 80 亿美元的 Grace Blackwell 芯片装入特殊目的载体，再回租给亚马逊，并通过债务与少量股权融资。内部文件显示，英伟达 GB300 机架单月涌入量达 50 亿美元，内华达与弗吉尼亚等地因电力与基建不足而积压。观察者质疑，在公司推进约 2200 亿美元资本开支之际，此举是否暴露 AI 硬件过剩；也有人认为这是既保留算力使用权、又不必全额持有芯片的融资安排。", "body_en": "Amazon Explores Offloading $8 Billion in Nvidia Chips to Investors.\n\nAmazon has thousands of cutting-edge Nvidia chips ready for its U.S. data centers, but power shortages mean many sit unused in warehouses.\n\nThe company is in talks to shift about $8 billion worth of Grace Blackwell chips into a special-purpose vehicle, which would lease them back to Amazon and raise funds through debt and a small equity stake.\n\nThis comes as internal documents reveal a massive influx of Nvidia GB300 racks—$5 billion in one month alone—piling up due to insufficient power and infrastructure in data centers across Nevada and Virginia. Observers note the timing raises questions about Amazon's AI hardware glut amid its $220 billion capital spending push, though some see the move as smart financing to keep using the chips without owning them outright.", "body_zh": "亚马逊探讨将约 80 亿美元英伟达芯片转售给投资者。\n\n亚马逊美国数据中心备好大批尖端英伟达芯片，却因电力短缺，不少仍堆在仓库闲置。\n\n公司正洽谈把约 80 亿美元的 Grace Blackwell 芯片装入特殊目的载体，再回租给亚马逊，并通过债务与少量股权融资。\n\n内部文件显示，英伟达 GB300 机架单月涌入量达 50 亿美元，内华达与弗吉尼亚等地因电力与基建不足而积压。观察者质疑，在公司推进约 2200 亿美元资本开支之际，此举是否暴露 AI 硬件过剩；也有人认为这是既保留算力使用权、又不必全额持有芯片的融资安排。", "url": "https://x.com/i/trending/2112540739628630161", "category": "News", "topics": ["Business & Finance", "Stocks", "Technology", "AI"], "updated_at": "2026-10-20T13:52:24.000Z"}, {"id": "2112933585816781110", "domain": "商业", "title_en": "ANC Official Blames Global Conflicts for South Africa's Economic Woes, Faces Sharp Backlash", "title_zh": "非国大官员把经济困局甩给全球冲突，遭尖锐反弹", "hook_en": "Charles Sekoati pointed to wars in Ukraine and the Middle East as the culprits behind South Africa's stalled growth. Online critics fired back, saying domestic failures have dragged the economy down for over a decade.", "hook_zh": "Charles Sekoati 把南非增长停滞归咎于乌克兰与中东战事。网上批评者回击：国内失灵已拖累经济十余年。", "summary_en": "On the day Finance Minister Enoch Godongwana presented the Medium-Term Budget Policy Statement, ANC finance whip Charles Sekoati told Newzroom Afrika that unforeseen global crises like the Russia-Ukraine war and Middle East tensions are blocking job creation and growth. Godongwana noted some fiscal gains, like a stabilized debt-to-GDP ratio at 78.4%, but cut the 2026 growth forecast to 1.2% due to higher oil and food prices. Critics highlighted that South Africa's GDP per capita in 2025 remains below 2008 levels, with IMF data showing 1.0% growth projected for 2026—far below neighbors like Ethiopia at 9.2%—and called the explanation a deflection from years of policy uncertainty, poor infrastructure, and high unemployment.", "summary_zh": "在财政部长 Enoch Godongwana 公布中期预算政策声明当天，非国大财政党鞭 Charles Sekoati 对 Newzroom Afrika 表示，俄乌战争、中东紧张等意外全球危机阻碍就业与增长。Godongwana 提到债务占 GDP 比稳定在 78.4% 等财政改善，但因油价与粮价上涨，将 2026 年增长预期下调至 1.2%。批评者指出，南非 2025 年人均 GDP 仍低于 2008 年水平，IMF 预计 2026 年仅增长 1.0%，远低于邻国如埃塞俄比亚的 9.2%，并称这一解释是在回避多年的政策不确定、基础设施薄弱与高失业。", "body_en": "ANC Official Blames Global Conflicts for South Africa's Economic Woes, Faces Sharp Backlash.\n\nCharles Sekoati pointed to wars in Ukraine and the Middle East as the culprits behind South Africa's stalled growth. Online critics fired back, saying domestic failures have dragged the economy down for over a decade.\n\nOn the day Finance Minister Enoch Godongwana presented the Medium-Term Budget Policy Statement, ANC finance whip Charles Sekoati told Newzroom Afrika that unforeseen global crises like the Russia-Ukraine war and Middle East tensions are blocking job creation and growth.\n\nGodongwana noted some fiscal gains, like a stabilized debt-to-GDP ratio at 78.4%, but cut the 2026 growth forecast to 1.2% due to higher oil and food prices. Critics highlighted that South Africa's GDP per capita in 2025 remains below 2008 levels, with IMF data showing 1.0% growth projected for 2026—far below neighbors like Ethiopia at 9.2%—and called the explanation a deflection from years of policy uncertainty, poor infrastructure, and high unemployment.", "body_zh": "非国大官员把经济困局甩给全球冲突，遭尖锐反弹。\n\nCharles Sekoati 把南非增长停滞归咎于乌克兰与中东战事。网上批评者回击：国内失灵已拖累经济十余年。\n\n在财政部长 Enoch Godongwana 公布中期预算政策声明当天，非国大财政党鞭 Charles Sekoati 对 Newzroom Afrika 表示，俄乌战争、中东紧张等意外全球危机阻碍就业与增长。\n\nGodongwana 提到债务占 GDP 比稳定在 78.4% 等财政改善，但因油价与粮价上涨，将 2026 年增长预期下调至 1.2%。批评者指出，南非 2025 年人均 GDP 仍低于 2008 年水平，IMF 预计 2026 年仅增长 1.0%，远低于邻国如埃塞俄比亚的 9.2%，并称这一解释是在回避多年的政策不确定、基础设施薄弱与高失业。", "url": "https://x.com/i/trending/2112933585816781110", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-21T15:54:19.000Z"}, {"id": "2112859560524288427", "domain": "商业", "title_en": "Blockchain Groups Push SEC to Codify Digital Commodity Rules", "title_zh": "多家区块链机构促 SEC 将「数字商品」写入规则正文", "hook_en": "Major blockchain organizations are calling on the SEC to lock in its digital commodity classification right in the rule text, ensuring lasting clarity for developers building the future of crypto.", "hook_zh": "主要区块链团队联名致函美国证交会：请把「数字商品」标签直接写进具有约束力的规则文本，以求长期清晰度。", "summary_en": "Stellar, Hedera, Aptos Labs, Ava Labs, Cardano Foundation, and Chainlink Labs jointly urged the SEC to embed its March 2026 interpretation—classifying certain Layer 1 tokens like APT and ADA as digital commodities—directly into the text of its Regulation Crypto Assets proposal. They argue this would provide certainty for staking, mining, and secondary sales, supporting U.S. innovation on foundational blockchain infrastructure. Ripple separately backed the proposal, emphasizing that only investment contracts, not tokens themselves, qualify as securities under the Howey test. The SEC received about 140 comments by October 20, with more feedback still coming as it reviews the input.", "summary_zh": "Stellar、Hedera、Aptos Labs、Ava Labs、Cardano Foundation、Chainlink Labs 等机构敦促 SEC，将 APT、AVAX、ADA、LINK、HBAR、XLM、XRP 等代币的数字商品分类，从说明性表述移入《加密资产监管》提案的操作性条款。此举呼应 2026 年 3 月 SEC-CFTC 解释，意见征询期于 2026 年 10 月 20 日截止；各方希望分类出现在正文而非仅前言，以便开发者在交易、质押与挖矿上获得确定性。Ripple 亦支持提案，强调触发证券法的是投资合同而非代币本身。推动旨在减少不确定性，并让加密创新留在美国。", "body_en": "Blockchain Groups Push SEC to Codify Digital Commodity Status in Crypto Rules.\n\nMajor blockchain teams just sent a joint plea to the SEC: lock the 'digital commodity' label right into the rules for lasting clarity.\n\nGroups like Stellar, Hedera, Aptos Labs, Ava Labs, Cardano Foundation, and Chainlink Labs urged the SEC to move the digital commodity classification—from tokens like APT, AVAX, ADA, LINK, HBAR, XLM, and XRP—directly into the binding text of its Regulation Crypto Assets proposal. This follows a March 2026 SEC-CFTC interpretation, with the comment period closing October 20, 2026; they want it in the operative rules, not just the preamble, for developer certainty on trading, staking, and mining.\n\nRipple separately backed the proposal, stressing that investment contracts, not tokens, trigger securities laws. The push aims to cut uncertainty and keep crypto innovation in the U.S.", "body_zh": "多家区块链机构促 SEC 将「数字商品」写入规则正文。\n\n主要区块链团队联名致函美国证交会：请把「数字商品」标签直接写进具有约束力的规则文本，以求长期清晰度。\n\nStellar、Hedera、Aptos Labs、Ava Labs、Cardano Foundation、Chainlink Labs 等机构敦促 SEC，将 APT、AVAX、ADA、LINK、HBAR、XLM、XRP 等代币的数字商品分类，从说明性表述移入《加密资产监管》提案的操作性条款。此举呼应 2026 年 3 月 SEC-CFTC 解释，意见征询期于 2026 年 10 月 20 日截止；各方希望分类出现在正文而非仅前言，以便开发者在交易、质押与挖矿上获得确定性。\n\nRipple 亦支持提案，强调触发证券法的是投资合同而非代币本身。推动旨在减少不确定性，并让加密创新留在美国。", "url": "https://x.com/i/trending/2112859560524288427", "category": "News", "topics": ["Cryptocurrency"], "updated_at": "2026-10-21T22:28:09.000Z"}, {"id": "2112602584293027909", "domain": "商业", "title_en": "tZERO Gains CFTC Approval for Derivatives Clearing", "title_zh": "tZERO 获 CFTC 批准开展衍生品清算", "hook_en": "tZERO just hit a major milestone, earning U.S. regulatory green light to clear derivatives alongside its blockchain-powered securities services.", "hook_zh": "tZERO 迎来重要里程碑：在区块链证券服务之外，获得美国监管批准开展衍生品清算。", "summary_en": "tZERO's subsidiary, tZERO DCO, LLC, received CFTC approval on October 16, 2026, to operate as a registered Derivatives Clearing Organization, expanding into fully collateralized futures, options, and swaps. This builds on their existing brokerage, trading, and custody services supporting Stellar, XDC Network, and Algorand blockchains. CEO Alan Konevsky called it a step toward tokenizing Wall Street, backed by over 100 patents and clients like Goldman Sachs, while Chief Legal Officer Vanessa Savino described it as a pinnacle in their licensing journey. The move strengthens regulated infrastructure linking traditional finance with blockchain for institutional clients.", "summary_zh": "tZERO 子公司 tZERO DCO, LLC 于 2026 年 10 月 16 日获 CFTC 批准，成为注册衍生品清算组织，业务扩展至全额担保的期货、期权与互换。此举建立在其已有经纪、交易与托管服务之上，并支持 Stellar、XDC Network、Algorand 等区块链。CEO Alan Konevsky 称这是迈向「华尔街代币化」的一步，公司拥有逾 100 项专利及高盛等客户；首席法务官 Vanessa Savino 则形容其为牌照征程的高峰。此举强化了连接传统金融与区块链、服务机构客户的受监管基础设施。", "body_en": "tZERO Gains CFTC Approval for Derivatives Clearing.\n\ntZERO just hit a major milestone, earning U.S. regulatory green light to clear derivatives alongside its blockchain-powered securities services.\n\ntZERO's subsidiary, tZERO DCO, LLC, received CFTC approval on October 16, 2026, to operate as a registered Derivatives Clearing Organization, expanding into fully collateralized futures, options, and swaps. This builds on their existing brokerage, trading, and custody services supporting Stellar, XDC Network, and Algorand blockchains.\n\nCEO Alan Konevsky called it a step toward tokenizing Wall Street, backed by over 100 patents and clients like Goldman Sachs, while Chief Legal Officer Vanessa Savino described it as a pinnacle in their licensing journey. The move strengthens regulated infrastructure linking traditional finance with blockchain for institutional clients.", "body_zh": "tZERO 获 CFTC 批准开展衍生品清算。\n\ntZERO 迎来重要里程碑：在区块链证券服务之外，获得美国监管批准开展衍生品清算。\n\ntZERO 子公司 tZERO DCO, LLC 于 2026 年 10 月 16 日获 CFTC 批准，成为注册衍生品清算组织，业务扩展至全额担保的期货、期权与互换。此举建立在其已有经纪、交易与托管服务之上，并支持 Stellar、XDC Network、Algorand 等区块链。\n\nCEO Alan Konevsky 称这是迈向「华尔街代币化」的一步，公司拥有逾 100 项专利及高盛等客户；首席法务官 Vanessa Savino 则形容其为牌照征程的高峰。此举强化了连接传统金融与区块链、服务机构客户的受监管基础设施。", "url": "https://x.com/i/trending/2112602584293027909", "category": "News", "topics": ["Cryptocurrency"], "updated_at": "2026-10-20T17:57:59.000Z"}, {"id": "2112796521959985524", "domain": "商业", "title_en": "America's Finance Hits Record-Breaking Pace with Mega-Deals", "title_zh": "美国资本市场连创纪录：巨额IPO与债券齐发", "hook_en": "From SpaceX's massive IPO to SoftBank's record junk-bond sale, U.S. markets just powered through an eye-popping wave of financial feats.", "hook_zh": "从 SpaceX 超大规模 IPO 到软银创纪录的垃圾债发行，美国市场正掀起一波令人瞩目的融资潮。", "summary_en": "The Economist highlighted a stunning lineup of achievements, including the biggest IPO ever from SpaceX, huge equity raises by Google and others, OpenAI's private funding, Broadcom's debt deal, Amazon's bond issuance, the first trillion-dollar ETF, and Berkshire Hathaway's cash pile. SoftBank recently sealed the largest corporate junk-bond offering on record, raising over $11 billion for AI investments amid a surge in new markets for compute and predictions. Observers celebrated this resilience as proof of America's unmatched capital markets strength, with comments hailing its bottomless appetite for innovation and ability to sideline setbacks.", "summary_zh": "《经济学人》梳理了一系列里程碑：SpaceX 完成史上最大 IPO，谷歌等巨头大幅增发股权，OpenAI 继续私募融资，博通债务交易、亚马逊发债、首只万亿美元 ETF 以及伯克希尔庞大现金储备也同台亮相。软银近日完成有史以来最大规模公司垃圾债发行，筹资逾 110 亿美元投入 AI。观察者认为，这印证了美国资本市场的深度与对创新的吸纳能力。", "body_en": "America's Finance Hits Record-Breaking Pace with Mega-Deals.\n\nFrom SpaceX's massive IPO to SoftBank's record junk-bond sale, U.S. markets just powered through an eye-popping wave of financial feats.\n\nThe Economist highlighted a stunning lineup of achievements, including the biggest IPO ever from SpaceX, huge equity raises by Google and others, OpenAI's private funding, Broadcom's debt deal, Amazon's bond issuance, the first trillion-dollar ETF, and Berkshire Hathaway's cash pile.\n\nSoftBank recently sealed the largest corporate junk-bond offering on record, raising over $11 billion for AI investments amid a surge in new markets for compute and predictions. Observers celebrated this resilience as proof of America's unmatched capital markets strength, with comments hailing its bottomless appetite for innovation and ability to sideline setbacks.", "body_zh": "美国资本市场连创纪录：巨额IPO与债券齐发。\n\n从 SpaceX 超大规模 IPO 到软银创纪录的垃圾债发行，美国市场正掀起一波令人瞩目的融资潮。\n\n《经济学人》梳理了一系列里程碑：SpaceX 完成史上最大 IPO，谷歌等巨头大幅增发股权，OpenAI 继续私募融资，博通债务交易、亚马逊发债、首只万亿美元 ETF 以及伯克希尔庞大现金储备也同台亮相。软银近日完成有史以来最大规模公司垃圾债发行，筹资逾 110 亿美元投入 AI。\n\n观察者认为，这印证了美国资本市场的深度与对创新的吸纳能力。", "url": "https://x.com/i/trending/2112796521959985524", "category": "News", "topics": ["Business & Finance"], "updated_at": "2026-10-21T06:46:48.000Z"}, {"id": "2112566578415849780", "domain": "商业", "title_en": "Copper Supply Shortfall Looms from 2028 Amid Surging Demand", "title_zh": "报告预警：铜供应短缺或自 2028 年起加剧", "hook_en": "Copper powers electric vehicles, grids, and AI data centers, but a new report warns of massive shortages starting in 2028 as supply struggles to keep up.", "hook_zh": "铜支撑电动车、电网与 AI 数据中心，但新报告警告自 2028 年起可能出现大规模短缺，供应跟不上需求。", "summary_en": "BloombergNEF projects copper demand jumping 61% to 46 million tonnes by 2050, driven by electric transport needing 11.4 million tonnes, while supply deficits could hit 20 million tonnes without new investments. Chile, the top producer with 180 million tonnes in reserves, faces slumping output from aging mines, low ore grades, weather, and accidents—potentially dropping to 5 million tonnes by 2026, the lowest in over 20 years. Prices have surged to $14,500 per tonne, with banks forecasting further rises, though closing the gap requires $332 billion and 17 years per new mine.", "summary_zh": "BloombergNEF 预计到 2050 年铜需求将跃升 61% 至 4600 万吨，其中电动交通约需 1140 万吨；若无新增投资，供应缺口或达 2000 万吨。全球最大生产国智利储量约 1.8 亿吨，却因矿山老化、品位下降、天气与事故导致产量下滑，2026 年或降至约 500 万吨——二十多年来最低。铜价已升至每吨约 1.45 万美元，银行预期仍将上行；填补缺口据估需约 3320 亿美元，新矿平均周期约 17 年。", "body_en": "Copper Supply Shortfall Looms from 2028 Amid Surging Demand.\n\nCopper powers electric vehicles, grids, and AI data centers, but a new report warns of massive shortages starting in 2028 as supply struggles to keep up.\n\nBloombergNEF projects copper demand jumping 61% to 46 million tonnes by 2050, driven by electric transport needing 11.4 million tonnes, while supply deficits could hit 20 million tonnes without new investments.\n\nChile, the top producer with 180 million tonnes in reserves, faces slumping output from aging mines, low ore grades, weather, and accidents—potentially dropping to 5 million tonnes by 2026, the lowest in over 20 years. Prices have surged to $14,500 per tonne, with banks forecasting further rises, though closing the gap requires $332 billion and 17 years per new mine.", "body_zh": "报告预警：铜供应短缺或自 2028 年起加剧。\n\n铜支撑电动车、电网与 AI 数据中心，但新报告警告自 2028 年起可能出现大规模短缺，供应跟不上需求。\n\nBloombergNEF 预计到 2050 年铜需求将跃升 61% 至 4600 万吨，其中电动交通约需 1140 万吨；若无新增投资，供应缺口或达 2000 万吨。\n\n全球最大生产国智利储量约 1.8 亿吨，却因矿山老化、品位下降、天气与事故导致产量下滑，2026 年或降至约 500 万吨——二十多年来最低。铜价已升至每吨约 1.45 万美元，银行预期仍将上行；填补缺口据估需约 3320 亿美元，新矿平均周期约 17 年。", "url": "https://x.com/i/trending/2112566578415849780", "category": "News", "topics": ["Business & Finance"], "updated_at": "2026-10-20T15:35:06.000Z"}, {"id": "2112795003680342391", "domain": "商业", "title_en": "S&P 500's Top 15 Stocks Hit Record 46.7% Share", "title_zh": "标准普尔500指数前15大股票创下46.7%的份额纪录", "hook_en": "A handful of tech giants now steer the entire S&P 500, with Nvidia alone claiming 7.5% of the index's value. Everyday investors in broad funds might not realize how much they're riding on these leaders.", "hook_zh": "少数科技巨头现在掌控着整个标准普尔500指数，仅英伟达就占该指数价值的7.5%。广义基金的日常投资者可能没有意识到他们对这些领导者的依赖程度。", "summary_en": "The 15 largest S&P 500 stocks account for a record 46.7% of the index's total market value, far exceeding the 27.2% seen at the 2000 dot-com peak. Nvidia tops the list at 7.5%, followed by Apple at 7.1%, Alphabet at 5.9%, and Microsoft at 5.6%, with these four alone making up 26.1%. The top five equal the market cap of the bottom 434 companies, prompting market watchers to question diversification in popular index funds and ETFs. While some highlight the leaders' strong cash flows, others note that any slowdown could hit passive portfolios hard.", "summary_zh": "15只最大的标准普尔500指数股票占该指数总市值的46.7% ，创下历史新高，远远超过2000年互联网泡沫高峰时的27.2%。英伟达以7.5%位居榜首，其次是苹果7.1% ， Alphabet 5.9% ，微软5.6% ，仅这四家就占26.1%。前五名的市值等于底部434家公司的市值，促使市场观察人士质疑热门指数基金和ETF的多元化。 虽然有些人强调了领导者的强劲现金流，但其他人则指出，任何放缓都可能对被动投资组合造成严重打击。", "body_en": "A handful of tech giants now steer the entire S&P 500, with Nvidia alone claiming 7.5% of the index's value. Everyday investors in broad funds might not realize how much they're riding on these leaders.\n\nThe 15 largest S&P 500 stocks account for a record 46.7% of the index's total market value, far exceeding the 27.2% seen at the 2000 dot-com peak. Nvidia tops the list at 7.5%, followed by Apple at 7.1%, Alphabet at 5.9%, and Microsoft at 5.6%, with these four alone making up 26.1%.\n\nThe top five equal the market cap of the bottom 434 companies, prompting market watchers to question diversification in popular index funds and ETFs. While some highlight the leaders' strong cash flows, others note that any slowdown could hit passive portfolios hard.", "body_zh": "少数科技巨头现在掌控着整个标准普尔500指数，仅英伟达就占该指数价值的7.5%。广义基金的日常投资者可能没有意识到他们对这些领导者的依赖程度。\n\n15只最大的标准普尔500指数股票占该指数总市值的46.7% ，创下历史新高，远远超过2000年互联网泡沫高峰时的27.2%。英伟达以7.5%位居榜首，其次是苹果7.1% ， Alphabet 5.9% ，微软5.6% ，仅这四家就占26.1%。\n\n前五名的市值等于底部434家公司的市值，促使市场观察人士质疑热门指数基金和ETF的多元化。虽然有些人强调了领导者的强劲现金流，但其他人则指出，任何放缓都可能对被动投资组合造成严重打击。", "url": "https://x.com/i/trending/2112795003680342391", "category": "News", "topics": ["Stocks"], "updated_at": "2026-10-21T06:39:54.000Z"}, {"id": "2112795004678676841", "domain": "商业", "title_en": "Indian Markets Slide as Small Caps Tumble, Anger Targets Finance Minister", "title_zh": "印度中小盘暴跌，市场怒火指向财长", "hook_en": "Investors watched in frustration as small and mid-cap stocks plunged on October 21, 2026, fueling direct calls for Finance Minister Nirmala Sitharaman to step down.", "hook_zh": "2026 年 10 月 21 日印度中小盘股急挫，投资者沮丧情绪高涨，社交媒体上出现要求财长西塔拉曼辞职的呼声。", "summary_en": "The Nifty 50 closed at 22,811.35, down 0.34%, and Sensex at 73,709.69, off 0.19%, but small-cap indices dropped over 2.3% with BSE companies losing Rs 11 lakh crore in value over two days. High leverage in small caps, now 49% of margin trading, amplified the sell-off amid rising crude oil prices, foreign selling, and profit booking. Social media users vented anger with posts like 'Nirmala Sitharaman please #resign. You have destroyed Indian Capital market,' while Sitharaman has defended the economy's fundamentals despite liquidity concerns.", "summary_zh": "Nifty 50 收于 22811.35 点跌 0.34%，Sensex 报 73709.69 点跌 0.19%，但小盘指数跌逾 2.3%，孟买证交所公司两日市值蒸发约 11 万亿卢比。小盘股高杠杆——保证金交易占比约 49%——在油价上涨、外资抛售与获利了结中放大跌幅。社交平台出现「请西塔拉曼辞职，你毁掉了印度资本市场」等帖文；财长则继续强调基本面稳健，并谈及流动性问题。", "body_en": "Indian Markets Slide as Small Caps Tumble, Anger Targets Finance Minister.\n\nInvestors watched in frustration as small and mid-cap stocks plunged on October 21, 2026, fueling direct calls for Finance Minister Nirmala Sitharaman to step down.\n\nThe Nifty 50 closed at 22,811.35, down 0.34%, and Sensex at 73,709.69, off 0.19%, but small-cap indices dropped over 2.3% with BSE companies losing Rs 11 lakh crore in value over two days. High leverage in small caps, now 49% of margin trading, amplified the sell-off amid rising crude oil prices, foreign selling, and profit booking.\n\nSocial media users vented anger with posts like 'Nirmala Sitharaman please #resign. You have destroyed Indian Capital market,' while Sitharaman has defended the economy's fundamentals despite liquidity concerns.", "body_zh": "印度中小盘暴跌，市场怒火指向财长。\n\n2026 年 10 月 21 日印度中小盘股急挫，投资者沮丧情绪高涨，社交媒体上出现要求财长西塔拉曼辞职的呼声。\n\nNifty 50 收于 22811.35 点跌 0.34%，Sensex 报 73709.69 点跌 0.19%，但小盘指数跌逾 2.3%，孟买证交所公司两日市值蒸发约 11 万亿卢比。\n\n小盘股高杠杆——保证金交易占比约 49%——在油价上涨、外资抛售与获利了结中放大跌幅。社交平台出现「请西塔拉曼辞职，你毁掉了印度资本市场」等帖文；财长则继续强调基本面稳健，并谈及流动性问题。", "url": "https://x.com/i/trending/2112795004678676841", "category": "News", "topics": ["Business & Finance", "Stocks"], "updated_at": "2026-10-21T13:45:53.000Z"}, {"id": "2112781652112064634", "domain": "商业", "title_en": "BNB Standard Rings Nasdaq Bell After Rebrand and New CEO", "title_zh": "BNB Standard在品牌重塑和新任首席执行官之后响起纳斯达克钟声", "hook_en": "On October 26, BNB Standard Corporation will ring the Nasdaq Opening Bell in Times Square, with CEO Alex Odagiu leading the ceremony alongside executives and partners. Binance co-founder CZ marked the moment with double bell emojis.", "hook_zh": "10月26日， BNB Standard Corporation将在时代广场敲响纳斯达克开盘钟，首席执行官Alex Odagiu将与高管和合作伙伴一起主持仪式。币安联合创始人CZ用双铃表情符号标志着这一时刻。", "summary_en": "The Nasdaq-listed company, ticker $BNC, shifted from CEA Industries to focus on its massive BNB treasury, the world's largest corporate holding, after community votes chose the 'BNB Standard' name with 47% support from nearly 5,800 X polls. New CEO Alex Odagiu, with Goldman Sachs background, started October 19, as BNB Chain burned 1.6 million BNB worth $1.2 billion to cut supply toward 100 million. BNB Standard plans its own validator node on BNB Chain, bridging traditional finance and crypto after raising $500 million in its 2025 pivot.", "summary_zh": "这家在纳斯达克上市的公司股票代码为$ BNC ，在社区投票选择了“BNB Standard”名称后，从CEA Industries转向专注于其庞大的BNB金库，这是全球最大的公司控股公司，该公司在近5800项X民意调查中获得了47%的支持。新任首席执行官亚历克斯·奥达吉乌（ Alex Odagiu ）拥有高盛（ Goldman Sachs ）的背景，于10月19日开始， BNB Chain烧毁了160万BNB ，价值12亿美元，将供应量削减至1亿。 BNB标准计划在BNB Chain上建立自己的验证器节点，在2025年的支点上筹集了5亿美元后，将传统金融和加密桥接起来。", "body_en": "On October 26, BNB Standard Corporation will ring the Nasdaq Opening Bell in Times Square, with CEO Alex Odagiu leading the ceremony alongside executives and partners. Binance co-founder CZ marked the moment with double bell emojis.\n\nThe Nasdaq-listed company, ticker $BNC, shifted from CEA Industries to focus on its massive BNB treasury, the world's largest corporate holding, after community votes chose the 'BNB Standard' name with 47% support from nearly 5,800 X polls.\n\nNew CEO Alex Odagiu, with Goldman Sachs background, started October 19, as BNB Chain burned 1.6 million BNB worth $1.2 billion to cut supply toward 100 million. BNB Standard plans its own validator node on BNB Chain, bridging traditional finance and crypto after raising $500 million in its 2025 pivot.", "body_zh": "10月26日， BNB Standard Corporation将在时代广场敲响纳斯达克开盘钟，首席执行官Alex Odagiu将与高管和合作伙伴一起主持仪式。币安联合创始人CZ用双铃表情符号标志着这一时刻。\n\n这家在纳斯达克上市的公司股票代码为$ BNC ，在社区投票选择了“BNB Standard”名称后，从CEA Industries转向专注于其庞大的BNB金库，这是全球最大的公司控股公司，该公司在近5800项X民意调查中获得了47%的支持。\n\n新任首席执行官亚历克斯·奥达吉乌（ Alex Odagiu ）拥有高盛（ Goldman Sachs ）的背景，于10月19日开始， BNB Chain烧毁了160万BNB ，价值12亿美元，将供应量削减至1亿。BNB标准计划在BNB Chain上建立自己的验证器节点，在2025年的支点上筹集了5亿美元后，将传统金融和加密桥接起来。", "url": "https://x.com/i/trending/2112781652112064634", "category": "News", "topics": ["Business & Finance", "Cryptocurrency"], "updated_at": "2026-10-21T08:28:42.000Z"}, {"id": "2112915461406957899", "domain": "商业", "title_en": "Indian Markets Dip Despite Heavy Institutional Buying", "title_zh": "尽管机构购买量很大，但印度市场仍在下跌", "hook_en": "Institutions poured in over ₹2,600 crore, yet the Nifty and Sensex still closed lower. Traders scratched their heads, asking 'Who sold?'", "hook_zh": "机构涌入超过2600亿₹ ，但Nifty和Sensex的收盘价仍然较低。交易员挠了挠头，问道： “谁卖的？”", "summary_en": "On October 21, 2026, FIIs net bought ₹1,022 crore and DIIs added ₹1,614 crore, but the Nifty 50 fell 0.34% to 22,811.35 and Sensex dropped 0.19% to 73,709.69 after an early surge reversed into heavy selling. Market breadth turned negative across segments, with observers pointing to possible retail profit-booking, rising crude oil above $110 a barrel, or unwinding MTF positions amid the Jio Platforms IPO launch. The day highlighted how retail flows and external pressures can outweigh institutional support in a single session.", "summary_zh": "2026年10月21日， FIIS净买入₹ 1,022亿卢比， DIIS增加了₹ 1,614亿卢比，但Nifty 50下跌0.34%至22,811.35 ， Sensex下跌0.19%至73,709.69 ，此前一轮激增逆转为大幅抛售。各细分市场的市场广度转为负面，观察人士指出，在Jio Platforms首次公开募股期间，可能出现零售利润预订、原油价格上涨至每桶110 $以上，或MTF头寸平仓。 这一天突出了零售流量和外部压力如何在一次会议中超过机构支持。", "body_en": "Indian Markets Dip Despite Heavy Institutional Buying.\n\nInstitutions poured in over ₹2,600 crore, yet the Nifty and Sensex still closed lower. Traders scratched their heads, asking 'Who sold?'\n\nOn October 21, 2026, FIIs net bought ₹1,022 crore and DIIs added ₹1,614 crore, but the Nifty 50 fell 0.34% to 22,811.35 and Sensex dropped 0.19% to 73,709.69 after an early surge reversed into heavy selling.\n\nMarket breadth turned negative across segments, with observers pointing to possible retail profit-booking, rising crude oil above $110 a barrel, or unwinding MTF positions amid the Jio Platforms IPO launch. The day highlighted how retail flows and external pressures can outweigh institutional support in a single session.", "body_zh": "机构涌入超过2600亿₹ ，但Nifty和Sensex的收盘价仍然较低。交易员挠了挠头，问道： “谁卖的？”\n\n2026年10月21日， FIIS净买入₹ 1,022亿卢比， DIIS增加了₹ 1,614亿卢比，但Nifty 50下跌0.34%至22,811.35 ， Sensex下跌0.19%至73,709.69 ，此前一轮激增逆转为大幅抛售。\n\n各细分市场的市场广度转为负面，观察人士指出，在Jio Platforms首次公开募股期间，可能出现零售利润预订、原油价格上涨至每桶110 $以上，或MTF头寸平仓。这一天突出了零售流量和外部压力如何在一次会议中超过机构支持。", "url": "https://x.com/i/trending/2112915461406957899", "category": "News", "topics": ["Business & Finance", "Stocks"], "updated_at": "2026-10-21T18:35:48.000Z"}, {"id": "2112948932623978868", "domain": "商业", "title_en": "India's Core Industries Hit 30-Month High with 7.9% Growth in September 2026", "title_zh": "印度核心产业在2026年9月创下30个月新高，增长7.9%", "hook_en": "India's factories and mines powered up in September, delivering their strongest output in over two years.", "hook_zh": "印度的工厂和矿山在9月份上电，实现了两年来最强劲的产量。", "summary_en": "Core industries grew 7.9% year-on-year, up from a revised 5.9% in August, with the index reaching 118.3. Iron ore led with an 18.4% surge, followed by electricity at 11.4%, coal at 10.7%, refinery products at 10.3%, cement at 9.8%, and steel at 4.9%. While fertiliser dropped 11.7%, natural gas fell 4.6%, and crude oil declined 1.4%, the overall April-September growth hit 5.1%, more than double last year's pace. This rebound signals building industrial strength ahead of broader production data.", "summary_zh": "核心产业同比增长7.9% ，高于8月份修订后的5.9% ，指数达到118.3。铁矿石激增18.4% ，其次是电力11.4% ，煤炭10.7% ，炼油产品10.3% ，水泥9.8% ，钢铁4.9%。虽然化肥下降了11.7% ，天然气下降了4.6% ，原油下降了1.4% ，但4月至9月的整体增长率达到了5.1% ，是去年的两倍多。 这一反弹标志着在更广泛的生产数据之前建立了工业实力。", "body_en": "India's Core Industries Hit 30-Month High with 7.9% Growth in September 2026.\n\nIndia's factories and mines powered up in September, delivering their strongest output in over two years.\n\nCore industries grew 7.9% year-on-year, up from a revised 5.9% in August, with the index reaching 118.3. Iron ore led with an 18.4% surge, followed by electricity at 11.4%, coal at 10.7%, refinery products at 10.3%, cement at 9.8%, and steel at 4.9%.\n\nWhile fertiliser dropped 11.7%, natural gas fell 4.6%, and crude oil declined 1.4%, the overall April-September growth hit 5.1%, more than double last year's pace. This rebound signals building industrial strength ahead of broader production data.", "body_zh": "印度的工厂和矿山在9月份上电，实现了两年来最强劲的产量。\n\n核心产业同比增长7.9% ，高于8月份修订后的5.9% ，指数达到118.3。铁矿石激增18.4% ，其次是电力11.4% ，煤炭10.7% ，炼油产品10.3% ，水泥9.8% ，钢铁4.9%。\n\n虽然化肥下降了11.7% ，天然气下降了4.6% ，原油下降了1.4% ，但4月至9月的整体增长率达到了5.1% ，是去年的两倍多。这一反弹标志着在更广泛的生产数据之前建立了工业实力。", "url": "https://x.com/i/trending/2112948932623978868", "category": "News", "topics": ["Business & Finance"], "updated_at": "2026-10-21T16:58:30.000Z"}, {"id": "2113026675130974423", "domain": "商业", "title_en": "Chainlink Q3 Update Shows $15B Migration and TradFi Ties", "title_zh": "Chainlink 三季度：150 亿美元迁移与传统金融合作升温", "hook_en": "Chainlink just shared its Q3 wins, from $15 billion flowing into its protocol to new links with giants like Swift and DTCC. It's a sign institutions are warming to blockchain for real-world assets.", "hook_zh": "Chainlink 公布三季度进展：协议流入约 150 亿美元，并与 Swift、DTCC 等建立更多联系，机构对链上真实世界资产兴趣上升。", "summary_en": "Chainlink's momentum update highlighted the CCIP 2.0 launch, over $15 billion migrating to the protocol, and $140 billion secured in onchain finance. The company pointed to growing partnerships with traditional finance players like DTCC and Swift, plus enterprise integrations with Infosys and Robinhood, and policy efforts in the U.S., UK, and Hong Kong. Charles Schwab's head of crypto research called Chainlink a pure play for RWA tokenization exposure, while analyst Andrew McCormick noted these institutional ties could bring efficient markets to everyday investors. Community observers see the migrations and pilots as blockchain shifting into core financial systems.", "summary_zh": "动量更新强调 CCIP 2.0 上线、逾 150 亿美元资产迁入协议，以及链上金融约 1400 亿美元的保障规模。公司点名与 DTCC、Swift 等传统金融合作，以及 Infosys、Robinhood 等企业集成，并在美、英、港推进政策沟通。嘉信加密研究负责人称其为 RWA 代币化敞口的纯正标的；分析师 Andrew McCormick 认为机构纽带有望把更高效市场带给普通投资者。社区观察者将迁移与试点视为区块链进入核心金融系统的信号。", "body_en": "Chainlink Q3 Update Shows $15B Migration and TradFi Ties.\n\nChainlink just shared its Q3 wins, from $15 billion flowing into its protocol to new links with giants like Swift and DTCC. It's a sign institutions are warming to blockchain for real-world assets.\n\nChainlink's momentum update highlighted the CCIP 2.0 launch, over $15 billion migrating to the protocol, and $140 billion secured in onchain finance. The company pointed to growing partnerships with traditional finance players like DTCC and Swift, plus enterprise integrations with Infosys and Robinhood, and policy efforts in the U.S., UK, and Hong Kong.\n\nCharles Schwab's head of crypto research called Chainlink a pure play for RWA tokenization exposure, while analyst Andrew McCormick noted these institutional ties could bring efficient markets to everyday investors. Community observers see the migrations and pilots as blockchain shifting into core financial systems.", "body_zh": "Chainlink 三季度：150 亿美元迁移与传统金融合作升温。\n\nChainlink 公布三季度进展：协议流入约 150 亿美元，并与 Swift、DTCC 等建立更多联系，机构对链上真实世界资产兴趣上升。\n\n动量更新强调 CCIP 2.0 上线、逾 150 亿美元资产迁入协议，以及链上金融约 1400 亿美元的保障规模。公司点名与 DTCC、Swift 等传统金融合作，以及 Infosys、Robinhood 等企业集成，并在美、英、港推进政策沟通。\n\n嘉信加密研究负责人称其为 RWA 代币化敞口的纯正标的；分析师 Andrew McCormick 认为机构纽带有望把更高效市场带给普通投资者。社区观察者将迁移与试点视为区块链进入核心金融系统的信号。", "url": "https://x.com/i/trending/2113026675130974423", "category": "News", "topics": ["Cryptocurrency"], "updated_at": "2026-10-21T22:03:18.000Z"}, {"id": "2112849951126589933", "domain": "商业", "title_en": "French Bond Yields Hit 5% Amid Protests and Debt Worries", "title_zh": "法国国债收益率触及 5%，抗议与债务忧虑交织", "hook_en": "Investors watched nervously as France's 10-year bond yield crossed 5% for the first time since 2002, fueled by riots in the streets and a parliament locked in budget battles.", "hook_zh": "法国十年期国债收益率自 2002 年来首次越过 5%，街头骚乱与议会预算僵局令投资者紧张。", "summary_en": "The benchmark yield on French government bonds briefly topped 5% on Wednesday before easing to 4.98%, up sharply from 3.2% in late February, as political gridlock, protests over living costs and education cuts, and public debt near 119% of GDP rattled markets. Lawmakers struggle to pass a 2027 budget with proposed €54 billion in spending cuts, while the country faces an EU deficit procedure and a Moody's rating review Friday that could bring a downgrade. Higher yields threaten to lift mortgage rates and push the government's interest bill to €91 billion next year, signaling eroding confidence in France's fiscal path despite its strong social safety net.", "summary_zh": "周三基准收益率一度站上 5%，随后回落至 4.98%；相对 2 月末约 3.2% 明显抬升。政治僵局、生活成本与教育削减引发的抗议，以及接近 GDP 119% 的公共债务冲击市场。议员艰难推进含约 540 亿欧元支出削减的 2027 预算，法国还面临欧盟赤字程序，穆迪周五或下调评级。更高收益率可能推升房贷成本，并把明年政府利息支出抬向约 910 亿欧元，显示财政路径信心受挫，尽管社保网络仍强。", "body_en": "French Bond Yields Hit 5% Amid Protests and Debt Worries.\n\nInvestors watched nervously as France's 10-year bond yield crossed 5% for the first time since 2002, fueled by riots in the streets and a parliament locked in budget battles.\n\nThe benchmark yield on French government bonds briefly topped 5% on Wednesday before easing to 4.98%, up sharply from 3.2% in late February, as political gridlock, protests over living costs and education cuts, and public debt near 119% of GDP rattled markets.\n\nLawmakers struggle to pass a 2027 budget with proposed €54 billion in spending cuts, while the country faces an EU deficit procedure and a Moody's rating review Friday that could bring a downgrade. Higher yields threaten to lift mortgage rates and push the government's interest bill to €91 billion next year, signaling eroding confidence in France's fiscal path despite its strong social safety net.", "body_zh": "法国国债收益率触及 5%，抗议与债务忧虑交织。\n\n法国十年期国债收益率自 2002 年来首次越过 5%，街头骚乱与议会预算僵局令投资者紧张。\n\n周三基准收益率一度站上 5%，随后回落至 4.98%；相对 2 月末约 3.2% 明显抬升。政治僵局、生活成本与教育削减引发的抗议，以及接近 GDP 119% 的公共债务冲击市场。\n\n议员艰难推进含约 540 亿欧元支出削减的 2027 预算，法国还面临欧盟赤字程序，穆迪周五或下调评级。更高收益率可能推升房贷成本，并把明年政府利息支出抬向约 910 亿欧元，显示财政路径信心受挫，尽管社保网络仍强。", "url": "https://x.com/i/trending/2112849951126589933", "category": "News", "topics": ["Business & Finance"], "updated_at": "2026-10-21T19:44:26.000Z"}, {"id": "2112637283748966756", "domain": "商业", "title_en": "SEC Clears Evernorth Prospectus for Potential $132 Million XRP Raise", "title_zh": "SEC 核准 Evernorth 招股说明书，或解锁约 1.32 亿美元加仓 XRP", "hook_en": "Evernorth Holdings just got the SEC's green light to register shares from warrants, potentially unlocking $132 million to grow its XRP stash even bigger.", "hook_zh": "Evernorth Holdings 获美证交会绿灯，可注册认股权证对应股份，有望筹资约 1.32 亿美元继续囤积 XRP。", "summary_en": "The U.S. Securities and Exchange Commission approved Evernorth's prospectus filing on around October 19, 2026, allowing up to 11.5 million shares tied to $11.50 warrants to be registered. If exercised fully, it could bring in about $132 million in proceeds, which the Nasdaq-listed company (ticker XRPN since mid-October) plans to use for building its concentrated XRP holdings. Crypto enthusiasts celebrated the move as a key step for XRP accumulation, while the firm warns of risks in the volatile digital asset space. This builds on Evernorth's public debut, partnerships like with Ripple, and active trading of its shares and warrants.", "summary_zh": "SEC 约在 10 月 19 日核准相关招股说明书，允许注册与 11.50 美元认股权证挂钩的最多约 1150 万股。若全部行权，募资约 1.32 亿美元，纳斯达克上市公司（中旬起代码 XRPN）拟用于集中增持 XRP。加密社区视之为 XRP 囤积关键一步；公司亦警示数字资产波动风险。此举承接其公开市场亮相、与瑞波等合作，以及股票与权证活跃交易。", "body_en": "SEC Clears Evernorth Prospectus for Potential $132 Million XRP Raise.\n\nEvernorth Holdings just got the SEC's green light to register shares from warrants, potentially unlocking $132 million to grow its XRP stash even bigger.\n\nThe U.S. Securities and Exchange Commission approved Evernorth's prospectus filing on around October 19, 2026, allowing up to 11.5 million shares tied to $11.50 warrants to be registered.\n\nIf exercised fully, it could bring in about $132 million in proceeds, which the Nasdaq-listed company (ticker XRPN since mid-October) plans to use for building its concentrated XRP holdings. Crypto enthusiasts celebrated the move as a key step for XRP accumulation, while the firm warns of risks in the volatile digital asset space. This builds on Evernorth's public debut, partnerships like with Ripple, and active trading of its shares and warrants.", "body_zh": "SEC 核准 Evernorth 招股说明书，或解锁约 1.32 亿美元加仓 XRP。\n\nEvernorth Holdings 获美证交会绿灯，可注册认股权证对应股份，有望筹资约 1.32 亿美元继续囤积 XRP。\n\nSEC 约在 10 月 19 日核准相关招股说明书，允许注册与 11.50 美元认股权证挂钩的最多约 1150 万股。若全部行权，募资约 1.32 亿美元，纳斯达克上市公司（中旬起代码 XRPN）拟用于集中增持 XRP。\n\n加密社区视之为 XRP 囤积关键一步；公司亦警示数字资产波动风险。此举承接其公开市场亮相、与瑞波等合作，以及股票与权证活跃交易。", "url": "https://x.com/i/trending/2112637283748966756", "category": "News", "topics": ["Cryptocurrency"], "updated_at": "2026-10-21T17:08:08.000Z"}, {"id": "2112431560116826201", "domain": "商业", "title_en": "Former Finance Secretary Sparks Debate on India's GDP in Dollar Terms", "title_zh": "前财长用美元口径印度 GDP 增速引爆争论", "hook_en": "Subhash Chandra Garg, ex-Finance Secretary, shared IMF data showing India's GDP growth in current US dollars at just 3.87%—well below the world average and China's rate—prompting a lively back-and-forth online.", "hook_zh": "前财政秘书 Subhash Chandra Garg 援引 IMF 数据称，印度以现价美元计 GDP 增速仅约 3.87%，低于全球均值与中国，引发网上激烈讨论。", "summary_en": "Garg contrasted this with India's real GDP growth of around 7% in local terms, arguing the dollar measure gives a fuller picture often missed in domestic talks. Critics say focusing on dollars mixes in currency fluctuations and overlooks actual output, while supporters like Sanjay Jha tie it to investor outflows exceeding Rs 3 lakh crore from Indian stocks in 2026 and job concerns. The IMF's October 2026 outlook projects India's real growth at 7%, but nominal dollar GDP lags partly due to rupee depreciation, highlighting tensions between real output metrics and global investor views.", "summary_zh": "Garg 将此与本地口径约 7% 的实际 GDP 增速对照，认为美元口径常被国内讨论忽略却更全面。批评者称盯住美元会混入汇率波动、忽视真实产出；支持者如 Sanjay Jha 则联系到 2026 年印度股市外资流出逾 3 万亿卢比与就业担忧。IMF 10 月展望仍预计印度实际增速约 7%，但名义美元 GDP 因卢比贬值等因素落后，凸显产出指标与全球投资者视角之间的张力。", "body_en": "Former Finance Secretary Sparks Debate on India's GDP in Dollar Terms.\n\nSubhash Chandra Garg, ex-Finance Secretary, shared IMF data showing India's GDP growth in current US dollars at just 3.87%—well below the world average and China's rate—prompting a lively back-and-forth online.\n\nGarg contrasted this with India's real GDP growth of around 7% in local terms, arguing the dollar measure gives a fuller picture often missed in domestic talks.\n\nCritics say focusing on dollars mixes in currency fluctuations and overlooks actual output, while supporters like Sanjay Jha tie it to investor outflows exceeding Rs 3 lakh crore from Indian stocks in 2026 and job concerns. The IMF's October 2026 outlook projects India's real growth at 7%, but nominal dollar GDP lags partly due to rupee depreciation, highlighting tensions between real output metrics and global investor views.", "body_zh": "前财长用美元口径印度 GDP 增速引爆争论。\n\n前财政秘书 Subhash Chandra Garg 援引 IMF 数据称，印度以现价美元计 GDP 增速仅约 3.87%，低于全球均值与中国，引发网上激烈讨论。\n\nGarg 将此与本地口径约 7% 的实际 GDP 增速对照，认为美元口径常被国内讨论忽略却更全面。\n\n批评者称盯住美元会混入汇率波动、忽视真实产出；支持者如 Sanjay Jha 则联系到 2026 年印度股市外资流出逾 3 万亿卢比与就业担忧。IMF 10 月展望仍预计印度实际增速约 7%，但名义美元 GDP 因卢比贬值等因素落后，凸显产出指标与全球投资者视角之间的张力。", "url": "https://x.com/i/trending/2112431560116826201", "category": "News", "topics": ["Business & Finance"], "updated_at": "2026-10-20T06:36:16.000Z"}, {"id": "2112486884211650655", "domain": "中国", "title_en": "Sindh CM Secures 34 China Deals at Shanghai Conference", "title_zh": "巴基斯坦信德省首席部长在沪签下 34 项对华合作", "hook_en": "Sindh Chief Minister Syed Murad Ali Shah stood by as 34 key agreements were signed in Shanghai, unlocking fresh paths for jobs and growth back home.", "hook_zh": "信德省首席部长穆拉德·阿里·沙阿在上海见证 34 项关键协议签署，为本地就业与增长打开新路。", "summary_en": "At the Sindh Investment and Trade Conference in Shanghai on October 15, 2026, CM Shah witnessed 34 memorandums of understanding and agreements with Chinese partners—10 government-to-government and 24 business-to-business. These cover energy like Thar coal, electric vehicles, AI-driven digital transformation, agriculture, and logistics, building on successes such as power plants and wind farms in the province. The event drew 400 delegates from over 100 companies, highlighting Sindh's ports, workforce, resources, and tax incentives, while follow-up meetings in Wuhan advanced projects like climate-resilient crops and Karachi's water supply. Supporters praise the moves for fostering investment, innovation, and prosperity rooted in the 75-year Pak-China friendship.", "summary_zh": "2026 年 10 月 15 日上海举行的信德投资贸易会议上，沙阿见证与中国伙伴签署 34 份备忘录与协议，其中政府间 10 项、企业间 24 项，涵盖塔尔煤电、电动车、AI 数字化、农业与物流等。活动吸引百余家企业约 400 名代表；后续武汉会谈推进耐气候作物与卡拉奇供水等项目。支持者称这延续巴中建交 75 年的合作传统。", "body_en": "Sindh CM Secures 34 China Deals at Shanghai Conference.\n\nSindh Chief Minister Syed Murad Ali Shah stood by as 34 key agreements were signed in Shanghai, unlocking fresh paths for jobs and growth back home.\n\nAt the Sindh Investment and Trade Conference in Shanghai on October 15, 2026, CM Shah witnessed 34 memorandums of understanding and agreements with Chinese partners—10 government-to-government and 24 business-to-business. These cover energy like Thar coal, electric vehicles, AI-driven digital transformation, agriculture, and logistics, building on successes such as power plants and wind farms in the province.\n\nThe event drew 400 delegates from over 100 companies, highlighting Sindh's ports, workforce, resources, and tax incentives, while follow-up meetings in Wuhan advanced projects like climate-resilient crops and Karachi's water supply. Supporters praise the moves for fostering investment, innovation, and prosperity rooted in the 75-year Pak-China friendship.", "body_zh": "巴基斯坦信德省首席部长在沪签下 34 项对华合作。\n\n信德省首席部长穆拉德·阿里·沙阿在上海见证 34 项关键协议签署，为本地就业与增长打开新路。\n\n2026 年 10 月 15 日上海举行的信德投资贸易会议上，沙阿见证与中国伙伴签署 34 份备忘录与协议，其中政府间 10 项、企业间 24 项，涵盖塔尔煤电、电动车、AI 数字化、农业与物流等。活动吸引百余家企业约 400 名代表；后续武汉会谈推进耐气候作物与卡拉奇供水等项目。\n\n支持者称这延续巴中建交 75 年的合作传统。", "url": "https://x.com/i/trending/2112486884211650655", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-20T13:25:56.000Z"}, {"id": "2112022699237310708", "domain": "中国", "title_en": "Liangzhu Forum Opens Marking 90th Anniversary of Ancient Ruins Discovery", "title_zh": "良渚论坛开幕，纪念遗址发现 90 周年", "hook_en": "Experts from nearly 60 countries gathered in Hangzhou to celebrate 5,000-year-old Liangzhu ruins, blending ancient history with modern tech and global chats.", "hook_zh": "近 60 国专家齐聚杭州，共庆约 5000 年历史的良渚遗址。", "summary_en": "The fourth Liangzhu Forum, held October 18-20 in Zhejiang province, honors the 90th anniversary of discovering the UNESCO-listed Liangzhu ruins, evidence of an early advanced society with rice farming. Under the theme 'Bridging the Past and the Future,' it features forums, an artists' exhibition, a cultural market with Belt and Road products, and AI glasses at the museum that guide visitors using real archives. An American archaeologist on his first China trip praised the scenery and hopes to study sites, while an Australian curator noted the link between ancient Liangzhu and today's Hangzhou; young volunteers provide bilingual support amid calls for global heritage cooperation.", "summary_zh": "第四届良渚论坛以「连接过去与未来」为主题，纪念入选世界遗产的良渚遗址发现 90 周年。活动包含 AI 导览与文化交流内容，吸引多国学者参与。", "body_en": "Experts from nearly 60 countries gathered in Hangzhou to celebrate 5,000-year-old Liangzhu ruins, blending ancient history with modern tech and global chats.\n\nThe fourth Liangzhu Forum, held October 18-20 in Zhejiang province, honors the 90th anniversary of discovering the UNESCO-listed Liangzhu ruins, evidence of an early advanced society with rice farming.\n\nUnder the theme 'Bridging the Past and the Future,' it features forums, an artists' exhibition, a cultural market with Belt and Road products, and AI glasses at the museum that guide visitors using real archives. An American archaeologist on his first China trip praised the scenery and hopes to study sites, while an Australian curator noted the link between ancient Liangzhu and today's Hangzhou; young volunteers provide bilingual support amid calls for global heritage cooperation.", "body_zh": "良渚论坛开幕，纪念遗址发现 90 周年。\n\n近 60 国专家齐聚杭州，共庆约 5000 年历史的良渚遗址。\n\n第四届良渚论坛以「连接过去与未来」为主题，纪念入选世界遗产的良渚遗址发现 90 周年。活动包含 AI 导览与文化交流内容，吸引多国学者参与。", "url": "https://x.com/i/trending/2112022699237310708", "category": "News", "topics": ["Science"], "updated_at": "2026-10-20T03:21:48.000Z"}, {"id": "2112572571275370804", "domain": "中国", "title_en": "Japan Faces Yttrium Shortage, Seeks US Help Against China Curbs", "title_zh": "日本钇供应告急，寻求美方协助应对中国出口限制", "hook_en": "Japan has just months left before running out of yttrium, a vital metal for jet engines and chips, as Chinese shipments nearly halt.", "hook_zh": "用于喷气发动机与芯片的关键金属钇，中国对日发运几近停滞，日本称只剩数月库存。", "summary_en": "Yttrium oxide shipments from China to Japan have almost stopped in 2026 after tighter export restrictions, driving outside prices to $1,150 per kilogram from $6 two years ago. The shortage endangers aerospace, autos, electronics, and defense, with a Japanese official warning of world economy risks if ignored. Japan asked the US to pressure China, while Washington withheld jet engine exports to Beijing and discussed solutions in recent meetings. Allies seek substitutes and new supplies amid limited global processing outside China.", "summary_zh": "2026 年中国收紧出口限制后，氧化钇对日发运几乎停止，日本以外市场价格从两年前每公斤约 6 美元飙至 1150 美元。短缺危及航空航天、汽车、电子与国防，日方官员警告若忽视将冲击世界经济。日本请求美国向中国施压；华盛顿则暂停对北京喷气发动机出口，并在近期会谈中讨论对策。盟友正寻找替代品与新供应，因中国以外全球加工能力有限。", "body_en": "Japan Faces Yttrium Shortage, Seeks US Help Against China Curbs.\n\nJapan has just months left before running out of yttrium, a vital metal for jet engines and chips, as Chinese shipments nearly halt.\n\nYttrium oxide shipments from China to Japan have almost stopped in 2026 after tighter export restrictions, driving outside prices to $1,150 per kilogram from $6 two years ago. The shortage endangers aerospace, autos, electronics, and defense, with a Japanese official warning of world economy risks if ignored.\n\nJapan asked the US to pressure China, while Washington withheld jet engine exports to Beijing and discussed solutions in recent meetings. Allies seek substitutes and new supplies amid limited global processing outside China.", "body_zh": "日本钇供应告急，寻求美方协助应对中国出口限制。\n\n用于喷气发动机与芯片的关键金属钇，中国对日发运几近停滞，日本称只剩数月库存。\n\n2026 年中国收紧出口限制后，氧化钇对日发运几乎停止，日本以外市场价格从两年前每公斤约 6 美元飙至 1150 美元。短缺危及航空航天、汽车、电子与国防，日方官员警告若忽视将冲击世界经济。\n\n日本请求美国向中国施压；华盛顿则暂停对北京喷气发动机出口，并在近期会谈中讨论对策。盟友正寻找替代品与新供应，因中国以外全球加工能力有限。", "url": "https://x.com/i/trending/2112572571275370804", "category": "News", "topics": ["Business & Finance"], "updated_at": "2026-10-20T19:24:35.000Z"}, {"id": "2112810342728323293", "domain": "中国", "title_en": "China Replaces Billboards with Scientists' Portraits in Major Cities", "title_zh": "中国多地用科学家肖像替换地铁商业广告", "hook_en": "Rocket scientist Qian Xuesen's giant portrait now greets shoppers in a Heze mall, replacing flashy ads with faces of national heroes.", "hook_zh": "走进地铁站，巨型屏幕上是杂交水稻先驱袁隆平等科学家，而非炫目广告。这一简单替换引来关于榜样的讨论。", "summary_en": "Since August 2026, cities like Heze, Zhengzhou, and Chongqing have filled public screens in malls, metros, and plazas with portraits of scientists such as Qian Xuesen, Yuan Longping, and Tu Youyou, complete with notes on their breakthroughs in rockets, rice, and malaria drugs. Local venues made these voluntary changes, often timed for holidays to highlight achievements in science and defense. The shift has sparked online talk about honoring innovators over celebrities and what public spaces say about a society's values.", "summary_zh": "中国开始在地铁站、商场等公共大屏用著名科学家肖像替换广告，包括农学家袁隆平、因疟疾治疗获诺奖的屠呦呦、火箭专家钱学森、核物理学家邓稼先等。举措 2026 年 8 月起自山东推开，并扩展至郑州、重庆等城市，尤其在国庆等节点，企业自愿腾出空间致敬科学成就、激励下一代。相关视频在印度等地引发讨论，有人对比本地公共传播，呼吁更重视创新而非商业喧嚣。", "body_en": "China Replaces Metro Ads with Portraits of Scientists.\n\nImagine stepping into a metro station where giant screens honor scientists like hybrid rice pioneer Yuan Longping instead of flashy ads. It's a simple swap that's getting people talking about role models.\n\nChina has started replacing advertisements on large public screens in metro stations, malls, and other spaces with portraits of renowned scientists such as agronomist Yuan Longping, Nobel winner Tu Youyou for malaria treatment, rocket expert Qian Xuesen, and nuclear physicist Deng Jiaxian.\n\nThe initiative began in Shandong province in August 2026 and spread to cities like Zhengzhou and Chongqing, especially around national holidays, with businesses voluntarily dedicating the space to celebrate scientific achievements and inspire the next generation. Videos of these displays have sparked online conversations in places like India, where some contrast it with local public messaging and call for emulating the focus on innovation over commercial noise.", "body_zh": "中国多地用科学家肖像替换地铁商业广告。\n\n走进地铁站，巨型屏幕上是杂交水稻先驱袁隆平等科学家，而非炫目广告。这一简单替换引来关于榜样的讨论。\n\n中国开始在地铁站、商场等公共大屏用著名科学家肖像替换广告，包括农学家袁隆平、因疟疾治疗获诺奖的屠呦呦、火箭专家钱学森、核物理学家邓稼先等。举措 2026 年 8 月起自山东推开，并扩展至郑州、重庆等城市，尤其在国庆等节点，企业自愿腾出空间致敬科学成就、激励下一代。\n\n相关视频在印度等地引发讨论，有人对比本地公共传播，呼吁更重视创新而非商业喧嚣。", "url": "https://x.com/i/trending/2112810342728323293", "category": "News", "topics": ["News"], "updated_at": "2026-10-21T10:44:04.000Z"}, {"id": "2112161836116132305", "domain": "中国", "title_en": "China Restricts Tunnel Boring Machine Exports Targeting India's Projects", "title_zh": "中国限制全断面掘进机出口，印度基建承压", "hook_en": "India's metro and border tunnel builds now face new hurdles from China's export curbs on key machinery. Analysts see it as a direct hit amid ongoing tensions.", "hook_zh": "印度地铁与边境隧道建设因中国对关键机械出口设限再添障碍。分析认为在持续紧张背景下属直接冲击。", "summary_en": "China's commerce ministry imposed export licenses on full-face tunnel boring machines, cutterheads, and high-altitude shotcrete equipment, effective November 18, citing dual-use military risks. The controls target sensitive regions like India, which has relied on these imports for infrastructure despite dropping purchases from $18 million to $3 million yearly. India is countering with a $1.2 billion incentive for local production by firms like BEML and L&T, accelerating self-reliance in heavy machinery.", "summary_zh": "中国商务部对全断面隧道掘进机、刀盘及高原喷射混凝土设备实施出口许可，11 月 18 日起生效，理由为军民两用风险。管控针对印度等敏感地区；印度基建仍依赖此类进口，尽管年采购已从约 1800 万美元降至 300 万美元。印度正以约 12 亿美元激励推动 BEML、L&T 等本土生产，加速重型机械自力更生。", "body_en": "China Restricts Tunnel Boring Machine Exports Targeting India's Projects.\n\nIndia's metro and border tunnel builds now face new hurdles from China's export curbs on key machinery. Analysts see it as a direct hit amid ongoing tensions.\n\nChina's commerce ministry imposed export licenses on full-face tunnel boring machines, cutterheads, and high-altitude shotcrete equipment, effective November 18, citing dual-use military risks.\n\nThe controls target sensitive regions like India, which has relied on these imports for infrastructure despite dropping purchases from $18 million to $3 million yearly. India is countering with a $1.2 billion incentive for local production by firms like BEML and L&T, accelerating self-reliance in heavy machinery.", "body_zh": "中国限制全断面掘进机出口，印度基建承压。\n\n印度地铁与边境隧道建设因中国对关键机械出口设限再添障碍。分析认为在持续紧张背景下属直接冲击。\n\n中国商务部对全断面隧道掘进机、刀盘及高原喷射混凝土设备实施出口许可，11 月 18 日起生效，理由为军民两用风险。管控针对印度等敏感地区；印度基建仍依赖此类进口，尽管年采购已从约 1800 万美元降至 300 万美元。\n\n印度正以约 12 亿美元激励推动 BEML、L&T 等本土生产，加速重型机械自力更生。", "url": "https://x.com/i/trending/2112161836116132305", "category": "News", "topics": ["News", "Business & Finance"], "updated_at": "2026-10-20T19:24:59.000Z"}, {"id": "2112437946263474495", "domain": "中国", "title_en": "China Tracks U.S. Warship Near Disputed South China Sea Shoal", "title_zh": "中国跟踪靠近争议南沙礁盘的美舰", "hook_en": "Early Tuesday, a U.S. littoral combat ship sailed into waters China calls its own near Xianbin Jiao, prompting Beijing to send forces for close monitoring.", "hook_zh": "周二早间，一艘美军濒海战斗舰驶入中方所称仙宾礁附近水域，北京派出力量抵近监控。", "summary_en": "China's PLA Navy accused the USS Charleston of illegally entering waters adjacent to Xianbin Jiao in the Spratly Islands on October 20, claiming it threatens sovereignty and regional stability. The Philippines countered that the ship stayed in international waters, requiring no permission, and referenced a 2016 arbitral ruling against China's claims. This follows a recent vessel collision near the same shoal and comes amid overlapping territorial assertions by multiple nations in the South China Sea.", "summary_zh": "中国人民解放军海军指责美舰「查尔斯顿」号于 10 月 20 日非法进入南沙群岛仙宾礁邻近水域，称其威胁主权与地区稳定。菲律宾反驳称该舰处于国际水域、无需许可，并援引 2016 年仲裁裁决否定中方主张。事件发生在同礁附近近期船只擦碰之后，正值多国在南海存在重叠领土主张。", "body_en": "China Tracks U.S. Warship Near Disputed South China Sea Shoal.\n\nEarly Tuesday, a U.S. littoral combat ship sailed into waters China calls its own near Xianbin Jiao, prompting Beijing to send forces for close monitoring.\n\nChina's PLA Navy accused the USS Charleston of illegally entering waters adjacent to Xianbin Jiao in the Spratly Islands on October 20, claiming it threatens sovereignty and regional stability.\n\nThe Philippines countered that the ship stayed in international waters, requiring no permission, and referenced a 2016 arbitral ruling against China's claims. This follows a recent vessel collision near the same shoal and comes amid overlapping territorial assertions by multiple nations in the South China Sea.", "body_zh": "中国跟踪靠近争议南沙礁盘的美舰。\n\n周二早间，一艘美军濒海战斗舰驶入中方所称仙宾礁附近水域，北京派出力量抵近监控。\n\n中国人民解放军海军指责美舰「查尔斯顿」号于 10 月 20 日非法进入南沙群岛仙宾礁邻近水域，称其威胁主权与地区稳定。\n\n菲律宾反驳称该舰处于国际水域、无需许可，并援引 2016 年仲裁裁决否定中方主张。事件发生在同礁附近近期船只擦碰之后，正值多国在南海存在重叠领土主张。", "url": "https://x.com/i/trending/2112437946263474495", "category": "News", "topics": ["News", "Politics"], "updated_at": "2026-10-20T15:35:04.000Z"}, {"id": "2112529713906200727", "domain": "中国", "title_en": "Lincolnshire Mayor Signs Taiwan Partnership Amid Authority Questions", "title_zh": "林肯郡市长签署对台伙伴关系，权限遭质疑", "hook_en": "Dame Andrea Jenkyns beamed from a video call, pen in hand, announcing a new deal with Taiwan's Tainan to boost trade and innovation. Online replies quickly pointed out mayors don't handle international agreements.", "hook_zh": "安德莉亚·詹金斯女爵士在视频通话中亮出签字笔，宣布与台湾台南达成新合作以促进贸易与创新；网友迅速指出市长无权签国际条约。", "summary_en": "Greater Lincolnshire's mayor shared images of signing what she called a landmark trade agreement with Tainan, highlighting opportunities in agriculture, tech, and culture. Critics, including a former council leader, labeled it deluded and beyond her powers, clarifying it's actually a sister-city partnership for local exchanges. Taiwanese media confirmed the first such UK-Taiwan link, while users stressed precise wording to avoid misleading the public on formal trade deals.", "summary_zh": "大林肯郡市长分享了她所称与台南签署「里程碑式贸易协议」的影像，强调农业、科技与文化机遇。批评者包括前地方议会领袖称其越权、表述不切实际，并澄清实质为姐妹城市式地方交流伙伴关系。台湾媒体确认此为英台间此类链接的首例；舆论强调措辞须准确，以免公众误以为是正式贸易协定。", "body_en": "Lincolnshire Mayor Signs Taiwan Partnership Amid Authority Questions.\n\nDame Andrea Jenkyns beamed from a video call, pen in hand, announcing a new deal with Taiwan's Tainan to boost trade and innovation. Online replies quickly pointed out mayors don't handle international agreements.\n\nGreater Lincolnshire's mayor shared images of signing what she called a landmark trade agreement with Tainan, highlighting opportunities in agriculture, tech, and culture.\n\nCritics, including a former council leader, labeled it deluded and beyond her powers, clarifying it's actually a sister-city partnership for local exchanges. Taiwanese media confirmed the first such UK-Taiwan link, while users stressed precise wording to avoid misleading the public on formal trade deals.", "body_zh": "林肯郡市长签署对台伙伴关系，权限遭质疑。\n\n安德莉亚·詹金斯女爵士在视频通话中亮出签字笔，宣布与台湾台南达成新合作以促进贸易与创新；网友迅速指出市长无权签国际条约。\n\n大林肯郡市长分享了她所称与台南签署「里程碑式贸易协议」的影像，强调农业、科技与文化机遇。\n\n批评者包括前地方议会领袖称其越权、表述不切实际，并澄清实质为姐妹城市式地方交流伙伴关系。台湾媒体确认此为英台间此类链接的首例；舆论强调措辞须准确，以免公众误以为是正式贸易协定。", "url": "https://x.com/i/trending/2112529713906200727", "category": "News", "topics": ["News"], "updated_at": "2026-10-20T13:07:49.000Z"}, {"id": "2112538623471964597", "domain": "中国", "title_en": "USDA Confirms Major Soybean Export Sale to China", "title_zh": "美农业部确认对华大豆大单出口", "hook_en": "Farmers and traders perked up Tuesday when the USDA announced a hefty private sale of U.S. soybeans to China—the first real sign of renewed buying after quiet months.", "hook_zh": "美国农业部公布对华私人大豆销售大单，是数月冷清后重新采购的首个明确信号，令农场主与贸易商振奋。", "summary_en": "Private exporters reported selling 612,000 metric tons of American soybeans to China for the 2026/27 marketing year, one of the largest single-day deals lately. Chinese customs data showed the first U.S. soybean arrivals in September at 360,878 tons, up from zero a year ago, though total imports fell 8% to 11.88 million tons with Brazil supplying most at 10.7 million. For January through September, U.S. exports to China dropped 34% year-over-year to 11.06 million tons, while Brazil's climbed 3.4% to 65.84 million—yet recent data points to U.S. rebounding amid improving trade conditions.", "summary_zh": "私人出口商报告向中国出售 61.2 万吨美豆，用于 2026/27 销售年度，为近期单日较大成交之一。中国海关显示 9 月首批美豆到港 36.0878 万吨，高于去年同期的零；但总进口仍降 8% 至 1188 万吨，巴西供应约 1070 万吨居首。1–9 月美对华出口同比降 34% 至 1106 万吨，巴西升 3.4% 至 6584 万吨——近期数据则显示美豆在贸易环境改善下有所回升。", "body_en": "USDA Confirms Major Soybean Export Sale to China.\n\nFarmers and traders perked up Tuesday when the USDA announced a hefty private sale of U.S. soybeans to China—the first real sign of renewed buying after quiet months.\n\nPrivate exporters reported selling 612,000 metric tons of American soybeans to China for the 2026/27 marketing year, one of the largest single-day deals lately. Chinese customs data showed the first U.S. soybean arrivals in September at 360,878 tons, up from zero a year ago, though total imports fell 8% to 11.88 million tons with Brazil supplying most at 10.7 million.\n\nFor January through September, U.S. exports to China dropped 34% year-over-year to 11.06 million tons, while Brazil's climbed 3.4% to 65.84 million—yet recent data points to U.S. rebounding amid improving trade conditions.", "body_zh": "美农业部确认对华大豆大单出口。\n\n美国农业部公布对华私人大豆销售大单，是数月冷清后重新采购的首个明确信号，令农场主与贸易商振奋。\n\n私人出口商报告向中国出售 61.2 万吨美豆，用于 2026/27 销售年度，为近期单日较大成交之一。\n\n中国海关显示 9 月首批美豆到港 36.0878 万吨，高于去年同期的零；但总进口仍降 8% 至 1188 万吨，巴西供应约 1070 万吨居首。1–9 月美对华出口同比降 34% 至 1106 万吨，巴西升 3.4% 至 6584 万吨——近期数据则显示美豆在贸易环境改善下有所回升。", "url": "https://x.com/i/trending/2112538623471964597", "category": "News", "topics": ["Business & Finance"], "updated_at": "2026-10-20T13:42:34.000Z"}, {"id": "2112003183275090362", "domain": "中国", "title_en": "China's Economy Grows Faster Than Expected Amid Record Stock Slump", "title_zh": "在创纪录的股市下滑中，中国经济的增长速度超过预期", "hook_en": "China's GDP beat forecasts in Q3, offering a bright spot even as stocks hit their longest losing streak ever.", "hook_zh": "中国的GDP在第三季度超过了预测，即使股市创下有史以来最长的连跌纪录，也提供了一个亮点。", "summary_en": "Official data showed 4.5% year-on-year growth in the third quarter, topping estimates of 4.4% and lifting the first nine months to 4.6%, within Beijing's annual target. Industrial output rose 5.5% in September, retail sales gained 1.1%, and a $133.5 billion trade surplus provided support, driven by tech exports tied to global AI demand. Yet the CSI 300 index fell for 10 straight weeks, its worst streak, as domestic demand stayed soft with property woes and weak consumer spending. Economists see the rebound easing stimulus pressure but question its staying power.", "summary_zh": "官方数据显示三季度同比增长 4.5%，高于 4.4% 预期，前九个月升至 4.6%，仍在年度目标区间。9 月工业增加值增 5.5%，零售增 1.1%，贸易顺差约 1335 亿美元，科技出口受全球 AI 需求拉动。但沪深 300 连续 10 周下跌创最差纪录，内需偏弱、地产与消费仍承压。经济学者认为回升减轻刺激压力，但可持续性仍存疑。", "body_en": "China's Economy Grows Faster Than Expected Amid Record Stock Slump.\n\nChina's GDP beat forecasts in Q3, offering a bright spot even as stocks hit their longest losing streak ever.\n\nOfficial data showed 4.5% year-on-year growth in the third quarter, topping estimates of 4.4% and lifting the first nine months to 4.6%, within Beijing's annual target. Industrial output rose 5.5% in September, retail sales gained 1.1%, and a $133.5 billion trade surplus provided support, driven by tech exports tied to global AI demand.\n\nYet the CSI 300 index fell for 10 straight weeks, its worst streak, as domestic demand stayed soft with property woes and weak consumer spending. Economists see the rebound easing stimulus pressure but question its staying power.", "body_zh": "在创纪录的股市下滑中，中国经济的增长速度超过预期。\n\n中国的GDP在第三季度超过了预测，即使股市创下有史以来最长的连跌纪录，也提供了一个亮点。\n\n官方数据显示三季度同比增长 4.5%，高于 4.4% 预期，前九个月升至 4.6%，仍在年度目标区间。9 月工业增加值增 5.5%，零售增 1.1%，贸易顺差约 1335 亿美元，科技出口受全球 AI 需求拉动。\n\n但沪深 300 连续 10 周下跌创最差纪录，内需偏弱、地产与消费仍承压。经济学者认为回升减轻刺激压力，但可持续性仍存疑。", "url": "https://x.com/i/trending/2112003183275090362", "category": "News", "topics": ["Business & Finance"], "updated_at": "2026-10-20T10:15:42.000Z"}, {"id": "2112533926702936100", "domain": "中国", "title_en": "China's Philosophers Offer Fresh Take on AI and Humanity", "title_zh": "中国的哲学家对人工智能和人类提出了全新的看法", "hook_en": "While Western worries center on super-smart machines outpacing us, Chinese thinkers flip the script to protect what makes us truly human.", "hook_zh": "虽然西方的担忧集中在超级智能机器超越我们，但中国思想家翻转脚本，以保护使我们真正成为人类的东西。", "summary_en": "Arnaud Bertrand's Substack explores how China's philosophers, sociologists, and ethicists view AI through traditions like Confucianism, emphasizing the heart-mind and benevolence over raw intelligence. Thinkers like Liu Yongmou warn against the 'machinization of humans'—technology eroding our inner qualities—while Zhao Tingyang cautions that aligning AI with human values might backfire. Drawing from ancient texts like the Zhuangzi, these ideas challenge Western fears and highlight overlooked questions as China leads in AI development.", "summary_zh": "Arnaud Bertrand的Substack探讨了中国的哲学家、社会学家和伦理学家如何通过儒家思想等传统来看待人工智能，强调心灵和仁慈而不是原始智慧。像刘永谋这样的思想家警告不要“人类机械化” --技术侵蚀我们的内在品质--而赵廷阳则警告说，将人工智能与人类价值观结合起来可能会适得其反。 这些想法借鉴了庄子等古代文献，挑战了西方的恐惧，并强调了随着中国在人工智能发展方面的领先地位而被忽视的问题。", "body_en": "China's Philosophers Offer Fresh Take on AI and Humanity.\n\nWhile Western worries center on super-smart machines outpacing us, Chinese thinkers flip the script to protect what makes us truly human.\n\nArnaud Bertrand's Substack explores how China's philosophers, sociologists, and ethicists view AI through traditions like Confucianism, emphasizing the heart-mind and benevolence over raw intelligence.\n\nThinkers like Liu Yongmou warn against the 'machinization of humans'—technology eroding our inner qualities—while Zhao Tingyang cautions that aligning AI with human values might backfire. Drawing from ancient texts like the Zhuangzi, these ideas challenge Western fears and highlight overlooked questions as China leads in AI development.", "body_zh": "中国的哲学家对人工智能和人类提出了全新的看法。\n\n虽然西方的担忧集中在超级智能机器超越我们，但中国思想家翻转脚本，以保护使我们真正成为人类的东西。\n\nArnaud Bertrand的Substack探讨了中国的哲学家、社会学家和伦理学家如何通过儒家思想等传统来看待人工智能，强调心灵和仁慈而不是原始智慧。\n\n像刘永谋这样的思想家警告不要“人类机械化” --技术侵蚀我们的内在品质--而赵廷阳则警告说，将人工智能与人类价值观结合起来可能会适得其反。这些想法借鉴了庄子等古代文献，挑战了西方的恐惧，并强调了随着中国在人工智能发展方面的领先地位而被忽视的问题。", "url": "https://x.com/i/trending/2112533926702936100", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-20T13:25:56.000Z"}, {"id": "2112405151768100963", "domain": "中国", "title_en": "Philippine Senators Push to Expel Chinese Ambassador Over Sea Threat", "title_zh": "菲参议员推动驱逐中国大使：南海言论引强烈反弹", "hook_en": "Chinese Ambassador Jing Quan's words hung heavy: China could 'easily win' with force in the West Philippine Sea, though it prefers peace. Philippine senators fired back, demanding he be sent home.", "hook_zh": "中国驻菲大使景泉称中国在西菲律宾海「可轻易取胜」但更愿和平；菲参议员要求将其驱逐出境。", "summary_en": "Senators Risa Hontiveros and Erwin Tulfo filed resolutions urging President Marcos to declare Ambassador Jing persona non grata after his remarks, seen as a veiled threat amid China's vessel harassment and illegal fishing in Philippine waters. The Department of Foreign Affairs summoned Jing to protest, while Senator Kiko Pangilinan sharply challenged Marcos to act decisively. The Chinese Embassy hit back by listing critical lawmakers online, but Malacañang favors diplomatic channels over expulsion to avoid escalation.", "summary_zh": "参议员 Risa Hontiveros 与 Erwin Tulfo 提交决议，敦促马科斯总统宣布景泉为不受欢迎人物，认为其言论是在船隻滋扰与非法捕捞背景下的威胁。外交部召见抗议；参议员 Kiko Pangilinan 直言马科斯应果断行动。中国使馆在网上点名批评议员；马拉卡南宫倾向外交渠道而非驱逐，以免局势升级。", "body_en": "Philippine Senators Push to Expel Chinese Ambassador Over Sea Threat.\n\nChinese Ambassador Jing Quan's words hung heavy: China could 'easily win' with force in the West Philippine Sea, though it prefers peace. Philippine senators fired back, demanding he be sent home.\n\nSenators Risa Hontiveros and Erwin Tulfo filed resolutions urging President Marcos to declare Ambassador Jing persona non grata after his remarks, seen as a veiled threat amid China's vessel harassment and illegal fishing in Philippine waters.\n\nThe Department of Foreign Affairs summoned Jing to protest, while Senator Kiko Pangilinan sharply challenged Marcos to act decisively. The Chinese Embassy hit back by listing critical lawmakers online, but Malacañang favors diplomatic channels over expulsion to avoid escalation.", "body_zh": "菲参议员推动驱逐中国大使：南海言论引强烈反弹。\n\n中国驻菲大使景泉称中国在西菲律宾海「可轻易取胜」但更愿和平；菲参议员要求将其驱逐出境。\n\n参议员 Risa Hontiveros 与 Erwin Tulfo 提交决议，敦促马科斯总统宣布景泉为不受欢迎人物，认为其言论是在船隻滋扰与非法捕捞背景下的威胁。\n\n外交部召见抗议；参议员 Kiko Pangilinan 直言马科斯应果断行动。中国使馆在网上点名批评议员；马拉卡南宫倾向外交渠道而非驱逐，以免局势升级。", "url": "https://x.com/i/trending/2112405151768100963", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-21T10:24:16.000Z"}, {"id": "2113011795937865915", "domain": "国际", "title_en": "Ireland's Parliament Narrows Approves Triple Lock Reform on Defence Deployments", "title_zh": "爱尔兰议会以微弱优势通过“三重锁定”防务改革", "hook_en": "After hours of heated debate, Ireland's Dáil voted 79-71 to loosen rules that have long guided its troops overseas, keeping government and parliamentary checks but dropping the UN veto.", "hook_zh": "经过数小时激烈辩论，爱尔兰众议院以79票对71票通过放宽海外派兵规则：保留政府与议会把关，但取消联合国一票否决。", "summary_en": "The Defence (Amendment) Bill 2026 removes the United Nations Security Council mandate from the Triple Lock, which previously required cabinet, Dáil, and UN approval for missions with more than 12 troops. Supporters like Taoiseach Micheál Martin and Defence Minister Helen McEntee argue the change lets Ireland sustain its 60-year peacekeeping tradition without relying on a gridlocked UN, especially amid vetoes from nations like Russia. Opposition leaders such as Sinn Féin's Mary Lou McDonald call it a betrayal of neutrality without a public vote, backed by polls showing 44 percent favour keeping the Triple Lock intact. The bill heads to committee next month, with critics pushing for wider consultation on this shift in foreign policy.", "summary_zh": "《2026年国防（修正）法案》将联合国安理会授权从“三重锁定”中移除；此前超过12人的海外任务需内阁、众议院与联合国三方批准。总理马丁、国防部长麦肯蒂等支持者称，此举可让爱尔兰在联合国陷入僵局、尤其是俄方否决频发时，继续维持六十余年维和传统。新芬党领袖麦克唐纳等反对派斥其为未经公投的中立立场背叛，民调显示约44%民众希望保留原机制。法案下月进入委员会审议，批评者呼吁就外交政策转向展开更广泛磋商。", "body_en": "Ireland's Parliament Narrows Approves Triple Lock Reform on Defence Deployments.\n\nAfter hours of heated debate, Ireland's Dáil voted 79-71 to loosen rules that have long guided its troops overseas, keeping government and parliamentary checks but dropping the UN veto.\n\nThe Defence (Amendment) Bill 2026 removes the United Nations Security Council mandate from the Triple Lock, which previously required cabinet, Dáil, and UN approval for missions with more than 12 troops. Supporters like Taoiseach Micheál Martin and Defence Minister Helen McEntee argue the change lets Ireland sustain its 60-year peacekeeping tradition without relying on a gridlocked UN, especially amid vetoes from nations like Russia.\n\nOpposition leaders such as Sinn Féin's Mary Lou McDonald call it a betrayal of neutrality without a public vote, backed by polls showing 44 percent favour keeping the Triple Lock intact. The bill heads to committee next month, with critics pushing for wider consultation on this shift in foreign policy.", "body_zh": "爱尔兰议会以微弱优势通过“三重锁定”防务改革。\n\n经过数小时激烈辩论，爱尔兰众议院以79票对71票通过放宽海外派兵规则：保留政府与议会把关，但取消联合国一票否决。\n\n《2026年国防（修正）法案》将联合国安理会授权从“三重锁定”中移除；此前超过12人的海外任务需内阁、众议院与联合国三方批准。总理马丁、国防部长麦肯蒂等支持者称，此举可让爱尔兰在联合国陷入僵局、尤其是俄方否决频发时，继续维持六十余年维和传统。\n\n新芬党领袖麦克唐纳等反对派斥其为未经公投的中立立场背叛，民调显示约44%民众希望保留原机制。法案下月进入委员会审议，批评者呼吁就外交政策转向展开更广泛磋商。", "url": "https://x.com/i/trending/2113011795937865915", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-21T21:05:15.000Z"}, {"id": "2112296384745631848", "domain": "国际", "title_en": "France Protests Spark Debate on Russian Interference Claims", "title_zh": "法国抗议潮引发「俄方干涉」说法之争", "hook_en": "Hundreds of thousands marched in France on October 17 over soaring living costs and cuts to education, only for the unrest to fuel sharp online arguments about hidden foreign hands.", "hook_zh": "10 月 17 日法国数十万人抗议生活成本飙升与教育削减，骚乱随后在网上激起「是否有外部黑手」的激烈争论。", "summary_en": "Demonstrations drew around 550,000 people nationwide, including 110,000 in Paris, starting with student demands before expanding to unions and turning violent with looting, arson, and over 1,200 arrests. Estonian MP Marko Mihkelson claimed Russia benefits from the chaos in France and Italy as part of a shadow war, while a satirical post by Wolfgang Richter mocked the idea of Putin paying protesters and called for speech curbs. Officials insist the unrest stems from domestic economic woes, with no evidence of Russian or Iranian organization, though both nations have amplified the violence in propaganda; online views split between those seeing Moscow's gain and critics dismissing it as scapegoating real policy failures.", "summary_zh": "全国约 55 万人上街，巴黎约 11 万，由学生诉求扩至工会，并演变为抢劫、纵火与逾 1200 人被捕。爱沙尼亚议员 Marko Mihkelson 称俄从法、意乱局获益，属影子战争；Wolfgang Richter 的讽刺帖则嘲讽「普京出钱抗议」说法并呼吁限制言论。官方坚持动因是国内经济困境，并无俄、伊组织证据，尽管两国宣传放大了暴力画面；网上有人强调莫斯科受益，也有人批评这是在替真正的政策失败找替罪羊。", "body_en": "France Protests Spark Debate on Russian Interference Claims.\n\nHundreds of thousands marched in France on October 17 over soaring living costs and cuts to education, only for the unrest to fuel sharp online arguments about hidden foreign hands.\n\nDemonstrations drew around 550,000 people nationwide, including 110,000 in Paris, starting with student demands before expanding to unions and turning violent with looting, arson, and over 1,200 arrests.\n\nEstonian MP Marko Mihkelson claimed Russia benefits from the chaos in France and Italy as part of a shadow war, while a satirical post by Wolfgang Richter mocked the idea of Putin paying protesters and called for speech curbs. Officials insist the unrest stems from domestic economic woes, with no evidence of Russian or Iranian organization, though both nations have amplified the violence in propaganda; online views split between those seeing Moscow's gain and critics dismissing it as scapegoating real policy failures.", "body_zh": "法国抗议潮引发「俄方干涉」说法之争。\n\n10 月 17 日法国数十万人抗议生活成本飙升与教育削减，骚乱随后在网上激起「是否有外部黑手」的激烈争论。\n\n全国约 55 万人上街，巴黎约 11 万，由学生诉求扩至工会，并演变为抢劫、纵火与逾 1200 人被捕。\n\n爱沙尼亚议员 Marko Mihkelson 称俄从法、意乱局获益，属影子战争；Wolfgang Richter 的讽刺帖则嘲讽「普京出钱抗议」说法并呼吁限制言论。官方坚持动因是国内经济困境，并无俄、伊组织证据，尽管两国宣传放大了暴力画面；网上有人强调莫斯科受益，也有人批评这是在替真正的政策失败找替罪羊。", "url": "https://x.com/i/trending/2112296384745631848", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-20T14:03:55.000Z"}, {"id": "2112893265104007427", "domain": "国际", "title_en": "Thread Reveals Groups Planning Responses to Potential Federal Actions Before Midterms", "title_zh": "帖文曝光组织在中期选举前讨论应对联邦行动", "hook_en": "A detailed X thread uncovered audio and video from democracy groups discussing when the federal government might cross into illegitimacy, raising eyebrows just before the November midterms.", "hook_zh": "一篇详尽的 X 帖文披露民主团体讨论联邦政府何时可能「越界」的音视频，临近 11 月中期选举引发关注。", "summary_en": "X user DataRepublican, real name Jennica Pounds, shared materials from the Renew to Thrive group and the United Democracy Alliance, which links with NGOs like Indivisible. The recordings outline 'redlines' such as invoking the Insurrection Act against peaceful protesters, with governors potentially refusing federal troops and networks stepping in. This coincides with a Washington Post report on current and former Pentagon officials advising 10 states on resisting possible federal moves near polling places. Reactions split between calls for investigation and defenses of the work as protecting elections, though the materials await independent verification.", "summary_zh": "X 用户 DataRepublican（真名 Jennica Pounds）分享了 Renew to Thrive 团体与联合民主联盟（关联 Indivisible 等 NGO）的材料。录音勾勒「红线」场景，例如对和平抗议者动用《叛乱法》，州长或拒绝联邦部队、网络介入响应。同期《华盛顿邮报》报道现任与前任五角大楼官员正为约 10 个州提供建议，以防范投票点附近可能的联邦举动。舆论分裂为要求调查与辩称属保卫选举，材料尚待独立核实。", "body_en": "Thread Reveals Groups Planning Responses to Potential Federal Actions Before Midterms.\n\nA detailed X thread uncovered audio and video from democracy groups discussing when the federal government might cross into illegitimacy, raising eyebrows just before the November midterms.\n\nX user DataRepublican, real name Jennica Pounds, shared materials from the Renew to Thrive group and the United Democracy Alliance, which links with NGOs like Indivisible. The recordings outline 'redlines' such as invoking the Insurrection Act against peaceful protesters, with governors potentially refusing federal troops and networks stepping in.\n\nThis coincides with a Washington Post report on current and former Pentagon officials advising 10 states on resisting possible federal moves near polling places. Reactions split between calls for investigation and defenses of the work as protecting elections, though the materials await independent verification.", "body_zh": "帖文曝光组织在中期选举前讨论应对联邦行动。\n\n一篇详尽的 X 帖文披露民主团体讨论联邦政府何时可能「越界」的音视频，临近 11 月中期选举引发关注。\n\nX 用户 DataRepublican（真名 Jennica Pounds）分享了 Renew to Thrive 团体与联合民主联盟（关联 Indivisible 等 NGO）的材料。录音勾勒「红线」场景，例如对和平抗议者动用《叛乱法》，州长或拒绝联邦部队、网络介入响应。\n\n同期《华盛顿邮报》报道现任与前任五角大楼官员正为约 10 个州提供建议，以防范投票点附近可能的联邦举动。舆论分裂为要求调查与辩称属保卫选举，材料尚待独立核实。", "url": "https://x.com/i/trending/2112893265104007427", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-21T17:32:37.000Z"}, {"id": "2112948936755286232", "domain": "国际", "title_en": "JD Vance Questions US Obligations to Ukraine Amid Budapest Memorandum Debate", "title_zh": "万斯质疑美国对乌克兰义务，布达佩斯备忘录再成焦点", "hook_en": "JD Vance called Ukraine a partner, not an ally, with no formal obligation to defend it. That statement quickly brought back memories of a 1994 promise Ukraine trusted when it gave up its nuclear arsenal.", "hook_zh": "万斯称乌克兰是伙伴而非盟友，美国并无正式协防义务。此言迅速勾起1994年乌克兰弃核时所信承诺的记忆。", "summary_en": "In an October 20, 2026 interview, US Vice President JD Vance said America has no treaty-bound duty to stand by Ukraine. Many pointed to the 1994 Budapest Memorandum, where Ukraine surrendered about 4,400 nuclear warheads in exchange for security assurances from the US, Russia, and the UK—assurances that respected its sovereignty and borders but lacked binding military commitments like NATO's Article 5. While the US has sent billions in aid since Russia's 2014 Crimea annexation and 2022 invasion, the debate highlights the memorandum's moral weight versus its non-binding nature, raising questions for nations weighing nuclear disarmament.", "summary_zh": "美国副总统万斯在2026年10月20日采访中表示，美国对乌克兰并无条约约束的协防责任。许多人提及1994年《布达佩斯备忘录》：乌克兰交出约4400枚核弹头，换取美、俄、英对其主权与边界的安全保证，但该保证并不具备北约第五条那样的强制军事承诺。尽管自2014年克里米亚事件与2022年全面入侵以来美国已提供巨额援助，这场辩论仍凸显备忘录的道德分量与非约束性之间的张力，也令正考虑弃核的国家心生疑虑。", "body_en": "JD Vance Questions US Obligations to Ukraine Amid Budapest Memorandum Debate.\n\nJD Vance called Ukraine a partner, not an ally, with no formal obligation to defend it. That statement quickly brought back memories of a 1994 promise Ukraine trusted when it gave up its nuclear arsenal.\n\nIn an October 20, 2026 interview, US Vice President JD Vance said America has no treaty-bound duty to stand by Ukraine.\n\nMany pointed to the 1994 Budapest Memorandum, where Ukraine surrendered about 4,400 nuclear warheads in exchange for security assurances from the US, Russia, and the UK—assurances that respected its sovereignty and borders but lacked binding military commitments like NATO's Article 5. While the US has sent billions in aid since Russia's 2014 Crimea annexation and 2022 invasion, the debate highlights the memorandum's moral weight versus its non-binding nature, raising questions for nations weighing nuclear disarmament.", "body_zh": "万斯质疑美国对乌克兰义务，布达佩斯备忘录再成焦点。\n\n万斯称乌克兰是伙伴而非盟友，美国并无正式协防义务。此言迅速勾起1994年乌克兰弃核时所信承诺的记忆。\n\n美国副总统万斯在2026年10月20日采访中表示，美国对乌克兰并无条约约束的协防责任。\n\n许多人提及1994年《布达佩斯备忘录》：乌克兰交出约4400枚核弹头，换取美、俄、英对其主权与边界的安全保证，但该保证并不具备北约第五条那样的强制军事承诺。尽管自2014年克里米亚事件与2022年全面入侵以来美国已提供巨额援助，这场辩论仍凸显备忘录的道德分量与非约束性之间的张力，也令正考虑弃核的国家心生疑虑。", "url": "https://x.com/i/trending/2112948936755286232", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-21T19:58:44.000Z"}, {"id": "2112826877455053262", "domain": "国际", "title_en": "India Adds Three Sites to UNESCO World Heritage Tentative List", "title_zh": "印度三处遗址列入联合国教科文组织世界遗产预备名录", "hook_en": "From bubbling mud volcanoes in the Andamans to ancient temples along the Mahanadi River, three Indian treasures now stand closer to global recognition.", "hook_zh": "从安达曼泥火山到默哈讷迪河畔古庙，三处印度遗产向全球认可又近一步。", "summary_en": "India's Permanent Delegation to UNESCO announced on October 20, 2026, the addition of the Karst-mud-volcano Complex of Baratang and Andaman Subduction Volcanoes in the Andaman and Nicobar Islands, plus the Sirpur Cultural and Archaeological Landscape in Chhattisgarh. These sites highlight unique geology like active volcanoes and limestone caves, alongside historic temples reflecting Hindu, Buddhist, and Jain heritage with evidence of multi-faith harmony. Union Minister Gajendra Singh Shekhawat praised Sirpur for its traditions in art, architecture, spirituality, and learning, as India builds on its 45 inscribed World Heritage Sites.", "summary_zh": "印度常驻教科文组织代表团 2026 年 10 月 20 日宣布，将巴拉唐喀斯特—泥火山综合体与安达曼俯冲火山，以及恰蒂斯加尔邦西尔普尔文化考古景观列入预备名录。前者突出活火山与石灰岩洞穴等地质特色，后者涵盖印度教、佛教与耆那教古庙及多信仰共存证据。联邦部长 Gajendra Singh Shekhawat 称赞西尔普尔在艺术、建筑、精神与学问上的传统；印度已有 45 处列入世界遗产。", "body_en": "India Adds Three Sites to UNESCO World Heritage Tentative List.\n\nFrom bubbling mud volcanoes in the Andamans to ancient temples along the Mahanadi River, three Indian treasures now stand closer to global recognition.\n\nIndia's Permanent Delegation to UNESCO announced on October 20, 2026, the addition of the Karst-mud-volcano Complex of Baratang and Andaman Subduction Volcanoes in the Andaman and Nicobar Islands, plus the Sirpur Cultural and Archaeological Landscape in Chhattisgarh.\n\nThese sites highlight unique geology like active volcanoes and limestone caves, alongside historic temples reflecting Hindu, Buddhist, and Jain heritage with evidence of multi-faith harmony. Union Minister Gajendra Singh Shekhawat praised Sirpur for its traditions in art, architecture, spirituality, and learning, as India builds on its 45 inscribed World Heritage Sites.", "body_zh": "印度三处遗址列入联合国教科文组织世界遗产预备名录。\n\n从安达曼泥火山到默哈讷迪河畔古庙，三处印度遗产向全球认可又近一步。\n\n印度常驻教科文组织代表团 2026 年 10 月 20 日宣布，将巴拉唐喀斯特—泥火山综合体与安达曼俯冲火山，以及恰蒂斯加尔邦西尔普尔文化考古景观列入预备名录。\n\n前者突出活火山与石灰岩洞穴等地质特色，后者涵盖印度教、佛教与耆那教古庙及多信仰共存证据。联邦部长 Gajendra Singh Shekhawat 称赞西尔普尔在艺术、建筑、精神与学问上的传统；印度已有 45 处列入世界遗产。", "url": "https://x.com/i/trending/2112826877455053262", "category": "News", "topics": ["Travel"], "updated_at": "2026-10-21T11:43:52.000Z"}, {"id": "2112773061082767722", "domain": "国际", "title_en": "Merz Rejects Ukraine Surrender as Threat to All Europe", "title_zh": "默茨拒绝乌克兰投降：那将是整个欧洲的屈服", "hook_en": "German Chancellor Friedrich Merz drew a firm line: Ukraine's surrender would mean Europe's own capitulation. He shared this view at the Berlin Global Dialogue, amid rising Russian sabotage fears.", "hook_zh": "德国总理弗里德里希·默茨划下红线：乌克兰投降等同欧洲自身投降。他在柏林全球对话上发表此论，正值对俄破坏活动担忧升温。", "summary_en": "Merz declared that any surrender by Ukraine to Russia is off the table, as it would surrender Europe's security too. His words followed U.S. intelligence reports of Putin ordering stepped-up sabotage against NATO nations, including a foiled drone attack on Leipzig-Halle Airport targeting a Ukrainian aid plane. A Kremlin back-channel warning hinted at more strikes to come, prompting Germany to boost security and consider NATO's Article 5 if casualties had occurred. Merz called Russia's hybrid operations and societal influence Germany's top concern, framing Ukraine aid as vital to protecting the post-1990 European order.", "summary_zh": "默茨宣称乌克兰向俄罗斯的任何投降都不在讨论之列，因为那也等于交出欧洲安全。表态紧随美国情报称普京下令加强对北约国家破坏活动的报道，包括针对莱比锡-哈雷机场一架乌克兰援助飞机的无人机袭击未遂。克里姆林宫据称通过后门渠道暗示还会有更多打击，促使德国加强安保，并考虑若有伤亡是否触及北约第五条。默茨称俄混合行动与社会渗透是德国首要关切，并将援乌视为捍卫 1990 年后欧洲秩序的关键。", "body_en": "Merz Rejects Ukraine Surrender as Threat to All Europe.\n\nGerman Chancellor Friedrich Merz drew a firm line: Ukraine's surrender would mean Europe's own capitulation. He shared this view at the Berlin Global Dialogue, amid rising Russian sabotage fears.\n\nMerz declared that any surrender by Ukraine to Russia is off the table, as it would surrender Europe's security too. His words followed U.S.\n\nintelligence reports of Putin ordering stepped-up sabotage against NATO nations, including a foiled drone attack on Leipzig-Halle Airport targeting a Ukrainian aid plane. A Kremlin back-channel warning hinted at more strikes to come, prompting Germany to boost security and consider NATO's Article 5 if casualties had occurred. Merz called Russia's hybrid operations and societal influence Germany's top concern, framing Ukraine aid as vital to protecting the post-1990 European order.", "body_zh": "默茨拒绝乌克兰投降：那将是整个欧洲的屈服。\n\n德国总理弗里德里希·默茨划下红线：乌克兰投降等同欧洲自身投降。他在柏林全球对话上发表此论，正值对俄破坏活动担忧升温。\n\n默茨宣称乌克兰向俄罗斯的任何投降都不在讨论之列，因为那也等于交出欧洲安全。表态紧随美国情报称普京下令加强对北约国家破坏活动的报道，包括针对莱比锡-哈雷机场一架乌克兰援助飞机的无人机袭击未遂。\n\n克里姆林宫据称通过后门渠道暗示还会有更多打击，促使德国加强安保，并考虑若有伤亡是否触及北约第五条。默茨称俄混合行动与社会渗透是德国首要关切，并将援乌视为捍卫 1990 年后欧洲秩序的关键。", "url": "https://x.com/i/trending/2112773061082767722", "category": "News", "topics": ["News", "Politics"], "updated_at": "2026-10-21T17:08:27.000Z"}, {"id": "2112501506905710732", "domain": "国际", "title_en": "UK and Poland Rebuke US Defense Secretary Over Afghanistan Ally Claims", "title_zh": "英国与波兰反驳美防长「阿富汗盟友贡献有限」之说", "hook_en": "Pete Hegseth recalled seeing dozens of flags in Kabul but claimed only a handful of nations truly fought alongside Americans. British and Polish leaders quickly pushed back, honoring the lives lost by their troops.", "hook_zh": "皮特·赫格塞斯称在喀布尔见过数十面旗帜，但真正并肩作战的国家寥寥；英国与波兰领导人迅速反驳，纪念本国官兵牺牲。", "summary_en": "During a speech at the University of Tennessee, US Defense Secretary Pete Hegseth said few NATO allies contributed meaningfully to combat in Afghanistan, joking that the ISAF patch meant 'I Saw Americans Fighting.' Downing Street responded firmly, noting 457 British deaths—the second-highest after the US—and thousands of families who sacrificed for collective security after the 2001 attacks. Poland's Foreign Minister Radosław Sikorski highlighted 44 Polish soldiers killed in Ghazni province, while records show over 1,100 non-US coalition deaths overall, underscoring the broad sacrifices in the 20-year conflict.", "summary_zh": "在田纳西大学演讲中，美国国防部长皮特·赫格塞斯称鲜有北约盟友在阿富汗真正投入作战，并戏称 ISAF 臂章意为「我看见美国人在打仗」。唐宁街强硬回应，指出英军阵亡 457 人——仅次于美国——以及数千家庭为「9·11」后集体安全所作牺牲。波兰外长拉多斯瓦夫·西科尔斯基强调在加兹尼省阵亡的 44 名波兰士兵；纪录显示非美联军阵亡逾 1100 人，凸显这场持续约二十年冲突中的广泛牺牲。", "body_en": "UK and Poland Rebuke US Defense Secretary Over Afghanistan Ally Claims.\n\nPete Hegseth recalled seeing dozens of flags in Kabul but claimed only a handful of nations truly fought alongside Americans. British and Polish leaders quickly pushed back, honoring the lives lost by their troops.\n\nDuring a speech at the University of Tennessee, US Defense Secretary Pete Hegseth said few NATO allies contributed meaningfully to combat in Afghanistan, joking that the ISAF patch meant 'I Saw Americans Fighting.' Downing Street responded firmly, noting 457 British deaths—the second-highest after the US—and thousands of families who sacrificed for collective security after the 2001 attacks. Poland's Foreign Minister Radosław Sikorski highlighted 44 Polish soldiers killed in Ghazni province, while records show over 1,100 non-US coalition deaths overall, underscoring the broad sacrifices in the 20-year conflict.", "body_zh": "英国与波兰反驳美防长「阿富汗盟友贡献有限」之说。\n\n皮特·赫格塞斯称在喀布尔见过数十面旗帜，但真正并肩作战的国家寥寥；英国与波兰领导人迅速反驳，纪念本国官兵牺牲。\n\n在田纳西大学演讲中，美国国防部长皮特·赫格塞斯称鲜有北约盟友在阿富汗真正投入作战，并戏称 ISAF 臂章意为「我看见美国人在打仗」。\n\n唐宁街强硬回应，指出英军阵亡 457 人——仅次于美国——以及数千家庭为「9·11」后集体安全所作牺牲。波兰外长拉多斯瓦夫·西科尔斯基强调在加兹尼省阵亡的 44 名波兰士兵；纪录显示非美联军阵亡逾 1100 人，凸显这场持续约二十年冲突中的广泛牺牲。", "url": "https://x.com/i/trending/2112501506905710732", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-20T14:10:22.000Z"}, {"id": "2112823809443066155", "domain": "国际", "title_en": "Debate Revives on NATO Expansion and Russia-Ukraine Origins", "title_zh": "北约东扩与俄乌冲突起源辩论再起", "hook_en": "A detailed post tracing three decades of Russian warnings about NATO in Ukraine has people revisiting the conflict's roots. Images of advancing flags highlight the mutual security fears on both sides.", "hook_zh": "一篇梳理俄罗斯三十年来对北约在乌克兰警告的长文，让人们重新审视冲突根源；推进中的旗帜图像凸显双方的安全恐惧。", "summary_en": "The discussion draws on declassified documents from 1990, where Western leaders assured Soviet leader Mikhail Gorbachev that NATO would not expand eastward, though no formal treaty resulted. Russian officials repeatedly warned from the 1990s to 2021 that Ukraine's NATO membership would trigger war, while critics stress sovereign nations' rights to choose alliances amid Russia's actions like the 2014 Crimea annexation. A 2010 Ukrainian election map reveals deep regional divides, with western areas favoring pro-Western ties and eastern regions leaning toward Russia, complicating the story of national unity.", "summary_zh": "讨论援引 1990 年解密文件：西方领导人曾向苏联领导人戈尔巴乔夫保证北约不会东扩，但并未形成正式条约。俄方官员自 1990 年代至 2021 年反复警告，乌克兰加入北约将触发战争；批评者则强调主权国家有权选择联盟，并指出俄罗斯 2014 年吞并克里米亚等行动。2010 年乌克兰选举地图显示深刻地区分裂——西部倾向亲西方、东部更亲近俄罗斯——使「国家团结」叙事更显复杂。", "body_en": "Debate Revives on NATO Expansion and Russia-Ukraine Origins.\n\nA detailed post tracing three decades of Russian warnings about NATO in Ukraine has people revisiting the conflict's roots. Images of advancing flags highlight the mutual security fears on both sides.\n\nThe discussion draws on declassified documents from 1990, where Western leaders assured Soviet leader Mikhail Gorbachev that NATO would not expand eastward, though no formal treaty resulted.\n\nRussian officials repeatedly warned from the 1990s to 2021 that Ukraine's NATO membership would trigger war, while critics stress sovereign nations' rights to choose alliances amid Russia's actions like the 2014 Crimea annexation. A 2010 Ukrainian election map reveals deep regional divides, with western areas favoring pro-Western ties and eastern regions leaning toward Russia, complicating the story of national unity.", "body_zh": "北约东扩与俄乌冲突起源辩论再起。\n\n一篇梳理俄罗斯三十年来对北约在乌克兰警告的长文，让人们重新审视冲突根源；推进中的旗帜图像凸显双方的安全恐惧。\n\n讨论援引 1990 年解密文件：西方领导人曾向苏联领导人戈尔巴乔夫保证北约不会东扩，但并未形成正式条约。\n\n俄方官员自 1990 年代至 2021 年反复警告，乌克兰加入北约将触发战争；批评者则强调主权国家有权选择联盟，并指出俄罗斯 2014 年吞并克里米亚等行动。2010 年乌克兰选举地图显示深刻地区分裂——西部倾向亲西方、东部更亲近俄罗斯——使「国家团结」叙事更显复杂。", "url": "https://x.com/i/trending/2112823809443066155", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-21T20:53:18.000Z"}, {"id": "2112384299999850805", "domain": "国际", "title_en": "Trump Warns of NATO Exit, Cites France at Kansas Rally", "title_zh": "特朗普在堪萨斯集会警告或退出北约", "hook_en": "Thousands packed an arena in Park City, Kansas, cheering as President Trump warned that Europe’s troubles could force America to pull back from NATO.", "hook_zh": "数万人聚集堪萨斯帕克城会场，特朗普总统警告欧洲乱局可能迫使美国从北约后退。", "summary_en": "At a rally supporting Sen. Roger Marshall ahead of the November 3 midterms, Trump described France as a once-great nation overwhelmed by migrants, jihadists, and communists, urging stronger U.S. borders to avoid a similar fate. He criticized heavy U.S. spending on NATO and Ukraine aid, saying allies must step up or face withdrawal, and expressed willingness for direct talks with Putin and Xi to end the Ukraine conflict. Protesters briefly interrupted but were quickly drowned out by the supportive crowd, as Trump pushed America First priorities alongside pledges for farmers and the economy.", "summary_zh": "在为参议员罗杰·马歇尔助选、迎接 11 月 3 日中期选举的集会上，特朗普称法国曾是伟大国家，如今被移民、圣战分子与共产主义者淹没，并敦促加强美国边境以免重蹈覆辙。他批评美国在北约与援乌上支出过高，称盟友必须加码否则可能面临美方退出，并表示愿与普京、习近平直接会谈以结束乌克兰冲突。抗议者短暂打断，但被支持者声浪盖过；他同时推销「美国优先」及对农民与经济的承诺。", "body_en": "Trump Warns of NATO Exit, Cites France at Kansas Rally.\n\nThousands packed an arena in Park City, Kansas, cheering as President Trump warned that Europe’s troubles could force America to pull back from NATO.\n\nAt a rally supporting Sen. Roger Marshall ahead of the November 3 midterms, Trump described France as a once-great nation overwhelmed by migrants, jihadists, and communists, urging stronger U.S. borders to avoid a similar fate.\n\nHe criticized heavy U.S. spending on NATO and Ukraine aid, saying allies must step up or face withdrawal, and expressed willingness for direct talks with Putin and Xi to end the Ukraine conflict. Protesters briefly interrupted but were quickly drowned out by the supportive crowd, as Trump pushed America First priorities alongside pledges for farmers and the economy.", "body_zh": "特朗普在堪萨斯集会警告或退出北约。\n\n数万人聚集堪萨斯帕克城会场，特朗普总统警告欧洲乱局可能迫使美国从北约后退。\n\n在为参议员罗杰·马歇尔助选、迎接 11 月 3 日中期选举的集会上，特朗普称法国曾是伟大国家，如今被移民、圣战分子与共产主义者淹没，并敦促加强美国边境以免重蹈覆辙。\n\n他批评美国在北约与援乌上支出过高，称盟友必须加码否则可能面临美方退出，并表示愿与普京、习近平直接会谈以结束乌克兰冲突。抗议者短暂打断，但被支持者声浪盖过；他同时推销「美国优先」及对农民与经济的承诺。", "url": "https://x.com/i/trending/2112384299999850805", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-20T21:20:55.000Z"}, {"id": "2112869350579310707", "domain": "国际", "title_en": "Trump Praises Iran Actions as Iranian Leaders Offer Diplomatic Path", "title_zh": "伊朗愿与美外交接触，同时警告战争只会加深苦难", "hook_en": "President Trump hailed his administration's moves against Iran as a historic success in preventing nuclear weapons, while Iranian officials extended a seven-day plan for talks amid Strait of Hormuz tensions.", "hook_zh": "伊朗外长阿拉格希伸出谈判之手，但明确表示：若选择战争，只会让发起者承受更深痛苦。", "summary_en": "Trump claimed his resolve stopped Iran from acquiring and using nuclear weapons, something no prior president achieved. In response, Iran's Foreign Minister Abbas Araghchi outlined a UN-presented framework: reopen the Strait of Hormuz on day six and start final deal talks on day seven, but only if the U.S. shows sincere trust-building steps after past strikes. President Masoud Pezeshkian stressed threats and sanctions must end first for meaningful dialogue, as both sides navigate deep mistrust and global energy concerns.", "summary_zh": "阿拉格希称，若美方拿出真诚建立信任的步骤迈向公正方案，伊朗愿推进外交，并概述上月联大提出的七部分框架，称其与既往美方协议方向一致。他强调伊朗对霍尔木兹海峡的影响力——在制裁解除等条件满足前海峡仍关闭——背景是长达约八个月的冲突、谈判破裂与袭击。总统佩泽希齐扬要求先有解除威胁的具体行动再谈对话；美国国务卿鲁比奥则认为任何协议都极其困难。经巴基斯坦、卡塔尔等斡旋的间接接触仍在继续，全球能源市场密切关注。", "body_en": "Iran Offers Diplomacy with US but Warns of War's Failure.\n\nIran's Foreign Minister Abbas Araghchi extended an open hand for talks, but made clear that war would only deepen the pain for those who choose it.\n\nAraghchi stated Iran is ready to pursue diplomacy if the US shows sincere trust-building steps toward a just solution, outlining a seven-part framework from last month's UN General Assembly that aligns with prior US agreements.\n\nHe highlighted Iran's leverage over the Strait of Hormuz, which remains closed until conditions like lifted sanctions are met, amid an eight-month conflict involving collapsed talks and attacks. President Pezeshkian called for concrete actions to remove threats before dialogue, while US Secretary Marco Rubio deemed any deal extremely difficult; indirect contacts continue via mediators like Pakistan and Qatar as global energy markets watch closely.", "body_zh": "伊朗愿与美外交接触，同时警告战争只会加深苦难。\n\n伊朗外长阿拉格希伸出谈判之手，但明确表示：若选择战争，只会让发起者承受更深痛苦。\n\n阿拉格希称，若美方拿出真诚建立信任的步骤迈向公正方案，伊朗愿推进外交，并概述上月联大提出的七部分框架，称其与既往美方协议方向一致。他强调伊朗对霍尔木兹海峡的影响力——在制裁解除等条件满足前海峡仍关闭——背景是长达约八个月的冲突、谈判破裂与袭击。\n\n总统佩泽希齐扬要求先有解除威胁的具体行动再谈对话；美国国务卿鲁比奥则认为任何协议都极其困难。经巴基斯坦、卡塔尔等斡旋的间接接触仍在继续，全球能源市场密切关注。", "url": "https://x.com/i/trending/2112869350579310707", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-21T22:40:50.000Z"}, {"id": "2112994548645540037", "domain": "国际", "title_en": "National Security Officials Prep States for Potential Trump Midterm Interference", "title_zh": "国家安全官员为潜在的特朗普中期干预做好准备", "hook_en": "A handful of U.S. national security veterans have quietly met with governors and lawmakers in 10 states, discussing worst-case scenarios like military at polls or fraud challenges.", "hook_zh": "少数美国国家安全退伍军人悄悄会见了10个州的州长和立法者，讨论了最坏的情况，如民意调查中的军队或欺诈挑战。", "summary_en": "The Washington Post detailed how about 10 current and former officials, many from the Defense Department, advised bipartisan state and congressional leaders on handling possible federal interference in the November 3 midterms. They focused on precautionary steps amid fears for democratic norms, without partisan motives. Critics labeled it a plot against the administration, while supporters cited January 6 as justification for vigilance; no White House response has surfaced as the debate underscores election tensions.", "summary_zh": "《华盛顿邮报》详细介绍了大约10名现任和前任官员（其中许多来自国防部）如何在11月3日的中期选举中向两党州和国会领导人提出建议，以应对可能的联邦干预。他们专注于预防措施，担心民主规范，没有党派动机。 批评者称这是反对政府的阴谋，而支持者则认为1月6日是保持警惕的理由；随着辩论凸显选举紧张局势，白宫没有做出任何回应。", "body_en": "National Security Officials Prep States for Potential Trump Midterm Interference.\n\nA handful of U.S. national security veterans have quietly met with governors and lawmakers in 10 states, discussing worst-case scenarios like military at polls or fraud challenges.\n\nThe Washington Post detailed how about 10 current and former officials, many from the Defense Department, advised bipartisan state and congressional leaders on handling possible federal interference in the November 3 midterms.\n\nThey focused on precautionary steps amid fears for democratic norms, without partisan motives. Critics labeled it a plot against the administration, while supporters cited January 6 as justification for vigilance; no White House response has surfaced as the debate underscores election tensions.", "body_zh": "少数美国国家安全退伍军人悄悄会见了10个州的州长和立法者，讨论了最坏的情况，如民意调查中的军队或欺诈挑战。\n\n《华盛顿邮报》详细介绍了大约10名现任和前任官员（其中许多来自国防部）如何在11月3日的中期选举中向两党州和国会领导人提出建议，以应对可能的联邦干预。\n\n他们专注于预防措施，担心民主规范，没有党派动机。批评者称这是反对政府的阴谋，而支持者则认为1月6日是保持警惕的理由；随着辩论凸显选举紧张局势，白宫没有做出任何回应。", "url": "https://x.com/i/trending/2112994548645540037", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-21T19:58:43.000Z"}, {"id": "2112592169139855608", "domain": "国际", "title_en": "Hungary Blocks Ukraine and Moldova EU Accession Steps", "title_zh": "匈牙利阻挠乌克兰与摩尔多瓦入欧谈判下一步", "hook_en": "Just days after Ukraine passed a law protecting its Hungarian-speaking minority, Hungary halted the next phase of EU talks for both Ukraine and Moldova, leaving diplomats puzzled by the silence.", "hook_zh": "乌克兰刚通过保护匈牙利语少数群体法律数日，匈牙利却叫停乌、摩两国入盟谈判下一阶段，令外交官费解。", "summary_en": "At a meeting of EU technical experts on October 20, Hungary objected to advancing the final two negotiating clusters on green agenda, sustainable connectivity, resources, agriculture, and cohesion, while the other 26 member states supported the move. This follows recent progress, including Ukraine's minority protections law on October 12 and a meeting between Prime Minister Péter Magyar and President Volodymyr Zelenskyy to reset ties, which allowed earlier clusters to open. The block revives questions about Hungary's stance on EU enlargement, as unanimity is required, and observers note frustration over the unexplained decision despite outreach efforts.", "summary_zh": "10 月 20 日欧盟技术专家会上，匈牙利反对推进绿色议程、可持续互联、资源、农业与凝聚等最后两组谈判集群，其余 26 国支持。此前乌克兰 10 月 12 日通过少数群体保护法，总理佩特·毛扎尔与泽连斯基会晤试图重置关系，曾为打开更早集群创造条件。因需全体一致，此次否决再引关于匈牙利扩大立场的质疑；观察者对缺乏解释的决定感到沮丧。", "body_en": "Hungary Blocks Ukraine and Moldova EU Accession Steps.\n\nJust days after Ukraine passed a law protecting its Hungarian-speaking minority, Hungary halted the next phase of EU talks for both Ukraine and Moldova, leaving diplomats puzzled by the silence.\n\nAt a meeting of EU technical experts on October 20, Hungary objected to advancing the final two negotiating clusters on green agenda, sustainable connectivity, resources, agriculture, and cohesion, while the other 26 member states supported the move.\n\nThis follows recent progress, including Ukraine's minority protections law on October 12 and a meeting between Prime Minister Péter Magyar and President Volodymyr Zelenskyy to reset ties, which allowed earlier clusters to open. The block revives questions about Hungary's stance on EU enlargement, as unanimity is required, and observers note frustration over the unexplained decision despite outreach efforts.", "body_zh": "匈牙利阻挠乌克兰与摩尔多瓦入欧谈判下一步。\n\n乌克兰刚通过保护匈牙利语少数群体法律数日，匈牙利却叫停乌、摩两国入盟谈判下一阶段，令外交官费解。\n\n10 月 20 日欧盟技术专家会上，匈牙利反对推进绿色议程、可持续互联、资源、农业与凝聚等最后两组谈判集群，其余 26 国支持。\n\n此前乌克兰 10 月 12 日通过少数群体保护法，总理佩特·毛扎尔与泽连斯基会晤试图重置关系，曾为打开更早集群创造条件。因需全体一致，此次否决再引关于匈牙利扩大立场的质疑；观察者对缺乏解释的决定感到沮丧。", "url": "https://x.com/i/trending/2112592169139855608", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-20T17:18:54.000Z"}, {"id": "2112558002708648142", "domain": "国际", "title_en": "Zelensky's 2025 Warning on Russia Resurfaces Amid Skepticism", "title_zh": "泽连斯基 2025 年俄威胁警告片段再流传，遭质疑", "hook_en": "A 2025 clip of Ukrainian President Volodymyr Zelensky warning that a U.S. NATO exit means certain Russian occupation of Europe has people online pushing back hard.", "hook_zh": "一段 2025 年泽连斯基警告「美国若退出北约则俄罗斯必占欧洲」的视频再度传播，网上反驳声浪很大。", "summary_en": "In a February 16, 2025, NBC Meet the Press interview, Zelensky told host Kristen Welker that European NATO forces lack enough brigades to match Russia's military, predicting a 100 percent risk of occupation starting with smaller ex-Soviet NATO states if the U.S. withdraws. The resurfaced excerpt drew skeptical reactions, with comments calling it 'bullshit,' pointing to supposed contradictions about Russia's struggles in Ukraine, and labeling it hyperbolic or a plea for more aid. The discussion highlights ongoing divides over Russian threats, NATO roles, and Western support for Ukraine as debates on assistance levels persist.", "summary_zh": "在 2025 年 2 月 16 日 NBC《Meet the Press》采访中，泽连斯基对主持人 Kristen Welker 称欧洲北约部队旅级力量不足以匹敌俄军，若美国撤离，从前苏联加盟、现为北约成员的较小国家开始，占领风险「百分之百」。片段重出后引来「胡扯」等质疑，有人指其与俄在乌战场受挫的叙事矛盾，或视之为夸张与求援。讨论再度暴露对俄威胁、北约角色与西方援乌力度的深刻分裂。", "body_en": "Zelensky's 2025 Warning on Russia Resurfaces Amid Skepticism.\n\nA 2025 clip of Ukrainian President Volodymyr Zelensky warning that a U.S. NATO exit means certain Russian occupation of Europe has people online pushing back hard.\n\nIn a February 16, 2025, NBC Meet the Press interview, Zelensky told host Kristen Welker that European NATO forces lack enough brigades to match Russia's military, predicting a 100 percent risk of occupation starting with smaller ex-Soviet NATO states if the U.S. withdraws.\n\nThe resurfaced excerpt drew skeptical reactions, with comments calling it 'bullshit,' pointing to supposed contradictions about Russia's struggles in Ukraine, and labeling it hyperbolic or a plea for more aid. The discussion highlights ongoing divides over Russian threats, NATO roles, and Western support for Ukraine as debates on assistance levels persist.", "body_zh": "泽连斯基 2025 年俄威胁警告片段再流传，遭质疑。\n\n一段 2025 年泽连斯基警告「美国若退出北约则俄罗斯必占欧洲」的视频再度传播，网上反驳声浪很大。\n\n在 2025 年 2 月 16 日 NBC《Meet the Press》采访中，泽连斯基对主持人 Kristen Welker 称欧洲北约部队旅级力量不足以匹敌俄军，若美国撤离，从前苏联加盟、现为北约成员的较小国家开始，占领风险「百分之百」。\n\n片段重出后引来「胡扯」等质疑，有人指其与俄在乌战场受挫的叙事矛盾，或视之为夸张与求援。讨论再度暴露对俄威胁、北约角色与西方援乌力度的深刻分裂。", "url": "https://x.com/i/trending/2112558002708648142", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-20T17:59:26.000Z"}, {"id": "2113041960558600306", "domain": "国际", "title_en": "France Faces Protests as Bond Yields Hit 24-Year High", "title_zh": "法国抗议升温，国债收益率创 24 年新高", "hook_en": "As riots flare in French cities over school shortages and living costs, online users fired back with pointed stats on gun deaths in the U.S. versus heat deaths in France.", "hook_zh": "法国多城因学校短缺与生活成本爆发骚乱；网上有人用枪支致死率与热浪致死率数据隔空对线美法风险。", "summary_en": "A government-linked post highlighted low firearm homicide rates in France at 0.3 per 100,000 in 2021, dwarfed by the U.S. at 5.9, but replies flipped it to show France's higher heat-related mortality of 7.7 per 100,000 against 0.6 in the U.S., amid thousands of excess deaths from recent heat waves. Protests escalated into riots, fueled by economic strains and summer heat, while France's 10-year bond yield topped 5% for the first time since 2002 due to fiscal worries. The back-and-forth revealed splits over infrastructure vulnerabilities, violence rates, and the limits of raw data in comparing national challenges.", "summary_zh": "一则政府相关帖文强调法国 2021 年枪支他杀率约每 10 万人 0.3，远低于美国的 5.9；回复则翻出法国热相关死亡率约 7.7、美国约 0.6，并指向近期热浪超额死亡。抗议升级为骚乱，叠加经济压力与暑热；法国十年期国债收益率自 2002 年来首次越过 5%。争论折射基建脆弱性、暴力率与用原始数据比较国家挑战的局限。", "body_en": "France Faces Protests as Bond Yields Hit 24-Year High.\n\nAs riots flare in French cities over school shortages and living costs, online users fired back with pointed stats on gun deaths in the U.S. versus heat deaths in France.\n\nA government-linked post highlighted low firearm homicide rates in France at 0.3 per 100,000 in 2021, dwarfed by the U.S. at 5.9, but replies flipped it to show France's higher heat-related mortality of 7.7 per 100,000 against 0.6 in the U.S., amid thousands of excess deaths from recent heat waves.\n\nProtests escalated into riots, fueled by economic strains and summer heat, while France's 10-year bond yield topped 5% for the first time since 2002 due to fiscal worries. The back-and-forth revealed splits over infrastructure vulnerabilities, violence rates, and the limits of raw data in comparing national challenges.", "body_zh": "法国抗议升温，国债收益率创 24 年新高。\n\n法国多城因学校短缺与生活成本爆发骚乱；网上有人用枪支致死率与热浪致死率数据隔空对线美法风险。\n\n一则政府相关帖文强调法国 2021 年枪支他杀率约每 10 万人 0.3，远低于美国的 5.9；回复则翻出法国热相关死亡率约 7.7、美国约 0.6，并指向近期热浪超额死亡。\n\n抗议升级为骚乱，叠加经济压力与暑热；法国十年期国债收益率自 2002 年来首次越过 5%。争论折射基建脆弱性、暴力率与用原始数据比较国家挑战的局限。", "url": "https://x.com/i/trending/2113041960558600306", "category": "News", "topics": ["News", "Politics"], "updated_at": "2026-10-21T23:06:08.000Z"}, {"id": "2112897433646641610", "domain": "体育", "title_en": "The Times Apologizes to FIFA and Infantino After Retracting Salary Claims", "title_zh": "《泰晤士报》撤回婴凡蒂诺「秘密薪酬」报道并道歉", "hook_en": "The Times pulled back a major story on FIFA president Gianni Infantino's alleged secret salary, issuing a full apology to him and the organization.", "hook_zh": "《泰晤士报》撤回有关国际足联主席詹尼·婴凡蒂诺所谓秘密薪酬的重大报道，并向其与国际足联正式道歉。", "summary_en": "On October 13, 2026, the British newspaper reported that Infantino received an undeclared second salary not listed in FIFA's filings, along with claims about a Miami property purchase and ties to Shadi LLC. The paper later corrected these errors, explaining that Swiss rules exclude expenses from compensation reports, Infantino did not buy the property, and neither he nor his family owns or controls Shadi LLC. FIFA accepted the apology but pointed to a broader effort to undermine them, especially as Infantino eyes re-election next year with candidacy deadlines nearing in November.", "summary_zh": "该报 10 月 13 日曾称婴凡蒂诺另有未申报第二份薪酬、涉迈阿密房产及与 Shadi LLC 关联。随后更正：瑞士规则不将部分费用列入薪酬披露、其未购该房产、本人及家人亦不拥有或控制 Shadi LLC。国际足联接受道歉，但指存在更广泛「抹黑」意图；婴凡蒂诺明年寻求连任，候选人申报期限临近 11 月。", "body_en": "The Times Apologizes to FIFA and Infantino After Retracting Salary Claims.\n\nThe Times pulled back a major story on FIFA president Gianni Infantino's alleged secret salary, issuing a full apology to him and the organization.\n\nOn October 13, 2026, the British newspaper reported that Infantino received an undeclared second salary not listed in FIFA's filings, along with claims about a Miami property purchase and ties to Shadi LLC.\n\nThe paper later corrected these errors, explaining that Swiss rules exclude expenses from compensation reports, Infantino did not buy the property, and neither he nor his family owns or controls Shadi LLC. FIFA accepted the apology but pointed to a broader effort to undermine them, especially as Infantino eyes re-election next year with candidacy deadlines nearing in November.", "body_zh": "《泰晤士报》撤回婴凡蒂诺「秘密薪酬」报道并道歉。\n\n《泰晤士报》撤回有关国际足联主席詹尼·婴凡蒂诺所谓秘密薪酬的重大报道，并向其与国际足联正式道歉。\n\n该报 10 月 13 日曾称婴凡蒂诺另有未申报第二份薪酬、涉迈阿密房产及与 Shadi LLC 关联。\n\n随后更正：瑞士规则不将部分费用列入薪酬披露、其未购该房产、本人及家人亦不拥有或控制 Shadi LLC。国际足联接受道歉，但指存在更广泛「抹黑」意图；婴凡蒂诺明年寻求连任，候选人申报期限临近 11 月。", "url": "https://x.com/i/trending/2112897433646641610", "category": "News", "topics": ["Sports"], "updated_at": "2026-10-21T16:42:23.000Z"}, {"id": "2112244932861997388", "domain": "体育", "title_en": "UEFA Presses FIFA with 42 Questions on Infantino's Trump Ties", "title_zh": "欧足联向国际足联提出 42 问，聚焦因凡蒂诺与特朗普关系", "hook_en": "UEFA leaders, fresh from raising alarms in Zurich, fired off a detailed letter to FIFA demanding answers on Gianni Infantino's close links to Donald Trump.", "hook_zh": "欧足联高层在苏黎世示警后，致函国际足联，要求就詹尼·因凡蒂诺与特朗普的关系等作出答复。", "summary_en": "UEFA General Secretary Theodore Theodoridis wrote to FIFA's Mattias Grafström, listing 42 questions on Infantino's leadership, including his business dealings with Trump like the abandoned FIFA Forward Enterprise plan tied to Thrive Capital and Joshua Kushner. The letter probes Trump's call to lift U.S. player Folarin Balogun's World Cup red card suspension, the unapproved FIFA Peace Prize to Trump, and multiple alleged conflicts from leases to sponsorships. It also covers Infantino's pay, spending on private jets, and governance ahead of the 2027 election, with responses due by November 2 to ensure accountability before candidate declarations on November 18.", "summary_zh": "欧足联秘书长西奥多·西奥多里迪斯致函国际足联的 Mattias Grafström，列出 42 个关于因凡蒂诺领导力的问题，包括其与特朗普的商业往来，例如已搁置、与特朗普相关的 FIFA Forward Enterprise 计划等。信函要求澄清治理、利益冲突与决策透明度，反映欧洲俱乐部与联赛对国际足联近期政治化动作的不安。围绕世界杯承办与商业安排的争论同步升温，双方尚未公开完整答复时间表。", "body_en": "UEFA Presses FIFA with 42 Questions on Infantino's Trump Ties.\n\nUEFA leaders, fresh from raising alarms in Zurich, fired off a detailed letter to FIFA demanding answers on Gianni Infantino's close links to Donald Trump.\n\nUEFA General Secretary Theodore Theodoridis wrote to FIFA's Mattias Grafström, listing 42 questions on Infantino's leadership, including his business dealings with Trump like the abandoned FIFA Forward Enterprise plan tied to Thrive Capital and Joshua Kushner. The letter probes Trump's call to lift U.S.\n\nplayer Folarin Balogun's World Cup red card suspension, the unapproved FIFA Peace Prize to Trump, and multiple alleged conflicts from leases to sponsorships. It also covers Infantino's pay, spending on private jets, and governance ahead of the 2027 election, with responses due by November 2 to ensure accountability before candidate declarations on November 18.", "body_zh": "欧足联向国际足联提出 42 问，聚焦因凡蒂诺与特朗普关系。\n\n欧足联高层在苏黎世示警后，致函国际足联，要求就詹尼·因凡蒂诺与特朗普的关系等作出答复。\n\n欧足联秘书长西奥多·西奥多里迪斯致函国际足联的 Mattias Grafström，列出 42 个关于因凡蒂诺领导力的问题，包括其与特朗普的商业往来，例如已搁置、与特朗普相关的 FIFA Forward Enterprise 计划等。\n\n信函要求澄清治理、利益冲突与决策透明度，反映欧洲俱乐部与联赛对国际足联近期政治化动作的不安。围绕世界杯承办与商业安排的争论同步升温，双方尚未公开完整答复时间表。", "url": "https://x.com/i/trending/2112244932861997388", "category": "Sports", "topics": ["UEFA Champions League"], "updated_at": "2026-10-20T00:20:21.000Z"}, {"id": "2112930908437426481", "domain": "体育", "title_en": "LeBron James Questions Knicks' Championship Whistle in Hot Mic Moment", "title_zh": "勒布朗热麦吐槽尼克斯「冠军哨」", "hook_en": "As the Knicks celebrated their first title in 53 years with rings and a banner, LeBron James muttered into a hot mic: 'They win one chip they get a championship whistle.' The comment lit up reactions right away.", "hook_zh": "尼克斯庆祝 53 年来首冠、颁发戒指与升起横幅之际，勒布朗·詹姆斯对着热麦嘀咕：「他们赢一个冠军就拿到冠军哨了。」评论立刻引爆讨论。", "summary_en": "During the Knicks' season opener at Madison Square Garden, the Philadelphia 76ers beat the defending champs 106-100, with James—noted as a new 76ers forward after leaving the Lakers—posting 14 points, nine rebounds, and six assists. His remark, caught on a hot mic amid the Knicks' ceremony, sparked fans to debate officiating favoritism, with some calling out hypocrisy given LeBron's foul-drawing history and others defending the 'championship whistle' idea. Knicks fans chanted 'We don’t want you' at him during free throws, while the 76ers pulled ahead in the third quarter behind James, Embiid, Maxey, and Brown.", "summary_zh": "尼克斯赛季揭幕战在麦迪逊广场花园进行，费城 76 人以 106-100 击败卫冕冠军；离开湖人、加盟 76 人的勒布朗贡献 14 分、9 篮板、6 助攻。他的热麦言论夹在尼克斯庆典中被捕捉到，球迷随即争论裁判是否偏袒——有人批评勒布朗造犯规「双标」，也有人认同「冠军哨」说法。尼克斯球迷在他罚球时高喊「我们不要你」，第三节 76 人在詹姆斯、恩比德、马克西与布朗带领下拉开比分。", "body_en": "LeBron James Questions Knicks' Championship Whistle in Hot Mic Moment.\n\nAs the Knicks celebrated their first title in 53 years with rings and a banner, LeBron James muttered into a hot mic: 'They win one chip they get a championship whistle.' The comment lit up reactions right away.\n\nDuring the Knicks' season opener at Madison Square Garden, the Philadelphia 76ers beat the defending champs 106-100, with James—noted as a new 76ers forward after leaving the Lakers—posting 14 points, nine rebounds, and six assists.\n\nHis remark, caught on a hot mic amid the Knicks' ceremony, sparked fans to debate officiating favoritism, with some calling out hypocrisy given LeBron's foul-drawing history and others defending the 'championship whistle' idea. Knicks fans chanted 'We don’t want you' at him during free throws, while the 76ers pulled ahead in the third quarter behind James, Embiid, Maxey, and Brown.", "body_zh": "勒布朗热麦吐槽尼克斯「冠军哨」。\n\n尼克斯庆祝 53 年来首冠、颁发戒指与升起横幅之际，勒布朗·詹姆斯对着热麦嘀咕：「他们赢一个冠军就拿到冠军哨了。」评论立刻引爆讨论。\n\n尼克斯赛季揭幕战在麦迪逊广场花园进行，费城 76 人以 106-100 击败卫冕冠军；离开湖人、加盟 76 人的勒布朗贡献 14 分、9 篮板、6 助攻。\n\n他的热麦言论夹在尼克斯庆典中被捕捉到，球迷随即争论裁判是否偏袒——有人批评勒布朗造犯规「双标」，也有人认同「冠军哨」说法。尼克斯球迷在他罚球时高喊「我们不要你」，第三节 76 人在詹姆斯、恩比德、马克西与布朗带领下拉开比分。", "url": "https://x.com/i/trending/2112930908437426481", "category": "Sports", "topics": ["NBA"], "updated_at": "2026-10-21T15:43:54.000Z"}, {"id": "2112623569473597808", "domain": "体育", "title_en": "Liverpool Fans Debate Skipping Villarreal Game for PSG-Barcelona Clash", "title_zh": "利物浦球迷纠结：欧冠主场与巴黎对巴萨同开", "hook_en": "Picture this: Liverpool's Champions League night at Anfield collides head-on with PSG versus Barcelona's star power, leaving fans torn on where to point their screens.", "hook_zh": "利物浦安菲尔德的欧冠之夜与巴黎圣日耳曼对阵巴塞罗那撞车，球迷纠结该把目光投向哪边屏幕。", "summary_en": "On Tuesday, Liverpool host Villarreal at Anfield at 8pm BST, the exact same time PSG welcomes Barcelona in another Champions League league-phase match. Fans are debating fiercely online after one called out those tempted to watch the glamorous PSG-Barcelona tie instead, with most insisting loyalty means sticking with the Reds no matter what. Some admit the pull of players like Lamine Yamal and Ousmane Dembélé but plan to prioritize their team, while others suggest splitting screens or note the spat feels like an online-only thing. It highlights football's tug between club devotion and big European showdowns.", "summary_zh": "周二英国夏令时晚 8 点，利物浦在安菲尔德主场迎战比利亚雷亚尔，同一时间巴黎在欧冠联赛阶段迎战巴萨。有人在网上点名「忍不住去看巴黎—巴萨」的球迷后，讨论升温；多数人坚持忠诚就该死守红军。也有人承认亚马尔、登贝莱等球星很有吸引力，但仍计划优先看本队，或考虑分屏观看。这场争论折射出俱乐部忠诚与「大欧洲对决」吸引力之间的拉扯。", "body_en": "Liverpool Fans Debate Skipping Villarreal Game for PSG-Barcelona Clash.\n\nPicture this: Liverpool's Champions League night at Anfield collides head-on with PSG versus Barcelona's star power, leaving fans torn on where to point their screens.\n\nOn Tuesday, Liverpool host Villarreal at Anfield at 8pm BST, the exact same time PSG welcomes Barcelona in another Champions League league-phase match. Fans are debating fiercely online after one called out those tempted to watch the glamorous PSG-Barcelona tie instead, with most insisting loyalty means sticking with the Reds no matter what.\n\nSome admit the pull of players like Lamine Yamal and Ousmane Dembélé but plan to prioritize their team, while others suggest splitting screens or note the spat feels like an online-only thing. It highlights football's tug between club devotion and big European showdowns.", "body_zh": "利物浦球迷纠结：欧冠主场与巴黎对巴萨同开。\n\n利物浦安菲尔德的欧冠之夜与巴黎圣日耳曼对阵巴塞罗那撞车，球迷纠结该把目光投向哪边屏幕。\n\n周二英国夏令时晚 8 点，利物浦在安菲尔德主场迎战比利亚雷亚尔，同一时间巴黎在欧冠联赛阶段迎战巴萨。有人在网上点名「忍不住去看巴黎—巴萨」的球迷后，讨论升温；多数人坚持忠诚就该死守红军。\n\n也有人承认亚马尔、登贝莱等球星很有吸引力，但仍计划优先看本队，或考虑分屏观看。这场争论折射出俱乐部忠诚与「大欧洲对决」吸引力之间的拉扯。", "url": "https://x.com/i/trending/2112623569473597808", "category": "Sports", "topics": ["UEFA Champions League"], "updated_at": "2026-10-20T19:23:57.000Z"}, {"id": "2112527510105919970", "domain": "体育", "title_en": "Ex-NFL Player Accuses Refs of Rigging Games for Chiefs", "title_zh": "前 NFL 球员指控裁判偏袒酋长，争议再起", "hook_en": "Breiden Fehoko leaned into the mic on a podcast and called out what he saw as late-game favoritism for the Chiefs. His words tapped into frustrations many rival fans have felt for years.", "hook_zh": "Breiden Fehoko 在播客上称第四节有「幽灵判罚」帮堪萨斯城赢球，戳中多年对手球迷的怒点。", "summary_en": "Former Chargers defensive tackle Breiden Fehoko claimed on Jason Whitlock's podcast that officials give Kansas City 'ghost calls' in the fourth quarter to swing tight games. He pointed to a pattern where penalties bail out the Chiefs when trailing, calling it a 'mockery,' and challenged refs to stay impartial in the playoffs. Critics noted his limited experience—just one game against Kansas City and 19 career appearances—while fans referenced moments like the 2022 AFC Championship as supposed proof. The debate highlights ongoing gripes about NFL officiating but lacks hard evidence of rigging.", "summary_zh": "前闪电防守截锋 Fehoko 在 Jason Whitlock 播客上声称，官员会在第四节用「幽灵判罚」扭转胶着比赛，落后时点球「救」酋长，称之为「嘲弄」，并要求季后赛保持公正。批评指出他仅打过一场对阵堪萨斯城、生涯出场约 19 次；球迷则搬出 2022 年 AFC 冠军赛等片段作「证据」。争论凸显对 NFL 执法的积怨，但缺乏操纵确证。", "body_en": "Ex-NFL Player Accuses Refs of Rigging Games for Chiefs.\n\nBreiden Fehoko leaned into the mic on a podcast and called out what he saw as late-game favoritism for the Chiefs. His words tapped into frustrations many rival fans have felt for years.\n\nFormer Chargers defensive tackle Breiden Fehoko claimed on Jason Whitlock's podcast that officials give Kansas City 'ghost calls' in the fourth quarter to swing tight games. He pointed to a pattern where penalties bail out the Chiefs when trailing, calling it a 'mockery,' and challenged refs to stay impartial in the playoffs.\n\nCritics noted his limited experience—just one game against Kansas City and 19 career appearances—while fans referenced moments like the 2022 AFC Championship as supposed proof. The debate highlights ongoing gripes about NFL officiating but lacks hard evidence of rigging.", "body_zh": "前 NFL 球员指控裁判偏袒酋长，争议再起。\n\nBreiden Fehoko 在播客上称第四节有「幽灵判罚」帮堪萨斯城赢球，戳中多年对手球迷的怒点。\n\n前闪电防守截锋 Fehoko 在 Jason Whitlock 播客上声称，官员会在第四节用「幽灵判罚」扭转胶着比赛，落后时点球「救」酋长，称之为「嘲弄」，并要求季后赛保持公正。\n\n批评指出他仅打过一场对阵堪萨斯城、生涯出场约 19 次；球迷则搬出 2022 年 AFC 冠军赛等片段作「证据」。争论凸显对 NFL 执法的积怨，但缺乏操纵确证。", "url": "https://x.com/i/trending/2112527510105919970", "category": "Sports", "topics": ["NFL"], "updated_at": "2026-10-21T02:52:40.000Z"}, {"id": "2112281281501528167", "domain": "体育", "title_en": "Kyrie Irving Doubts Playing into His Early 40s as NBA Evolves", "title_zh": "凯里·欧文质疑自己能否像勒布朗一样打到四十出头", "hook_en": "Kyrie Irving paused during media day to reflect on a league that's changed since his childhood dreams. At 34, he loves the game but sees modern pressures making a long career like LeBron's unlikely for him.", "hook_zh": "凯里·欧文在媒体日反思：联盟已非儿时梦想中的模样。34 岁的他仍爱篮球，但觉现代压力让勒布朗式超长生涯对己不太可能。", "summary_en": "The Mavericks guard shared honest thoughts after practice Monday, saying he can't envision suiting up at 42 or 43 amid social media, gambling, and a more 'robotic' NBA far from the one he fell in love with as a kid. Irving praised LeBron James, Stephen Curry, and Kevin Durant for their longevity while noting shifts like mental health talks and tipping meetings that weren't around when he entered as the 2011 No. 1 pick. Preparing for his 2026-27 return after missing last season with a torn ACL, he's focused on enjoying competition and personal growth as Dallas opens Wednesday against Houston.", "summary_zh": "这名独行侠后卫周一训练后坦诚，在社交媒体、博彩与更「机械」的 NBA 中，难以想象自己 42、43 岁还穿球衣——那与儿时爱上的篮球相去甚远。他称赞勒布朗、库里与杜兰特的长寿，同时提到心理健康讨论、赛前提示会等入行时（2011 年状元秀）尚不存在的变化。在因 ACL 撕裂缺席上赛季后，他备战 2026–27 回归，专注享受竞争与成长，达拉斯周三对休斯敦揭幕。", "body_en": "Kyrie Irving Doubts Playing into His Early 40s as NBA Evolves.\n\nKyrie Irving paused during media day to reflect on a league that's changed since his childhood dreams. At 34, he loves the game but sees modern pressures making a long career like LeBron's unlikely for him.\n\nThe Mavericks guard shared honest thoughts after practice Monday, saying he can't envision suiting up at 42 or 43 amid social media, gambling, and a more 'robotic' NBA far from the one he fell in love with as a kid. Irving praised LeBron James, Stephen Curry, and Kevin Durant for their longevity while noting shifts like mental health talks and tipping meetings that weren't around when he entered as the 2011 No.\n\n1 pick. Preparing for his 2026-27 return after missing last season with a torn ACL, he's focused on enjoying competition and personal growth as Dallas opens Wednesday against Houston.", "body_zh": "凯里·欧文质疑自己能否像勒布朗一样打到四十出头。\n\n凯里·欧文在媒体日反思：联盟已非儿时梦想中的模样。34 岁的他仍爱篮球，但觉现代压力让勒布朗式超长生涯对己不太可能。\n\n这名独行侠后卫周一训练后坦诚，在社交媒体、博彩与更「机械」的 NBA 中，难以想象自己 42、43 岁还穿球衣——那与儿时爱上的篮球相去甚远。\n\n他称赞勒布朗、库里与杜兰特的长寿，同时提到心理健康讨论、赛前提示会等入行时（2011 年状元秀）尚不存在的变化。在因 ACL 撕裂缺席上赛季后，他备战 2026–27 回归，专注享受竞争与成长，达拉斯周三对休斯敦揭幕。", "url": "https://x.com/i/trending/2112281281501528167", "category": "Sports", "topics": [], "updated_at": "2026-10-20T15:54:00.000Z"}, {"id": "2112984435729576320", "domain": "体育", "title_en": "NFL Pushes Ahead with Paris Game Amid French Riots", "title_zh": "NFL在巴黎骚乱中与法国队比赛", "hook_en": "As riots rage through Paris with cars burning and clashes with police, the NFL insists its first regular-season game in France goes on. T.J. Watt's wife Dani captured the unease, posting: 'Tell me how this one makes sense???'.", "hook_zh": "随着骚乱笼罩着巴黎的冲突、抢劫和逮捕， NFL准备在那里进行第一场常规赛，引起了球员家属和评论家的尖锐质疑。", "summary_en": "The Pittsburgh Steelers face the New Orleans Saints on October 25 at Stade de France, despite violent protests over rising costs and poor services that have led to thousands of arrests and curfews. Critics, including players' families and commentators like Mike Florio, question the risks to players, coaches, fans, and staff in the unrest. NFL executives emphasize close coordination with French authorities and the U.S. State Department for heightened security, with no plans to cancel or relocate.", "summary_zh": "匹兹堡钢人队于10月25日在法兰西体育场面对新奥尔良圣徒，尽管抗议生活费用，学校条件和公共服务导致数千人被捕和受伤。美国国家橄榄球联盟（ NFL ）专员罗杰·古德尔（ Roger Goodell ）坚称，抗议活动大多是和平的，球员们没有面临危险，体育场的安全措施得到了法国当局和美国国务院的协调。 钢人队明星T.J.瓦特的妻子丹尼·瓦特（ Dani Watt ）公开询问如何让球员和家人陷入混乱，而联盟则继续推进准备工作。", "body_en": "NFL Sticks with France Game Amid Paris Riots.\n\nAs riots grip Paris with clashes, looting, and arrests, the NFL readies its first regular-season game there, drawing sharp questions from players' families and critics.\n\nThe Pittsburgh Steelers face the New Orleans Saints at Stade de France on October 25, despite unrest from protests over living costs, school conditions, and public services that led to thousands of arrests and injuries. NFL Commissioner Roger Goodell insists the protests are mostly peaceful and players face no danger, with ramped-up stadium security coordinated with French authorities and the U.S.\n\nState Department. Dani Watt, wife of Steelers star T.J. Watt, publicly asked how sending players and families into the turmoil makes sense, while the league presses ahead with preparations unchanged.", "body_zh": "随着骚乱笼罩着巴黎的冲突、抢劫和逮捕， NFL准备在那里进行第一场常规赛，引起了球员家属和评论家的尖锐质疑。\n\n匹兹堡钢人队于10月25日在法兰西体育场面对新奥尔良圣徒，尽管抗议生活费用，学校条件和公共服务导致数千人被捕和受伤。\n\n美国国家橄榄球联盟（ NFL ）专员罗杰·古德尔（ Roger Goodell ）坚称，抗议活动大多是和平的，球员们没有面临危险，体育场的安全措施得到了法国当局和美国国务院的协调。钢人队明星T.J.瓦特的妻子丹尼·瓦特（ Dani Watt ）公开询问如何让球员和家人陷入混乱，而联盟则继续推进准备工作。", "url": "https://x.com/i/trending/2112984435729576320", "category": "Sports", "topics": ["NFL"], "updated_at": "2026-10-21T21:52:44.000Z"}, {"id": "2112637280108335380", "domain": "体育", "title_en": "NFL Umpire Larry Smith Tears Quadriceps in Rare Non-Contact Injury at Wembley", "title_zh": "NFL 裁判拉里·史密斯温布利非对抗拉伤股四头肌赛季报销", "hook_en": "Larry Smith slipped on wet grass between plays, stood briefly, then collapsed clutching his leg—a shocking moment that sidelined the umpire for good this season.", "hook_zh": "拉里·史密斯在死球间隙踩湿草滑倒，起身后捂腿倒地，本赛季就此告别场边。", "summary_en": "During the Houston Texans-Jacksonville Jaguars game at Wembley Stadium, second-year NFL umpire Larry Smith tore his right quadriceps in a non-contact slip early in the first quarter. Trainers from both teams helped him off the field on a cart, and his crew finished with six officials while splitting his duties. A middle school principal from Kansas City, Kansas, in his full-time job, Smith won't return until 2027, prompting the NFL to seek a replacement like swing official Tab Slaughter or Ian Malepeai for referee Shawn Hochuli’s crew. Veteran line judge Carl Johnson knelt by his side, hat off in what looked like a prayer, as fans shared surprised laughs about refs joining the injury list.", "summary_zh": "休斯敦得州人队对阵杰克逊维尔美洲虎队的温布利比赛中，二年级主裁判拉里·史密斯在首节早段非对抗滑倒，右股四头肌撕裂。双方训练师用推车将其抬离，组员以六人完赛并分担职责。史密斯全职为堪萨斯城中学校长，预计 2027 年才归队；联盟考虑由轮换裁判 Tab Slaughter 或 Ian Malepeai 补进 Shawn Hochuli 组。边裁 Carl Johnson 脱帽跪旁似在祈祷；球迷调侃「裁判也进伤病名单」。", "body_en": "NFL Umpire Larry Smith Tears Quadriceps in Rare Non-Contact Injury at Wembley.\n\nLarry Smith slipped on wet grass between plays, stood briefly, then collapsed clutching his leg—a shocking moment that sidelined the umpire for good this season.\n\nDuring the Houston Texans-Jacksonville Jaguars game at Wembley Stadium, second-year NFL umpire Larry Smith tore his right quadriceps in a non-contact slip early in the first quarter. Trainers from both teams helped him off the field on a cart, and his crew finished with six officials while splitting his duties.\n\nA middle school principal from Kansas City, Kansas, in his full-time job, Smith won't return until 2027, prompting the NFL to seek a replacement like swing official Tab Slaughter or Ian Malepeai for referee Shawn Hochuli’s crew. Veteran line judge Carl Johnson knelt by his side, hat off in what looked like a prayer, as fans shared surprised laughs about refs joining the injury list.", "body_zh": "NFL 裁判拉里·史密斯温布利非对抗拉伤股四头肌赛季报销。\n\n拉里·史密斯在死球间隙踩湿草滑倒，起身后捂腿倒地，本赛季就此告别场边。\n\n休斯敦得州人队对阵杰克逊维尔美洲虎队的温布利比赛中，二年级主裁判拉里·史密斯在首节早段非对抗滑倒，右股四头肌撕裂。双方训练师用推车将其抬离，组员以六人完赛并分担职责。\n\n史密斯全职为堪萨斯城中学校长，预计 2027 年才归队；联盟考虑由轮换裁判 Tab Slaughter 或 Ian Malepeai 补进 Shawn Hochuli 组。边裁 Carl Johnson 脱帽跪旁似在祈祷；球迷调侃「裁判也进伤病名单」。", "url": "https://x.com/i/trending/2112637280108335380", "category": "Sports", "topics": ["NFL"], "updated_at": "2026-10-20T20:16:29.000Z"}, {"id": "2113011790829293638", "domain": "体育", "title_en": "FOX Sports Adds Gulfstream Park to America's Day at the Races Starting 2027", "title_zh": "FOX 体育 2027 年起将 Gulfstream Park 纳入赛马日直播", "hook_en": "Veteran broadcaster Todd Schrupp is thrilled to return to South Florida, where he first honed his skills at Calder Racecourse, now calling races at Gulfstream Park.", "hook_zh": "资深解说 Todd Schrupp 欣喜重返南佛罗里达，从 Calder 练就的功力将用于 Gulfstream Park 赛马解说。", "summary_en": "FOX Sports is expanding its horse racing coverage by including Gulfstream Park's Championship Meet in America's Day at the Races from 2027, with the $1 million EquiTrack Florida Derby airing live on the FOX network on March 27. The multi-year deal with NYRA and 1/ST covers the winter meet from late November through March at the Hallandale Beach track, featuring stakes like the Pegasus World Cup and key Triple Crown preps that have produced 26 Kentucky Derby winners since 1952. This addition complements existing coverage from Saratoga, Belmont, Del Mar, and Oaklawn, building nearly 1,000 hours of live racing annually and creating a year-round calendar of top American races.", "summary_zh": "FOX Sports 与 NYRA、1/ST 多年协议自 2027 年起把 Gulfstream Park 冠军赛季纳入 America's Day at the Races；3 月 27 日百万美元 EquiTrack 佛罗里达德比将在 FOX 电视网直播。覆盖哈利戴海滩赛道冬末至三月赛事，包括飞马世界杯及自 1952 年来产出 26 位肯塔基德比冠军的三冠预赛。此举补充萨拉托加、贝尔蒙特、Del Mar、Oaklawn 等转播，年直播赛马近千小时，形成全美顶级赛马全年日历。", "body_en": "FOX Sports Adds Gulfstream Park to America's Day at the Races Starting 2027.\n\nVeteran broadcaster Todd Schrupp is thrilled to return to South Florida, where he first honed his skills at Calder Racecourse, now calling races at Gulfstream Park.\n\nFOX Sports is expanding its horse racing coverage by including Gulfstream Park's Championship Meet in America's Day at the Races from 2027, with the $1 million EquiTrack Florida Derby airing live on the FOX network on March 27.\n\nThe multi-year deal with NYRA and 1/ST covers the winter meet from late November through March at the Hallandale Beach track, featuring stakes like the Pegasus World Cup and key Triple Crown preps that have produced 26 Kentucky Derby winners since 1952. This addition complements existing coverage from Saratoga, Belmont, Del Mar, and Oaklawn, building nearly 1,000 hours of live racing annually and creating a year-round calendar of top American races.", "body_zh": "FOX 体育 2027 年起将 Gulfstream Park 纳入赛马日直播。\n\n资深解说 Todd Schrupp 欣喜重返南佛罗里达，从 Calder 练就的功力将用于 Gulfstream Park 赛马解说。\n\nFOX Sports 与 NYRA、1/ST 多年协议自 2027 年起把 Gulfstream Park 冠军赛季纳入 America's Day at the Races；3 月 27 日百万美元 EquiTrack 佛罗里达德比将在 FOX 电视网直播。\n\n覆盖哈利戴海滩赛道冬末至三月赛事，包括飞马世界杯及自 1952 年来产出 26 位肯塔基德比冠军的三冠预赛。此举补充萨拉托加、贝尔蒙特、Del Mar、Oaklawn 等转播，年直播赛马近千小时，形成全美顶级赛马全年日历。", "url": "https://x.com/i/trending/2113011790829293638", "category": "Sports", "topics": ["Sports"], "updated_at": "2026-10-21T21:04:17.000Z"}, {"id": "2112138759433252907", "domain": "体育", "title_en": "Kimi Antonelli Poised to Clinch F1 Title in Texas", "title_zh": "安东内利德州站有望锁定 F1 最年轻冠军", "hook_en": "At just 20 years old, Kimi Antonelli stands on the brink of F1 history in Austin, where a strong finish could crown him the youngest champion ever.", "hook_zh": "年仅 20 岁的基米·安东内利在奥斯汀站濒临创造历史：出色完赛或使他成为最年轻世界冠军。", "summary_en": "The Mercedes driver leads the 2026 championship by 102 points over George Russell after 17 races, with Lewis Hamilton, Max Verstappen, Charles Leclerc, and Lando Norris still mathematically alive but far behind. He can seal the title at the United States Grand Prix if he wins while Russell places ninth or worse and Hamilton fifth or lower, shattering Sebastian Vettel's record set at 23 years and 134 days. Track data shows Antonelli's top race pace this season, though Mercedes boss Toto Wolff calls the math tough, and fans buzz with excitement and jinx worries ahead of the Americas triple-header.", "summary_zh": "梅赛德斯车手在 17 站后以 102 分领跑乔治·拉塞尔；汉密尔顿、维斯塔潘、勒克莱尔、诺里斯仍有数学可能但差距大。若美国大奖赛他夺冠且拉塞尔第九或更后、汉密尔顿第五或更后，即可加冕，并打破维特尔 23 岁又 134 天的纪录。赛道数据显示其本季赛速顶尖，梅奔老板托托·沃尔夫称计算苛刻；粉丝既兴奋又怕「乌鸦嘴」，美洲三连赛将至。", "body_en": "Kimi Antonelli Poised to Clinch F1 Title in Texas.\n\nAt just 20 years old, Kimi Antonelli stands on the brink of F1 history in Austin, where a strong finish could crown him the youngest champion ever.\n\nThe Mercedes driver leads the 2026 championship by 102 points over George Russell after 17 races, with Lewis Hamilton, Max Verstappen, Charles Leclerc, and Lando Norris still mathematically alive but far behind.\n\nHe can seal the title at the United States Grand Prix if he wins while Russell places ninth or worse and Hamilton fifth or lower, shattering Sebastian Vettel's record set at 23 years and 134 days. Track data shows Antonelli's top race pace this season, though Mercedes boss Toto Wolff calls the math tough, and fans buzz with excitement and jinx worries ahead of the Americas triple-header.", "body_zh": "安东内利德州站有望锁定 F1 最年轻冠军。\n\n年仅 20 岁的基米·安东内利在奥斯汀站濒临创造历史：出色完赛或使他成为最年轻世界冠军。\n\n梅赛德斯车手在 17 站后以 102 分领跑乔治·拉塞尔；汉密尔顿、维斯塔潘、勒克莱尔、诺里斯仍有数学可能但差距大。\n\n若美国大奖赛他夺冠且拉塞尔第九或更后、汉密尔顿第五或更后，即可加冕，并打破维特尔 23 岁又 134 天的纪录。赛道数据显示其本季赛速顶尖，梅奔老板托托·沃尔夫称计算苛刻；粉丝既兴奋又怕「乌鸦嘴」，美洲三连赛将至。", "url": "https://x.com/i/trending/2112138759433252907", "category": "Sports", "topics": ["Formula 1"], "updated_at": "2026-10-20T23:48:55.000Z"}, {"id": "2112326602743050735", "domain": "体育", "title_en": "MLB Fans Debate Salary Cap as Small-Market Teams Reach World Series", "title_zh": "小市场球队打进世界大赛，MLB 薪资帽争议再起", "hook_en": "The Milwaukee Brewers swept the Dodgers in the NLCS, sending two low-spending teams to the World Series and fueling fresh talk about whether MLB needs a salary cap.", "hook_zh": "密尔沃基酿酒人横扫道奇晋级，两支低薪球队会师世界大赛，薪资硬帽争论再被点燃。", "summary_en": "Brewers, with the 19th-ranked payroll, beat the high-spending Dodgers in four games, drawing 7.53 million viewers—the best LCS audience since 2015—and now face the Rays for a first-time champion. Owners propose a $245.3 million hard cap and $171.2 million floor starting 2027 to boost balance, but players reject it as a wage suppressor. Small-market fans like Pirates supporters cheer the idea to limit talent hoarding, while critics say location and culture still sway stars, and Brewers' run proves smart spending works amid wide payroll gaps like the Dodgers' $433 million projection.", "summary_zh": "薪资排名第 19 的酿酒人四场淘汰高薪道奇，联盟冠军赛收视 753 万为 2015 年来最佳，将与光芒争夺队史首冠。老板提案 2027 年起硬帽约 2.453 亿美元、地板约 1.712 亿以促平衡，球员方斥为压低工资。海盗等小市场球迷欢迎限制囤积球星；批评者称地点与文化仍左右去留，酿酒人证明精明投入可行——对比道奇预计约 4.33 亿薪资差距悬殊。", "body_en": "MLB Fans Debate Salary Cap as Small-Market Teams Reach World Series.\n\nThe Milwaukee Brewers swept the Dodgers in the NLCS, sending two low-spending teams to the World Series and fueling fresh talk about whether MLB needs a salary cap.\n\nBrewers, with the 19th-ranked payroll, beat the high-spending Dodgers in four games, drawing 7.53 million viewers—the best LCS audience since 2015—and now face the Rays for a first-time champion.\n\nOwners propose a $245.3 million hard cap and $171.2 million floor starting 2027 to boost balance, but players reject it as a wage suppressor. Small-market fans like Pirates supporters cheer the idea to limit talent hoarding, while critics say location and culture still sway stars, and Brewers' run proves smart spending works amid wide payroll gaps like the Dodgers' $433 million projection.", "body_zh": "小市场球队打进世界大赛，MLB 薪资帽争议再起。\n\n密尔沃基酿酒人横扫道奇晋级，两支低薪球队会师世界大赛，薪资硬帽争论再被点燃。\n\n薪资排名第 19 的酿酒人四场淘汰高薪道奇，联盟冠军赛收视 753 万为 2015 年来最佳，将与光芒争夺队史首冠。\n\n老板提案 2027 年起硬帽约 2.453 亿美元、地板约 1.712 亿以促平衡，球员方斥为压低工资。海盗等小市场球迷欢迎限制囤积球星；批评者称地点与文化仍左右去留，酿酒人证明精明投入可行——对比道奇预计约 4.33 亿薪资差距悬殊。", "url": "https://x.com/i/trending/2112326602743050735", "category": "Sports", "topics": ["MLB"], "updated_at": "2026-10-21T05:20:54.000Z"}, {"id": "2113041959019245966", "domain": "体育", "title_en": "LeBron James Practices Golf Swing During National Anthem in NBA Debut", "title_zh": "勒布朗 NBA 首秀奏国歌时练高尔夫挥杆引争议", "hook_en": "On his debut night with the 76ers at Madison Square Garden, LeBron James twisted into a golf swing as the national anthem played, drawing eyes from teammates and fans alike.", "hook_zh": "勒布朗·詹姆斯加盟 76 人后在麦迪逊广场花园首秀，国歌响起时比划高尔夫挥杆，队友球迷目光齐聚。", "summary_en": "The 41-year-old, now with Philadelphia after leaving the Lakers, stood in the player line on October 20 during pregame ceremonies before the Knicks game, where his arm swings caught on video. Critics called it disrespectful to the anthem's roots in the War of 1812 and accused him of seeking attention, while some saw it as routine loosening up and Barstool Sports joked it was never a bad time for The King's swing. James contributed 14 points and nine rebounds in the 76ers' 106-100 win that spoiled New York's ring night, but the clip dominated discussions alongside his performance.", "summary_zh": "41 岁的他离开湖人加盟费城，10 月 20 日对阵尼克斯赛前站在球员列中，摆臂动作被拍下。批评者称对源自 1812 年战争的国歌不敬、博取眼球；也有人视为赛前热身，Barstool 玩笑称「国王挥杆永远不嫌早」。他贡献 14 分 9 篮板，助 76 人以 106-100 搅局尼克斯夺冠之夜，但该片段与表现同样刷屏。", "body_en": "LeBron James Practices Golf Swing During National Anthem in NBA Debut.\n\nOn his debut night with the 76ers at Madison Square Garden, LeBron James twisted into a golf swing as the national anthem played, drawing eyes from teammates and fans alike.\n\nThe 41-year-old, now with Philadelphia after leaving the Lakers, stood in the player line on October 20 during pregame ceremonies before the Knicks game, where his arm swings caught on video.\n\nCritics called it disrespectful to the anthem's roots in the War of 1812 and accused him of seeking attention, while some saw it as routine loosening up and Barstool Sports joked it was never a bad time for The King's swing. James contributed 14 points and nine rebounds in the 76ers' 106-100 win that spoiled New York's ring night, but the clip dominated discussions alongside his performance.", "body_zh": "勒布朗 NBA 首秀奏国歌时练高尔夫挥杆引争议。\n\n勒布朗·詹姆斯加盟 76 人后在麦迪逊广场花园首秀，国歌响起时比划高尔夫挥杆，队友球迷目光齐聚。\n\n41 岁的他离开湖人加盟费城，10 月 20 日对阵尼克斯赛前站在球员列中，摆臂动作被拍下。\n\n批评者称对源自 1812 年战争的国歌不敬、博取眼球；也有人视为赛前热身，Barstool 玩笑称「国王挥杆永远不嫌早」。他贡献 14 分 9 篮板，助 76 人以 106-100 搅局尼克斯夺冠之夜，但该片段与表现同样刷屏。", "url": "https://x.com/i/trending/2113041959019245966", "category": "Sports", "topics": ["NBA"], "updated_at": "2026-10-21T23:06:00.000Z"}, {"id": "2112946152933089721", "domain": "娱乐", "title_en": "CMA Tribute Celebrates Dolly Parton's Life and Music Tonight", "title_zh": "CMA致敬特别荣誉Dolly Parton今晚在ABC", "hook_en": "Country music icons gather in Nashville tonight to honor Dolly Parton with her timeless hits and heartfelt stories, capturing the sunshine she brought to the world.", "hook_zh": "乡村音乐爱好者正在聚集他们的组织，庆祝多莉·帕顿（ Dolly Parton ）令人难以置信的生活和遗产。", "summary_en": "The two-hour live special, “CMA Presents I Will Always Love You: A Celebration of Dolly Parton,” airs at 9 p.m. ET on ABC and Disney+, streaming on Hulu the next day from Belmont University’s Fisher Center. Stars like Reba McEntire, Carrie Underwood, Kelsea Ballerini, Brad Paisley, and even U2’s Bono perform classics such as “Jolene” and “I Will Always Love You,” sharing personal stories amid archival footage. Proceeds support Dolly Parton’s Imagination Library, which has delivered millions of books to children, reflecting her lasting legacy of music, kindness, and generosity after her passing on August 25, 2026.", "summary_zh": "乡村音乐协会于美国东部时间晚上9点在美国广播公司和迪士尼+直播“CMA Presents I Will Always Love You: A Celebration of Dolly Parton” ，距离她于8月25日因癌症去世将近两个月。Carrie Underwood、Reba McEntire、Kelsea Ballerini甚至Bono等明星将在纳什维尔的贝尔蒙特大学演出她的经典作品，特别嘉宾包括Oprah Winfrey和Julia Roberts将分享她的故事。 收益支持她的Imagination Library ，为孩子们提供免费书籍，使其成为对她的音乐、从烟雾山脉崛起和慈善事业的衷心致意。", "body_en": "CMA Tribute Special Honors Dolly Parton Tonight on ABC.\n\nCountry music lovers are gathering their tissues for an emotional night celebrating Dolly Parton's incredible life and legacy.\n\nThe Country Music Association airs 'CMA Presents I Will Always Love You: A Celebration of Dolly Parton' live at 9 p.m. ET on ABC and Disney+, nearly two months after her passing on August 25 at age 80 from cancer.\n\nStars like Carrie Underwood, Reba McEntire, Kelsea Ballerini, and even Bono will perform her classics at Belmont University in Nashville, with special guests including Oprah Winfrey and Julia Roberts sharing stories. Proceeds support her Imagination Library, delivering free books to kids, making it a heartfelt nod to her music, rise from the Smoky Mountains, and philanthropy.", "body_zh": "乡村音乐爱好者正在聚集他们的组织，庆祝多莉·帕顿（ Dolly Parton ）令人难以置信的生活和遗产。\n\n乡村音乐协会于美国东部时间晚上9点在美国广播公司和迪士尼+直播“CMA Presents I Will Always Love You: A Celebration of Dolly Parton” ，距离她于8月25日因癌症去世将近两个月。\n\nCarrie Underwood、Reba McEntire、Kelsea Ballerini甚至Bono等明星将在纳什维尔的贝尔蒙特大学演出她的经典作品，特别嘉宾包括Oprah Winfrey和Julia Roberts将分享她的故事。收益支持她的Imagination Library ，为孩子们提供免费书籍，使其成为对她的音乐、从烟雾山脉崛起和慈善事业的衷心致意。", "url": "https://x.com/i/trending/2112946152933089721", "category": "Entertainment", "topics": ["Music", "Country"], "updated_at": "2026-10-21T22:03:45.000Z"}, {"id": "2112078869360726394", "domain": "娱乐", "title_en": "Lingling Kwong Shines at Cartier’s Into The Wild Event in Singapore", "title_zh": "邝玲玲亮相卡地亚新加坡「Into The Wild」活动", "hook_en": "Lingling Kwong turned heads in a shimmering black sequined gown and dramatic floral gloves, posing confidently amid jungle-inspired backdrops at Cartier’s elegant gathering.", "hook_zh": "邝玲玲身着闪亮黑色亮片礼服与戏剧感花卉手套，在丛林风布景前自信亮相。", "summary_en": "On October 19, Thai actress Lingling Kwong brought her sophisticated style to Cartier’s “Into The Wild” event in Singapore, celebrating the brand’s iconic panther motifs and animal-inspired jewelry. She stunned in multiple looks, from a strapless grey dress to a flowing black gown, accessorized with bold silver chains, sparkling bracelets, and statement earrings. Fans raved about her radiant smile and glamour, with one calling her “Elegance has a name.” The immersive experience opens to the public at 17 Rochester Park from October 21 to 25, with elements lingering at ION Orchard through early November.", "summary_zh": "10 月 19 日，泰国演员邝玲玲出席卡地亚新加坡「Into The Wild」活动，呼应品牌黑豹与动物主题珠宝。她多次换装，从抹胸灰裙到飘逸黑礼服，搭配银色链条、手镯与夸张耳环。粉丝称赞其笑容与气质。沉浸式体验 10 月 21–25 日对公众开放于 Rochester Park 17 号，部分展陈延续至 ION Orchard 至 11 月初。", "body_en": "Lingling Kwong Shines at Cartier’s Into The Wild Event in Singapore.\n\nLingling Kwong turned heads in a shimmering black sequined gown and dramatic floral gloves, posing confidently amid jungle-inspired backdrops at Cartier’s elegant gathering.\n\nOn October 19, Thai actress Lingling Kwong brought her sophisticated style to Cartier’s “Into The Wild” event in Singapore, celebrating the brand’s iconic panther motifs and animal-inspired jewelry.\n\nShe stunned in multiple looks, from a strapless grey dress to a flowing black gown, accessorized with bold silver chains, sparkling bracelets, and statement earrings. Fans raved about her radiant smile and glamour, with one calling her “Elegance has a name.” The immersive experience opens to the public at 17 Rochester Park from October 21 to 25, with elements lingering at ION Orchard through early November.", "body_zh": "邝玲玲亮相卡地亚新加坡「Into The Wild」活动。\n\n邝玲玲身着闪亮黑色亮片礼服与戏剧感花卉手套，在丛林风布景前自信亮相。\n\n10 月 19 日，泰国演员邝玲玲出席卡地亚新加坡「Into The Wild」活动，呼应品牌黑豹与动物主题珠宝。她多次换装，从抹胸灰裙到飘逸黑礼服，搭配银色链条、手镯与夸张耳环。\n\n粉丝称赞其笑容与气质。沉浸式体验 10 月 21–25 日对公众开放于 Rochester Park 17 号，部分展陈延续至 ION Orchard 至 11 月初。", "url": "https://x.com/i/trending/2112078869360726394", "category": "Entertainment", "topics": ["Celebrity"], "updated_at": "2026-10-21T06:02:16.000Z"}, {"id": "2112506238923608157", "domain": "娱乐", "title_en": "Fans Adore Pooh Krittin and Pavel Naret's Grim Reaper Promo Photos", "title_zh": "粉丝热捧 Pooh 与 Pavel《死神恋人》宣传照", "hook_en": "Pooh Krittin channels a brooding grim reaper with flowing dark hair and moody blue lighting, while Pavel Naret contrasts in a crisp white shirt—their chemistry already leaping off the screen.", "hook_zh": "Pooh Krittin 黑发阴郁死神造型配冷蓝光，Pavel Naret 白衬衫对比鲜明——化学反应已溢出屏幕。", "summary_en": "The promotional images for the upcoming fantasy romance series 'The Grim Lover' showcase Pooh as the grim reaper Sibsi (aka Fourteen or Rafah) and Pavel as grieving anesthesiologist Vivorn Assarak (Won), adapted from a web novel blending boys' love, fantasy, romance, and drama. Fans rave about the 'lethal visuals' and 'insane' pairing chemistry, with one calling Pooh 'the handsomest Reaper' ever. Produced by Change2561, the series airs on One 31 and streams globally on Netflix, with a fan event 'ROAD TO THE GRIM LOVER' set for November 18, 2026, at ICONSIAM Hall in Bangkok—tickets on sale October 30.", "summary_zh": "奇幻爱情剧《The Grim Lover》宣传照中，Pooh 饰死神 Sibsi（Fourteen/Rafah），Pavel 饰哀悼中的麻醉医生 Vivorn Assarak（Won），改编融合 BL、奇幻、爱情与戏剧的网络小说。粉丝狂赞「致命视觉」与「疯狂」配对，有人称 Pooh「史上最帅死神」。Change2561 制作，One 31 播出、Netflix 全球上线；粉丝活动 ROAD TO THE GRIM LOVER 定于 2026 年 11 月 18 日曼谷 ICONSIAM Hall，门票 10 月 30 日开售。", "body_en": "Fans Adore Pooh Krittin and Pavel Naret's Grim Reaper Promo Photos.\n\nPooh Krittin channels a brooding grim reaper with flowing dark hair and moody blue lighting, while Pavel Naret contrasts in a crisp white shirt—their chemistry already leaping off the screen.\n\nThe promotional images for the upcoming fantasy romance series 'The Grim Lover' showcase Pooh as the grim reaper Sibsi (aka Fourteen or Rafah) and Pavel as grieving anesthesiologist Vivorn Assarak (Won), adapted from a web novel blending boys' love, fantasy, romance, and drama.\n\nFans rave about the 'lethal visuals' and 'insane' pairing chemistry, with one calling Pooh 'the handsomest Reaper' ever. Produced by Change2561, the series airs on One 31 and streams globally on Netflix, with a fan event 'ROAD TO THE GRIM LOVER' set for November 18, 2026, at ICONSIAM Hall in Bangkok—tickets on sale October 30.", "body_zh": "粉丝热捧 Pooh 与 Pavel《死神恋人》宣传照。\n\nPooh Krittin 黑发阴郁死神造型配冷蓝光，Pavel Naret 白衬衫对比鲜明——化学反应已溢出屏幕。\n\n奇幻爱情剧《The Grim Lover》宣传照中，Pooh 饰死神 Sibsi（Fourteen/Rafah），Pavel 饰哀悼中的麻醉医生 Vivorn Assarak（Won），改编融合 BL、奇幻、爱情与戏剧的网络小说。\n\n粉丝狂赞「致命视觉」与「疯狂」配对，有人称 Pooh「史上最帅死神」。Change2561 制作，One 31 播出、Netflix 全球上线；粉丝活动 ROAD TO THE GRIM LOVER 定于 2026 年 11 月 18 日曼谷 ICONSIAM Hall，门票 10 月 30 日开售。", "url": "https://x.com/i/trending/2112506238923608157", "category": "Entertainment", "topics": ["Celebrity"], "updated_at": "2026-10-20T11:32:52.000Z"}, {"id": "2112450617138659781", "domain": "娱乐", "title_en": "Wang Yibo Shares North China Leopard Expedition at Beijing Premiere", "title_zh": "王一博北京首映分享华北豹科考见闻", "hook_en": "Wang Yibo beamed with pride at the Beijing premiere when he learned his infrared camera had captured a rare North China leopard in the wild.", "hook_zh": "王一博在北京首映礼得知自己的红外相机拍到罕见华北豹，难掩自豪。", "summary_en": "The Chinese actor and WildAid ambassador attended the media premiere for 'Defenders of the Hidden 2: Land of Leopards' on October 20 in Beijing, recounting his 10-to-15-day high-altitude shoot in Qinghai where he wielded a professional Canon camera for the first time and set up wildlife cams. The series spotlights the North China leopard's habitat struggles and human-wildlife harmony efforts, with the first episode streaming on Tencent Video October 24 and the second on October 31. Yibo urged fans to reject products from endangered species, holding a framed leopard photo amid warm event cheers.", "summary_zh": "这位中国演员兼野生救援大使于 10 月 20 日出席纪录片《隐秘的守卫者 2：豹之境》媒体首映，讲述在青海海拔地区拍摄 10–15 天的经历：首次使用专业佳能相机并布设野生动物相机。系列聚焦华北豹栖息地困境与人兽和谐，第一集 10 月 24 日、第二集 10 月 31 日登陆腾讯视频。一博手持装裱豹影呼吁抵制濒危物种制品，现场反响热烈。", "body_en": "Wang Yibo Shares North China Leopard Expedition at Beijing Premiere.\n\nWang Yibo beamed with pride at the Beijing premiere when he learned his infrared camera had captured a rare North China leopard in the wild.\n\nThe Chinese actor and WildAid ambassador attended the media premiere for 'Defenders of the Hidden 2: Land of Leopards' on October 20 in Beijing, recounting his 10-to-15-day high-altitude shoot in Qinghai where he wielded a professional Canon camera for the first time and set up wildlife cams.\n\nThe series spotlights the North China leopard's habitat struggles and human-wildlife harmony efforts, with the first episode streaming on Tencent Video October 24 and the second on October 31. Yibo urged fans to reject products from endangered species, holding a framed leopard photo amid warm event cheers.", "body_zh": "王一博北京首映分享华北豹科考见闻。\n\n王一博在北京首映礼得知自己的红外相机拍到罕见华北豹，难掩自豪。\n\n这位中国演员兼野生救援大使于 10 月 20 日出席纪录片《隐秘的守卫者 2：豹之境》媒体首映，讲述在青海海拔地区拍摄 10–15 天的经历：首次使用专业佳能相机并布设野生动物相机。\n\n系列聚焦华北豹栖息地困境与人兽和谐，第一集 10 月 24 日、第二集 10 月 31 日登陆腾讯视频。一博手持装裱豹影呼吁抵制濒危物种制品，现场反响热烈。", "url": "https://x.com/i/trending/2112450617138659781", "category": "Entertainment", "topics": ["Celebrity"], "updated_at": "2026-10-20T17:18:13.000Z"}, {"id": "2112630069361570032", "domain": "娱乐", "title_en": "Golden Globes Place Michael Jackson Biopic in Drama Categories", "title_zh": "金球奖将迈克尔·杰克逊的传记片列入戏剧类", "hook_en": "Jaafar Jackson steps into his uncle's shoes in the Michael Jackson biopic, but the Golden Globes just shifted its awards path to a tougher drama field.", "hook_zh": "贾法尔·杰克逊（ Jaafar Jackson ）在迈克尔·杰克逊（ Michael Jackson ）的传记片中扮演叔叔的角色，但金球奖刚刚将其颁奖之路转向了更艰难的戏剧领域。", "summary_en": "Lionsgate hoped to enter 'Michael' in the comedy or musical categories for the 2027 Golden Globes, but organizers ruled it fits drama instead, pitting Jaafar Jackson against stars from Christopher Nolan’s 'The Odyssey' and 'La Bola Negra.' The decision follows tightened rules for music biopics like 'Elvis' and 'Bohemian Rhapsody,' which no longer qualify as musicals unless songs drive the plot. Fans debate the call, with Taj Jackson questioning the logic, while Jaafar's praised performance keeps eyes on his drama actor chances; Lionsgate may appeal by October 31 but likely won't.", "summary_zh": "Lionsgate希望在2027年金球奖的喜剧或音乐类别中加入“Michael” ，但组织者裁定它适合戏剧，让Jaafar Jackson与Christopher Nolan的“The Odyssey”和“La Bola Negra”中的明星对抗。这一决定遵循了“猫王”和“波西米亚狂想曲”等音乐传记片的严格规则，除非歌曲驱动情节，否则这些传记片不再符合音乐剧的资格。 球迷们对这一呼吁进行了辩论，泰姬·杰克逊（ Taj Jackson ）对这一逻辑提出质疑，而贾法尔（ Jaafar ）备受赞誉的表现则密切关注他的戏剧演员机会；狮门（ Lionsgate ）可能会在10月31日之前提出上诉，", "body_en": "Golden Globes Place Michael Jackson Biopic in Drama Categories.\n\nJaafar Jackson steps into his uncle's shoes in the Michael Jackson biopic, but the Golden Globes just shifted its awards path to a tougher drama field.\n\nLionsgate hoped to enter 'Michael' in the comedy or musical categories for the 2027 Golden Globes, but organizers ruled it fits drama instead, pitting Jaafar Jackson against stars from Christopher Nolan’s 'The Odyssey' and 'La Bola Negra.' The decision follows tightened rules for music biopics like 'Elvis' and 'Bohemian Rhapsody,' which no longer qualify as musicals unless songs drive the plot.\n\nFans debate the call, with Taj Jackson questioning the logic, while Jaafar's praised performance keeps eyes on his drama actor chances; Lionsgate may appeal by October 31 but likely won't.", "body_zh": "贾法尔·杰克逊（ Jaafar Jackson ）在迈克尔·杰克逊（ Michael Jackson ）的传记片中扮演叔叔的角色，但金球奖刚刚将其颁奖之路转向了更艰难的戏剧领域。\n\nLionsgate希望在2027年金球奖的喜剧或音乐类别中加入“Michael” ，但组织者裁定它适合戏剧，让Jaafar Jackson与Christopher Nolan的“The Odyssey”和“La Bola Negra”中的明星对抗。\n\n这一决定遵循了“猫王”和“波西米亚狂想曲”等音乐传记片的严格规则，除非歌曲驱动情节，否则这些传记片不再符合音乐剧的资格。球迷们对这一呼吁进行了辩论，泰姬·杰克逊（ Taj Jackson ）对这一逻辑提出质疑，而贾法尔（ Jaafar ）备受赞誉的表现则密切关注他的戏剧演员机会；狮门（ Lionsgate ）可能会在10月31日之前提出上诉，", "url": "https://x.com/i/trending/2112630069361570032", "category": "Entertainment", "topics": ["Movies & TV"], "updated_at": "2026-10-21T17:48:00.000Z"}, {"id": "2112840787054743961", "domain": "娱乐", "title_en": "Moonlight Marks 10 Years Since Theatrical Premiere", "title_zh": "Moonlight标志着美国首次亮相和奥斯卡辉煌10周年", "hook_en": "Ten years ago today, Barry Jenkins' quiet masterpiece Moonlight arrived in theaters, capturing a young Black man's journey through identity and belonging in Miami.", "hook_zh": "十年前的今天，巴里·詹金斯（ Barry Jenkins ）的《月光》（ Moonlight ）悄然抵达美国影院，通过它对迈阿密一个年轻人生活的温柔注视，永远改变了有关身份和爱的对话。", "summary_en": "The film follows Chiron from childhood as 'Little,' through teenage bullying, to adulthood as 'Black,' with standout performances by Mahershala Ali as a kind drug dealer and Naomie Harris as his struggling mother. It won three Oscars, including Best Picture—the first for a film with an all-Black cast and gay protagonist—and its poetic cinematography and score turn everyday moments profound. Now streaming on Netflix, with a new 4K remaster in theaters and Jenkins reflecting on its making, fans continue to praise its honest portrayal of beauty, pain, and human gray areas.", "summary_zh": "这部电影于2016年10月21日由A24发行，讲述了凯龙星从童年到成年的三个章节，获得了三项奥斯卡奖，其中包括第一部全黑演员和LGBT主题的最佳影片。 Mahershala Ali、Naomie Harris、Trevante Rhodes、Ashton Sanders和Jharrel Jerome的杰出表演，加上明亮的电影摄影和Nicholas Britell的配乐，使其150万美元的预算在全球范围内获得了6700万美元的持久赞誉。本周， Netflix将其添加到其美国图书馆，同时4K重制版重返影院，因为粉丝们分享了其脆弱性和自我接受主题的个人故事。", "body_en": "Ten years ago today, Barry Jenkins' Moonlight quietly arrived in U.S. theaters, forever changing conversations about identity and love through its tender gaze on a young man's life in Miami.\n\nReleased on October 21, 2016, by A24, the film follows Chiron from childhood to adulthood across three chapters, earning three Oscars including Best Picture as the first with an all-Black cast and LGBT theme. Standout performances by Mahershala Ali, Naomie Harris, Trevante Rhodes, Ashton Sanders, and Jharrel Jerome, paired with luminous cinematography and Nicholas Britell's score, turned its $1.5 million budget into $67 million worldwide and lasting praise.\n\nThis week, Netflix added it to its U.S. library while a 4K remaster returned to theaters, as fans share personal stories of its themes of vulnerability and self-acceptance.", "body_zh": "十年前的今天，巴里·詹金斯（ Barry Jenkins ）的《月光》（ Moonlight ）悄然抵达美国影院，通过它对迈阿密一个年轻人生活的温柔注视，永远改变了有关身份和爱的对话。\n\n这部电影于2016年10月21日由A24发行，讲述了凯龙星从童年到成年的三个章节，获得了三项奥斯卡奖，其中包括第一部全黑演员和LGBT主题的最佳影片。\n\nMahershala Ali、Naomie Harris、Trevante Rhodes、Ashton Sanders和Jharrel Jerome的杰出表演，加上明亮的电影摄影和Nicholas Britell的配乐，使其150万美元的预算在全球范围内获得了6700万美元的持久赞誉。本周， Netflix将其添加到其美国图书馆，同时4K重制版重返影院，因为粉丝们分享了其脆弱性和自我接受主题的个人故事。", "url": "https://x.com/i/trending/2112840787054743961", "category": "Entertainment", "topics": ["Movies & TV"], "updated_at": "2026-10-21T20:52:22.000Z"}, {"id": "2112352804241285515", "domain": "娱乐", "title_en": "Dwayne Johnson Transforms into Elderly Chicken Man for Lizard Music", "title_zh": "德维恩·约翰逊（ Dwayne Johnson ）变身为蜥蜴音乐的老鸡人", "hook_en": "Dwayne Johnson strolls New York streets with gray hair, a bushy beard, and a bucket hat, pizza in hand beside a child actor and giant lizard puppet. At 54, he's unrecognizable as the eccentric 70-year-old Chicken Man.", "hook_zh": "德维恩·约翰逊（ Dwayne Johnson ）在纽约街头漫步，头发灰白，蓄着浓密的胡须，戴着渔夫帽，手里拿着披萨，旁边是儿童演员和巨型蜥蜴木偶。54岁时，他无法辨认出这位古怪的70岁鸡人。", "summary_en": "Johnson stars in Lizard Music, Benny Safdie's adaptation of Daniel Pinkwater’s 1976 children’s book, playing a septuagenarian who joins a boy on a whimsical adventure after discovering lizards on late-night TV. Set photos capture him in full prosthetics with young co-star Theo Clark Leber, amid a stacked cast including Rachel McAdams, Jeff Goldblum, and Colman Domingo. The Amazon MGM Studios film wraps principal photography for a Christmas 2027 release, following Johnson's physical overhaul and prior work with Safdie on The Smashing Machine.", "summary_zh": "约翰逊主演了蜥蜴音乐，本尼·萨夫迪改编了丹尼尔·平克沃特（ Daniel Pinkwater ） 1976年的儿童书籍，扮演一名七十岁的老人，在深夜电视上发现蜥蜴后，他和一个男孩一起进行了一次异想天开的冒险。在雷切尔·麦克亚当斯（ Rachel McAdams ）、杰夫·戈德布鲁姆（ Jeff Goldblum ）和科尔曼·多明戈（ Colman Domingo ）等演员阵容中，与年轻的联合主演西奥·克拉克·莱伯（ Theo Clark Leber ）一起拍摄全假肢照片 Amazon MGM Studios电影在约翰逊的物理检修和之前与Safdie在The Smashing Machine上的合作之后，包装了2027年圣诞节的主要摄影作品。", "body_en": "Dwayne Johnson Transforms into Elderly Chicken Man for Lizard Music.\n\nDwayne Johnson strolls New York streets with gray hair, a bushy beard, and a bucket hat, pizza in hand beside a child actor and giant lizard puppet. At 54, he's unrecognizable as the eccentric 70-year-old Chicken Man.\n\nJohnson stars in Lizard Music, Benny Safdie's adaptation of Daniel Pinkwater’s 1976 children’s book, playing a septuagenarian who joins a boy on a whimsical adventure after discovering lizards on late-night TV.\n\nSet photos capture him in full prosthetics with young co-star Theo Clark Leber, amid a stacked cast including Rachel McAdams, Jeff Goldblum, and Colman Domingo. The Amazon MGM Studios film wraps principal photography for a Christmas 2027 release, following Johnson's physical overhaul and prior work with Safdie on The Smashing Machine.", "body_zh": "德维恩·约翰逊（ Dwayne Johnson ）在纽约街头漫步，头发灰白，蓄着浓密的胡须，戴着渔夫帽，手里拿着披萨，旁边是儿童演员和巨型蜥蜴木偶。54岁时，他无法辨认出这位古怪的70岁鸡人。\n\n约翰逊主演了蜥蜴音乐，本尼·萨夫迪改编了丹尼尔·平克沃特（ Daniel Pinkwater ） 1976年的儿童书籍，扮演一名七十岁的老人，在深夜电视上发现蜥蜴后，他和一个男孩一起进行了一次异想天开的冒险。在雷切尔·麦克亚当斯（ Rachel McAdams ）、杰夫·戈德布鲁姆（ Jeff Goldblum ）和科尔曼·多明戈（ Colman Domingo ）等演员阵容中，与年轻的联合主演西奥·克拉克·莱伯（ Theo Clark Leber ）一起拍摄全假肢照片 Amazon MGM Studios电影在约翰逊的物理检修和之前与Safdie在The Smashing Machine上的合作之后，包装了2027年圣诞节的主要摄影作品。", "url": "https://x.com/i/trending/2112352804241285515", "category": "Entertainment", "topics": ["Movies & TV"], "updated_at": "2026-10-21T17:07:08.000Z"}, {"id": "2112623560363536767", "domain": "娱乐", "title_en": "LE SSERAFIM and PLAVE Fans Unite for 2026 MAMA Awards Voting", "title_zh": "LE SSERAFIM 与 PLAVE 粉丝携手冲刺 2026 MAMA 投票", "hook_en": "Fans of LE SSERAFIM and PLAVE are joining forces, backing each other in the Fans’ Choice categories with daily votes and colorful fan art flooding timelines.", "hook_zh": "两团粉丝跨圈互投 Fans’ Choice，每日打卡与应援图刷屏时间线。", "summary_en": "Supporters are teaming up for the first round of 2026 MAMA Awards Fans’ Choice voting, asking fans to vote for LE SSERAFIM in the female category and PLAVE in the male category through the Mnet Plus app and X posts until October 22 at 11:59 p.m. KST. Announced by fan accounts like @FIMBASE, the cross-fandom effort includes sharing voting proofs under #피어나랑_플리랑, with PLAVE fans creating anime-inspired illustrations of the virtual boy group in racing suits and stage outfits. LE SSERAFIM fans match the energy ahead of their Chapter 2 performance at the November 20-21 ceremony in Osaka, Japan, as the top 20 acts per gender advance from this round.", "summary_zh": "2026 MAMA Awards 第一轮 Fans’ Choice 投票中，粉丝号召女团投 LE SSERAFIM、男团投 PLAVE，经 Mnet Plus 与 X 发帖，截止韩国时间 10 月 22 日 23:59。@FIMBASE 等账号发起跨粉圈协作，话题 #피어나랑_플리랑 晒投票凭证；PLAVE 粉丝绘制赛车服与舞台风插画。LE SSERAFIM 粉丝同样加码，为 11 月 20–21 日大阪 Chapter 2 舞台蓄势；本轮各性别前 20 晋级。", "body_en": "LE SSERAFIM and PLAVE Fans Unite for 2026 MAMA Awards Voting.\n\nFans of LE SSERAFIM and PLAVE are joining forces, backing each other in the Fans’ Choice categories with daily votes and colorful fan art flooding timelines.\n\nSupporters are teaming up for the first round of 2026 MAMA Awards Fans’ Choice voting, asking fans to vote for LE SSERAFIM in the female category and PLAVE in the male category through the Mnet Plus app and X posts until October 22 at 11:59 p.m. KST.\n\nAnnounced by fan accounts like @FIMBASE, the cross-fandom effort includes sharing voting proofs under #피어나랑_플리랑, with PLAVE fans creating anime-inspired illustrations of the virtual boy group in racing suits and stage outfits. LE SSERAFIM fans match the energy ahead of their Chapter 2 performance at the November 20-21 ceremony in Osaka, Japan, as the top 20 acts per gender advance from this round.", "body_zh": "LE SSERAFIM 与 PLAVE 粉丝携手冲刺 2026 MAMA 投票。\n\n两团粉丝跨圈互投 Fans’ Choice，每日打卡与应援图刷屏时间线。\n\n2026 MAMA Awards 第一轮 Fans’ Choice 投票中，粉丝号召女团投 LE SSERAFIM、男团投 PLAVE，经 Mnet Plus 与 X 发帖，截止韩国时间 10 月 22 日 23:59。\n\n@FIMBASE 等账号发起跨粉圈协作，话题 #피어나랑_플리랑 晒投票凭证；PLAVE 粉丝绘制赛车服与舞台风插画。LE SSERAFIM 粉丝同样加码，为 11 月 20–21 日大阪 Chapter 2 舞台蓄势；本轮各性别前 20 晋级。", "url": "https://x.com/i/trending/2112623560363536767", "category": "Entertainment", "topics": ["K-pop"], "updated_at": "2026-10-20T19:24:45.000Z"}, {"id": "2112111882152910915", "domain": "娱乐", "title_en": "100 Days of Deception Captivates with Spy Romance in 1930s Korea", "title_zh": "《百日的谎言》：1930 年代京城谍战甜宠升温", "hook_en": "In 1930s colonial Korea, a clever pickpocket goes undercover as a spy, sparking suspicion and romance with an elite interpreter amid high-stakes missions.", "hook_zh": "殖民时期朝鲜，顶尖扒手卧底成间谍，与精英通译在高风险任务中生出猜忌与爱意。", "summary_en": "tvN's '100 Days of Deception,' which premiered October 10, follows Lee Ga-kyung (Kim Yoo-jung), Gyeongseong’s top pickpocket on a 100-day undercover mission for the independence group, crossing paths with Kim Tae-woong (Park Jin-young), an adopted son of a high-ranking official. The series blends tense espionage, shifting loyalties, and budding romance, drawing praise for the leads' chemistry and climbing ratings from 5.3% at launch to around 9% by episode 4. Fans love behind-the-scenes clips of the stars laughing on set, while strong buzz rankings and Netflix availability worldwide fuel its momentum through late November.", "summary_zh": "tvN《百日的谎言》10 月 10 日开播，金裕贞饰李佳京——京城第一扒手，为独立组织执行百日卧底；朴珍荣饰金泰雄，高官养子。剧集融合谍战张力、立场摇摆与暗生情愫，主演化学反应获赞，收视从首播约 5.3% 升至第 4 集约 9%。片场笑声花絮热传，热搜与 Netflix 全球上线推动势头延续至 11 月末。", "body_en": "100 Days of Deception Captivates with Spy Romance in 1930s Korea.\n\nIn 1930s colonial Korea, a clever pickpocket goes undercover as a spy, sparking suspicion and romance with an elite interpreter amid high-stakes missions.\n\ntvN's '100 Days of Deception,' which premiered October 10, follows Lee Ga-kyung (Kim Yoo-jung), Gyeongseong’s top pickpocket on a 100-day undercover mission for the independence group, crossing paths with Kim Tae-woong (Park Jin-young), an adopted son of a high-ranking official.\n\nThe series blends tense espionage, shifting loyalties, and budding romance, drawing praise for the leads' chemistry and climbing ratings from 5.3% at launch to around 9% by episode 4. Fans love behind-the-scenes clips of the stars laughing on set, while strong buzz rankings and Netflix availability worldwide fuel its momentum through late November.", "body_zh": "《百日的谎言》：1930 年代京城谍战甜宠升温。\n\n殖民时期朝鲜，顶尖扒手卧底成间谍，与精英通译在高风险任务中生出猜忌与爱意。\n\ntvN《百日的谎言》10 月 10 日开播，金裕贞饰李佳京——京城第一扒手，为独立组织执行百日卧底；朴珍荣饰金泰雄，高官养子。\n\n剧集融合谍战张力、立场摇摆与暗生情愫，主演化学反应获赞，收视从首播约 5.3% 升至第 4 集约 9%。片场笑声花絮热传，热搜与 Netflix 全球上线推动势头延续至 11 月末。", "url": "https://x.com/i/trending/2112111882152910915", "category": "Entertainment", "topics": ["Movies & TV"], "updated_at": "2026-10-20T08:04:03.000Z"}, {"id": "2112426906595524740", "domain": "娱乐", "title_en": "JoongDunk Fan Meeting Sells Out in Hong Kong Amid Duo Split", "title_zh": "JoongDunk 香港粉丝见面会售罄，恰逢荧幕拆伙", "hook_en": "Fans grabbed every ticket for JoongDunk's December 5 Hong Kong fan meeting, turning it into a sell-out just days after their agency announced the end of their on-screen pairing.", "hook_zh": "经纪公司刚宣布荧幕搭档结束，12 月 5 日香港见面会门票却被抢光。", "summary_en": "Thai actors Joong Archen Aydin and Dunk Natachai Boonprasert, beloved as JoongDunk, will appear together one last time with their character Jaidee at Nina Hotel Tsuen Wan West. GMMTV announced on October 19 that the pair mutually agreed to pursue separate careers, but this event and prior schedules remain on track. Supporters from multiple countries snapped up tickets and add-ons, sharing emotional tributes like sketches and messages of endless love, while warning against unofficial sellers. The rapid sell-out underscores their lasting bond with fans, who mix joy over the gathering with hopes for cherished memories.", "summary_zh": "泰国演员 Joong Archen Aydin 与 Dunk Natachai Boonprasert（合称 JoongDunk）将携角色 Jaidee 在荃湾西 Nina Hotel 最后同台。GMMTV 10 月 19 日称双方合意分头发展，但本场与既定行程照常。多国粉丝秒抢门票与周边，分享手绘与「永远爱」留言，并提醒防黄牛。秒空凸显粉丝羁绊：既为聚会兴奋，也珍惜共同回忆。", "body_en": "JoongDunk Fan Meeting Sells Out in Hong Kong Amid Duo Split.\n\nFans grabbed every ticket for JoongDunk's December 5 Hong Kong fan meeting, turning it into a sell-out just days after their agency announced the end of their on-screen pairing.\n\nThai actors Joong Archen Aydin and Dunk Natachai Boonprasert, beloved as JoongDunk, will appear together one last time with their character Jaidee at Nina Hotel Tsuen Wan West. GMMTV announced on October 19 that the pair mutually agreed to pursue separate careers, but this event and prior schedules remain on track.\n\nSupporters from multiple countries snapped up tickets and add-ons, sharing emotional tributes like sketches and messages of endless love, while warning against unofficial sellers. The rapid sell-out underscores their lasting bond with fans, who mix joy over the gathering with hopes for cherished memories.", "body_zh": "JoongDunk 香港粉丝见面会售罄，恰逢荧幕拆伙。\n\n经纪公司刚宣布荧幕搭档结束，12 月 5 日香港见面会门票却被抢光。\n\n泰国演员 Joong Archen Aydin 与 Dunk Natachai Boonprasert（合称 JoongDunk）将携角色 Jaidee 在荃湾西 Nina Hotel 最后同台。GMMTV 10 月 19 日称双方合意分头发展，但本场与既定行程照常。\n\n多国粉丝秒抢门票与周边，分享手绘与「永远爱」留言，并提醒防黄牛。秒空凸显粉丝羁绊：既为聚会兴奋，也珍惜共同回忆。", "url": "https://x.com/i/trending/2112426906595524740", "category": "Entertainment", "topics": ["Concerts"], "updated_at": "2026-10-21T11:16:28.000Z"}, {"id": "2112807301782638724", "domain": "娱乐", "title_en": "Kim Hyeyoon Named Taiwan Tourism Ambassador for 2026-2027", "title_zh": "金惠奫出任 2026–2027 台湾观光宣传大使", "hook_en": "Kim Hyeyoon stepped out in a crisp white pantsuit, flashing smiles and holding her official certificate as fans snapped photos at the Seoul launch.", "hook_zh": "金惠奫身着白裤装亮相首尔发布会，手持聘书笑容满面，粉丝围拍。", "summary_en": "South Korean actress Kim Hyeyoon was appointed promotional ambassador for Taiwan Tourism at a Seoul press conference, where new campaign videos debuted under the slogan 'Everyone, Anytime, Taiwan Delights.' The clips show her enjoying Tainan food streets with her brother, Sun Moon Lake with family, solo time in Kaohsiung, and beach fun with friends, highlighting Taiwan's charms for any traveler or season. Organizers picked her for her bright image and wide appeal, boosted by her popularity from *Lovely Runner* and a 2024 Taiwan fan meeting. She hopes the videos inspire people to plan trips that fit their style.", "summary_zh": "韩国女演员金惠奫在首尔记者会获聘台湾观光宣传大使，新片以「Everyone, Anytime, Taiwan Delights」为口号：与兄逛台南小吃、与家人游日月潭、高雄独行、海边友人行，展示四季与多元玩法。主办方看中其明朗形象与《浪漫速成班》人气及 2024 台湾粉丝见面会号召力。她希望影片启发观众规划适合自己的行程。", "body_en": "Kim Hyeyoon Named Taiwan Tourism Ambassador for 2026-2027.\n\nKim Hyeyoon stepped out in a crisp white pantsuit, flashing smiles and holding her official certificate as fans snapped photos at the Seoul launch.\n\nSouth Korean actress Kim Hyeyoon was appointed promotional ambassador for Taiwan Tourism at a Seoul press conference, where new campaign videos debuted under the slogan 'Everyone, Anytime, Taiwan Delights.' The clips show her enjoying Tainan food streets with her brother, Sun Moon Lake with family, solo time in Kaohsiung, and beach fun with friends, highlighting Taiwan's charms for any traveler or season.\n\nOrganizers picked her for her bright image and wide appeal, boosted by her popularity from *Lovely Runner* and a 2024 Taiwan fan meeting. She hopes the videos inspire people to plan trips that fit their style.", "body_zh": "金惠奫出任 2026–2027 台湾观光宣传大使。\n\n金惠奫身着白裤装亮相首尔发布会，手持聘书笑容满面，粉丝围拍。\n\n韩国女演员金惠奫在首尔记者会获聘台湾观光宣传大使，新片以「Everyone, Anytime, Taiwan Delights」为口号：与兄逛台南小吃、与家人游日月潭、高雄独行、海边友人行，展示四季与多元玩法。\n\n主办方看中其明朗形象与《浪漫速成班》人气及 2024 台湾粉丝见面会号召力。她希望影片启发观众规划适合自己的行程。", "url": "https://x.com/i/trending/2112807301782638724", "category": "Entertainment", "topics": ["Travel"], "updated_at": "2026-10-21T12:40:57.000Z"}, {"id": "2113014995948831070", "domain": "娱乐", "title_en": "Tom Cruise to Receive AFI Life Achievement Award", "title_zh": "汤姆·克鲁斯将获美国电影学院终身成就奖", "hook_en": "Tom Cruise, the star who's thrilled audiences for decades, will be honored with the American Film Institute's top career award at a star-studded gala.", "hook_zh": "数十年来让观众肾上腺素飙升的汤姆·克鲁斯，将在星光晚宴上接受 AFI 最高生涯荣誉。", "summary_en": "The AFI announced on October 21, 2026, that Cruise will receive its 52nd Life Achievement Award on April 24, 2027, at the Dolby Theatre in Los Angeles. AFI Board chair Kathleen Kennedy called him a global icon whose passion for movies brings people together and serves as an ambassador for American film. At 64, Cruise has starred in films grossing nearly $13 billion worldwide, from Risky Business to Mission: Impossible and Top Gun: Maverick, earning three Oscar acting nods and an honorary Oscar in 2025. The award follows Eddie Murphy as last year's honoree and supports AFI's education and preservation work.", "summary_zh": "AFI 10 月 21 日宣布，克鲁斯将于 2027 年 4 月 24 日在洛杉矶杜比剧院领取第 52 届终身成就奖。董事会主席凯瑟琳·肯尼迪称其为全球偶像，对电影的热情凝聚观众，并担任美国电影大使。64 岁的他作品全球票房近 130 亿美元，从《危险生意》到《碟中谍》《壮志凌云：独行侠》，三获奥斯卡演技提名并于 2025 年获荣誉奖。该奖上届得主为艾迪·墨菲，亦支持 AFI 教育与保存工作。", "body_en": "Tom Cruise to Receive AFI Life Achievement Award.\n\nTom Cruise, the star who's thrilled audiences for decades, will be honored with the American Film Institute's top career award at a star-studded gala.\n\nThe AFI announced on October 21, 2026, that Cruise will receive its 52nd Life Achievement Award on April 24, 2027, at the Dolby Theatre in Los Angeles. AFI Board chair Kathleen Kennedy called him a global icon whose passion for movies brings people together and serves as an ambassador for American film.\n\nAt 64, Cruise has starred in films grossing nearly $13 billion worldwide, from Risky Business to Mission: Impossible and Top Gun: Maverick, earning three Oscar acting nods and an honorary Oscar in 2025. The award follows Eddie Murphy as last year's honoree and supports AFI's education and preservation work.", "body_zh": "汤姆·克鲁斯将获美国电影学院终身成就奖。\n\n数十年来让观众肾上腺素飙升的汤姆·克鲁斯，将在星光晚宴上接受 AFI 最高生涯荣誉。\n\nAFI 10 月 21 日宣布，克鲁斯将于 2027 年 4 月 24 日在洛杉矶杜比剧院领取第 52 届终身成就奖。董事会主席凯瑟琳·肯尼迪称其为全球偶像，对电影的热情凝聚观众，并担任美国电影大使。\n\n64 岁的他作品全球票房近 130 亿美元，从《危险生意》到《碟中谍》《壮志凌云：独行侠》，三获奥斯卡演技提名并于 2025 年获荣誉奖。该奖上届得主为艾迪·墨菲，亦支持 AFI 教育与保存工作。", "url": "https://x.com/i/trending/2113014995948831070", "category": "Entertainment", "topics": ["Movies & TV"], "updated_at": "2026-10-21T21:18:16.000Z"}, {"id": "2112801173090587112", "domain": "娱乐", "title_en": "Thai Actress Lingling Kwong Shines at Cartier’s Into the Wild Event in Singapore", "title_zh": "泰星玲玲·邝亮相新加坡 Cartier「Into the Wild」", "hook_en": "Lingling Kwong stepped into a lush garden paradise in Singapore, her shimmering black sequined gown and dramatic gloves catching every light amid animal-inspired jewelry.", "hook_zh": "玲玲·邝走进新加坡如丛林般的花园会场，黑色亮片礼裙与戏剧性手套在灯光下闪烁，动物主题珠宝吸睛。", "summary_en": "Thai actress Lingling Kwong attended Cartier’s “Into the Wild” celebration at Rochester Park as a special guest, wearing striking ensembles from the Faune & Flore collection that blended sequins, floral details, and signature motifs. The event transformed heritage houses and gardens into immersive spaces with illuminated designs, artisan demos, dance performances, and sensory highlights of Cartier’s jewelry, watches, fragrances, and leather goods. Fans and media praised her elegant presence, with the experience open to the public through October 25 at 17 Rochester Park via advance registration.", "summary_zh": "泰国女演员玲玲·邝以特邀嘉宾身份出席罗彻斯特公园 Cartier「Into the Wild」，身着 Faune & Flore 系列亮片、花卉细节与标志性图案造型。活动将遗产宅邸与花园变为沉浸空间，含光影装置、匠人演示、舞蹈，并呈现珠宝、腕表、香氛与皮具。粉丝与媒体称赞其优雅风范；公众可通过预约于 10 月 25 日前在 17 Rochester Park 体验。", "body_en": "Thai Actress Lingling Kwong Shines at Cartier’s Into the Wild Event in Singapore.\n\nLingling Kwong stepped into a lush garden paradise in Singapore, her shimmering black sequined gown and dramatic gloves catching every light amid animal-inspired jewelry.\n\nThai actress Lingling Kwong attended Cartier’s “Into the Wild” celebration at Rochester Park as a special guest, wearing striking ensembles from the Faune & Flore collection that blended sequins, floral details, and signature motifs.\n\nThe event transformed heritage houses and gardens into immersive spaces with illuminated designs, artisan demos, dance performances, and sensory highlights of Cartier’s jewelry, watches, fragrances, and leather goods. Fans and media praised her elegant presence, with the experience open to the public through October 25 at 17 Rochester Park via advance registration.", "body_zh": "泰星玲玲·邝亮相新加坡 Cartier「Into the Wild」。\n\n玲玲·邝走进新加坡如丛林般的花园会场，黑色亮片礼裙与戏剧性手套在灯光下闪烁，动物主题珠宝吸睛。\n\n泰国女演员玲玲·邝以特邀嘉宾身份出席罗彻斯特公园 Cartier「Into the Wild」，身着 Faune & Flore 系列亮片、花卉细节与标志性图案造型。\n\n活动将遗产宅邸与花园变为沉浸空间，含光影装置、匠人演示、舞蹈，并呈现珠宝、腕表、香氛与皮具。粉丝与媒体称赞其优雅风范；公众可通过预约于 10 月 25 日前在 17 Rochester Park 体验。", "url": "https://x.com/i/trending/2112801173090587112", "category": "Entertainment", "topics": ["Celebrity"], "updated_at": "2026-10-21T17:57:44.000Z"}, {"id": "2112653365356433717", "domain": "娱乐", "title_en": "Fans Defend Ariana Grande as Glinda Against Amanda Seyfried Casting Talk", "title_zh": "粉丝力挺 Ariana Grande 饰 Glinda，回击 Seyfried 假想选角", "hook_en": "A post wondering if Amanda Seyfried would have topped Ariana Grande as Glinda in Wicked quickly met pushback from fans who love the film's magic just as it is.", "hook_zh": "有人猜测若 Amanda Seyfried 演《魔法坏女巫》Glinda 是否更强，拥趸迅速反击：电影魔力本就如此。", "summary_en": "Ariana Grande shines as the bubbly Glinda opposite Cynthia Erivo's Elphaba in Jon M. Chu's hit musical films, which have pulled in hundreds of millions at the box office. Seyfried auditioned multiple times, even carving out time during The Dropout shoots, but later said Grande was meant for the role and called the movie fantastic. Fans highlight Grande's vocal range, her chemistry with Erivo, and director Chu's praise for her unique audition energy, shutting down the recurring what-if debate. The back-and-forth underscores fans' strong bond with Wicked's tale of friendship and ambition.", "summary_zh": "Ariana Grande 在 Jon M. Chu 音乐电影中饰活泼 Glinda，搭档 Cynthia Erivo 的 Elphaba，票房数亿美元。Seyfried 曾多次试镜，甚至在拍摄《The Dropout》期间挤时间，后称 Grande 天生适合该角并盛赞成片。粉丝强调其音域、与 Erivo 化学反应及导演对试镜独特能量的赞赏，终结反复 what-if。争论也凸显观众对友情与志向故事的深厚情感连接。", "body_en": "Fans Defend Ariana Grande as Glinda Against Amanda Seyfried Casting Talk.\n\nA post wondering if Amanda Seyfried would have topped Ariana Grande as Glinda in Wicked quickly met pushback from fans who love the film's magic just as it is.\n\nAriana Grande shines as the bubbly Glinda opposite Cynthia Erivo's Elphaba in Jon M. Chu's hit musical films, which have pulled in hundreds of millions at the box office.\n\nSeyfried auditioned multiple times, even carving out time during The Dropout shoots, but later said Grande was meant for the role and called the movie fantastic. Fans highlight Grande's vocal range, her chemistry with Erivo, and director Chu's praise for her unique audition energy, shutting down the recurring what-if debate. The back-and-forth underscores fans' strong bond with Wicked's tale of friendship and ambition.", "body_zh": "粉丝力挺 Ariana Grande 饰 Glinda，回击 Seyfried 假想选角。\n\n有人猜测若 Amanda Seyfried 演《魔法坏女巫》Glinda 是否更强，拥趸迅速反击：电影魔力本就如此。\n\nAriana Grande 在 Jon M. Chu 音乐电影中饰活泼 Glinda，搭档 Cynthia Erivo 的 Elphaba，票房数亿美元。Seyfried 曾多次试镜，甚至在拍摄《The Dropout》期间挤时间，后称 Grande 天生适合该角并盛赞成片。\n\n粉丝强调其音域、与 Erivo 化学反应及导演对试镜独特能量的赞赏，终结反复 what-if。争论也凸显观众对友情与志向故事的深厚情感连接。", "url": "https://x.com/i/trending/2112653365356433717", "category": "Entertainment", "topics": ["Movies & TV", "Celebrity"], "updated_at": "2026-10-21T00:31:26.000Z"}, {"id": "2112433199888679267", "domain": "科学", "title_en": "AI Predicts Cancer Survival from Face Photos", "title_zh": "AI 凭面部照片预测癌症生存风险", "hook_en": "Doctors have always glanced at a patient's face to sense how sick they might be. Now AI makes that gut feel precise, spotting survival odds from a single snapshot.", "hook_zh": "医生一向会扫一眼患者面容判断病情轻重；如今 AI 把这种直觉量化，单张快照即可估计生存概率。", "summary_en": "Researchers from Mass General Brigham, Dana-Farber, Harvard, and Dutch partners unveiled FAHR-Face, two AI tools trained on millions of images that estimate biological age and forecast mortality risk for cancer patients. In tests with over 34,000 patients, the survival model showed those in the highest-risk group faced three times the death risk of the lowest, even after accounting for clinical factors, with strong results in an independent validation. While promising for low-cost checks using just a phone photo, the tools—mostly trained on white Boston patients—need more diverse testing and aren't ready for clinics yet. Lead researchers see it as a complement to doctor judgment, with the model now public on Hugging Face.", "summary_zh": "麻省总医院布莱根、丹娜法伯、哈佛与荷兰合作方发布 FAHR-Face：两款在海量图像上训练的 AI，可估计生物学年龄并预测癌症患者死亡风险。逾 3.4 万名患者测试显示，最高风险组死亡风险约为最低组三倍，即使校正临床因素后仍成立，独立验证表现稳健。工具有望用手机照片做低成本筛查，但主要在波士顿白人患者上训练，需更多元验证，尚不能进诊所。负责人视其为医生判断的补充，模型已在 Hugging Face 公开。", "body_en": "AI Predicts Cancer Survival from Face Photos.\n\nDoctors have always glanced at a patient's face to sense how sick they might be. Now AI makes that gut feel precise, spotting survival odds from a single snapshot.\n\nResearchers from Mass General Brigham, Dana-Farber, Harvard, and Dutch partners unveiled FAHR-Face, two AI tools trained on millions of images that estimate biological age and forecast mortality risk for cancer patients. In tests with over 34,000 patients, the survival model showed those in the highest-risk group faced three times the death risk of the lowest, even after accounting for clinical factors, with strong results in an independent validation.\n\nWhile promising for low-cost checks using just a phone photo, the tools—mostly trained on white Boston patients—need more diverse testing and aren't ready for clinics yet. Lead researchers see it as a complement to doctor judgment, with the model now public on Hugging Face.", "body_zh": "AI 凭面部照片预测癌症生存风险。\n\n医生一向会扫一眼患者面容判断病情轻重；如今 AI 把这种直觉量化，单张快照即可估计生存概率。\n\n麻省总医院布莱根、丹娜法伯、哈佛与荷兰合作方发布 FAHR-Face：两款在海量图像上训练的 AI，可估计生物学年龄并预测癌症患者死亡风险。逾 3.4 万名患者测试显示，最高风险组死亡风险约为最低组三倍，即使校正临床因素后仍成立，独立验证表现稳健。\n\n工具有望用手机照片做低成本筛查，但主要在波士顿白人患者上训练，需更多元验证，尚不能进诊所。负责人视其为医生判断的补充，模型已在 Hugging Face 公开。", "url": "https://x.com/i/trending/2112433199888679267", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-20T21:07:35.000Z"}, {"id": "2112883739105620216", "domain": "科学", "title_en": "NASENI Launches Drone Training, Skills and Clean Energy Projects in Kaduna", "title_zh": "尼日利亚 NASENI 在卡杜纳启动无人机培训、技能与清洁能源项目", "hook_en": "In Kaduna, NASENI's team broke ground on a skills centre while handing out solar systems to 500 families, aiming to spark self-reliance one household at a time.", "hook_zh": "在卡杜纳，NASENI 团队为技能中心奠基，并向 500 户家庭发放太阳能系统，志在一户一户点燃自立。", "summary_en": "NASENI, led by CEO Khalil Halilu, kicked off key initiatives in Kaduna State, including a new Skills Development Centre in Rigachikun, solar home systems and clean cookstoves for 500 beneficiaries through the Sustainable Empowerment Programme, and a drone training facility at the Air Force Institute of Technology partnered with Caverton. The drone centre has already trained two cohorts, with women comprising at least 60 percent in some groups, reducing dependence on foreign technicians and opening technical jobs. These efforts, joined by Governor Uba Sani, highlight NASENI's push for home-grown tech like locally adapted drones for security and farming, plus 44 products from 20 factories tailored to Nigeria's needs.", "summary_zh": "由 CEO Khalil Halilu 率领的 NASENI 在卡杜纳州启动多项举措：Rigachikun 新技能发展中心、通过可持续赋能计划向 500 名受益人提供太阳能户用系统与清洁炉灶，以及与 Caverton 合作、设于空军理工学院的无人机培训设施。无人机中心已培训两批学员，部分班级女性占比至少 60%，减少对外籍技师依赖并开辟技术岗位。州长 Uba Sani 等到场；行动凸显 NASENI 推动本土适配无人机用于安全与农业，以及 20 家工厂 44 种贴合尼日利亚需求产品的努力。", "body_en": "NASENI Launches Drone Training, Skills and Clean Energy Projects in Kaduna.\n\nIn Kaduna, NASENI's team broke ground on a skills centre while handing out solar systems to 500 families, aiming to spark self-reliance one household at a time.\n\nNASENI, led by CEO Khalil Halilu, kicked off key initiatives in Kaduna State, including a new Skills Development Centre in Rigachikun, solar home systems and clean cookstoves for 500 beneficiaries through the Sustainable Empowerment Programme, and a drone training facility at the Air Force Institute of Technology partnered with Caverton.\n\nThe drone centre has already trained two cohorts, with women comprising at least 60 percent in some groups, reducing dependence on foreign technicians and opening technical jobs. These efforts, joined by Governor Uba Sani, highlight NASENI's push for home-grown tech like locally adapted drones for security and farming, plus 44 products from 20 factories tailored to Nigeria's needs.", "body_zh": "尼日利亚 NASENI 在卡杜纳启动无人机培训、技能与清洁能源项目。\n\n在卡杜纳，NASENI 团队为技能中心奠基，并向 500 户家庭发放太阳能系统，志在一户一户点燃自立。\n\n由 CEO Khalil Halilu 率领的 NASENI 在卡杜纳州启动多项举措：Rigachikun 新技能发展中心、通过可持续赋能计划向 500 名受益人提供太阳能户用系统与清洁炉灶，以及与 Caverton 合作、设于空军理工学院的无人机培训设施。\n\n无人机中心已培训两批学员，部分班级女性占比至少 60%，减少对外籍技师依赖并开辟技术岗位。州长 Uba Sani 等到场；行动凸显 NASENI 推动本土适配无人机用于安全与农业，以及 20 家工厂 44 种贴合尼日利亚需求产品的努力。", "url": "https://x.com/i/trending/2112883739105620216", "category": "News", "topics": ["Technology"], "updated_at": "2026-10-21T21:18:12.000Z"}, {"id": "2112771430316404992", "domain": "科学", "title_en": "Biosphere 2 Experiment Revives Debates on Self-Sustaining Living", "title_zh": "生物圈 2 号实验再引「自给生存」讨论", "hook_en": "Eight people stepped into a glass dome in the Arizona desert in 1991, aiming to create a sealed world with its own rainforest, ocean, and farm. Two years later, they emerged thinner but alive, sparking lessons that echo today.", "hook_zh": "1991 年八人走进亚利桑那沙漠玻璃穹顶，试图建造含雨林、海洋与农场的密封世界；两年后消瘦但存活走出，启示至今回响。", "summary_en": "The $150 million Biosphere 2 project tested if humans could thrive in a three-acre sealed ecosystem, growing 80 percent of their calories from crops like sweet potatoes and bananas, with goats providing key milk and a few pigs and chickens for scraps. Challenges hit hard: oxygen levels dropped to 14 percent from soil microbes outpacing plants, crew lost 10-20 percent body weight, and animals like pigs were slaughtered early amid calorie shortages. A popular thread recaps these struggles, with some calling it a warning against plant-heavy diets while others note fixes like added oxygen could work for space or Earth setups. The dome near Tucson now serves as a University of Arizona research site for ecology.", "summary_zh": "耗资约 1.5 亿美元的生物圈 2 号检验人类能否在三英亩密封生态中生存：约 80% 热量来自红薯、香蕉等作物，山羊供奶，少量猪鸡处理厨余。挑战严峻：土壤微生物耗氧快于植物，氧气降至 14%，成员减重 10–20%，猪等动物因热量不足提前宰杀。热门讨论有人视之为植物为主饮食的警示，也有人认为补氧等修正可用于太空或地球方案。图森附近穹顶现为亚利桑那大学生态研究站。", "body_en": "Biosphere 2 Experiment Revives Debates on Self-Sustaining Living.\n\nEight people stepped into a glass dome in the Arizona desert in 1991, aiming to create a sealed world with its own rainforest, ocean, and farm. Two years later, they emerged thinner but alive, sparking lessons that echo today.\n\nThe $150 million Biosphere 2 project tested if humans could thrive in a three-acre sealed ecosystem, growing 80 percent of their calories from crops like sweet potatoes and bananas, with goats providing key milk and a few pigs and chickens for scraps. Challenges hit hard: oxygen levels dropped to 14 percent from soil microbes outpacing plants, crew lost 10-20 percent body weight, and animals like pigs were slaughtered early amid calorie shortages.\n\nA popular thread recaps these struggles, with some calling it a warning against plant-heavy diets while others note fixes like added oxygen could work for space or Earth setups. The dome near Tucson now serves as a University of Arizona research site for ecology.", "body_zh": "生物圈 2 号实验再引「自给生存」讨论。\n\n1991 年八人走进亚利桑那沙漠玻璃穹顶，试图建造含雨林、海洋与农场的密封世界；两年后消瘦但存活走出，启示至今回响。\n\n耗资约 1.5 亿美元的生物圈 2 号检验人类能否在三英亩密封生态中生存：约 80% 热量来自红薯、香蕉等作物，山羊供奶，少量猪鸡处理厨余。挑战严峻：土壤微生物耗氧快于植物，氧气降至 14%，成员减重 10–20%，猪等动物因热量不足提前宰杀。\n\n热门讨论有人视之为植物为主饮食的警示，也有人认为补氧等修正可用于太空或地球方案。图森附近穹顶现为亚利桑那大学生态研究站。", "url": "https://x.com/i/trending/2112771430316404992", "category": "News", "topics": ["Science"], "updated_at": "2026-10-21T07:36:09.000Z"}, {"id": "2112514540671730138", "domain": "科学", "title_en": "Reuters Reveals Heat Storms Blanketing Earth for 18 Years Straight", "title_zh": "路透调查：热风暴已连续 18 年覆盖全球某处", "hook_en": "Imagine heat waves so massive they cover nearly 85% of the planet for over a year—Reuters' investigation uncovers this new reality reshaping daily life worldwide.", "hook_zh": "路透调查呈现新现实：热浪规模大到可覆盖近 85% 地球表面并持续逾一年，正重塑全球日常生活。", "summary_en": "Reuters analyzed over 600 billion temperature readings since 1960 and found heat storms—vast heat waves spanning at least 1% of Earth's surface—now strike 102 times a year on average, up from five in the 1960s. Since July 6, 2008, at least one has raged somewhere every single day, an unbroken 18-year cascade. People share struggles with the relentless heat, which kills nearly half a million annually and damages ecosystems, while the outlet launched a live tracker to monitor these events like hurricanes. Meteorologist Ryan Maue questions the framing, noting a shift in average temperatures explains much of the rise, but Reuters argues naming them helps the public grasp the scale.", "summary_zh": "路透分析自 1960 年以来逾 6000 亿条气温读数，发现「热风暴」——覆盖地球表面至少 1% 的巨大热浪——如今年均约 102 次，1960 年代仅约 5 次。自 2008 年 7 月 6 日起，全球每天至少有一处在经历热风暴，连续 18 年未断。人们分享酷热下的困境；此类事件每年致死近 50 万并损害生态。路透上线类似飓风的实时追踪器。气象学家 Ryan Maue 质疑表述，认为平均气温抬升可解释大部分增加；路透则称命名有助于公众理解规模。", "body_en": "Reuters Reveals Heat Storms Blanketing Earth for 18 Years Straight.\n\nImagine heat waves so massive they cover nearly 85% of the planet for over a year—Reuters' investigation uncovers this new reality reshaping daily life worldwide.\n\nReuters analyzed over 600 billion temperature readings since 1960 and found heat storms—vast heat waves spanning at least 1% of Earth's surface—now strike 102 times a year on average, up from five in the 1960s. Since July 6, 2008, at least one has raged somewhere every single day, an unbroken 18-year cascade.\n\nPeople share struggles with the relentless heat, which kills nearly half a million annually and damages ecosystems, while the outlet launched a live tracker to monitor these events like hurricanes. Meteorologist Ryan Maue questions the framing, noting a shift in average temperatures explains much of the rise, but Reuters argues naming them helps the public grasp the scale.", "body_zh": "路透调查：热风暴已连续 18 年覆盖全球某处。\n\n路透调查呈现新现实：热浪规模大到可覆盖近 85% 地球表面并持续逾一年，正重塑全球日常生活。\n\n路透分析自 1960 年以来逾 6000 亿条气温读数，发现「热风暴」——覆盖地球表面至少 1% 的巨大热浪——如今年均约 102 次，1960 年代仅约 5 次。自 2008 年 7 月 6 日起，全球每天至少有一处在经历热风暴，连续 18 年未断。\n\n人们分享酷热下的困境；此类事件每年致死近 50 万并损害生态。路透上线类似飓风的实时追踪器。气象学家 Ryan Maue 质疑表述，认为平均气温抬升可解释大部分增加；路透则称命名有助于公众理解规模。", "url": "https://x.com/i/trending/2112514540671730138", "category": "News", "topics": ["Science"], "updated_at": "2026-10-20T17:06:35.000Z"}, {"id": "2113023570280329511", "domain": "科学", "title_en": "Marathon Fusion Turns Mercury to Gold in Fusion Breakthroughs", "title_zh": "Marathon Fusion：聚变中把汞变成金，刷新转化速率", "hook_en": "A San Francisco startup just announced turning mercury into stable gold at record rates, blending nuclear fusion with a touch of alchemy. Their lab demos have fusion fans buzzing about clean power plus precious byproducts.", "hook_zh": "旧金山初创宣布以创纪录速率将汞转化为稳定金，把核聚变与一点「炼金」想象结合；实验室演示令聚变拥趸振奋。", "summary_en": "Marathon Fusion reported experimental success transmuting mercury-198 into gold-197 using neutrons from fusion reactions, achieving rates 10 times faster than CERN's record. Last month, they demonstrated high-rate isotope enrichment in a plasma centrifuge, beating a 40-year Soviet benchmark, and they're now building a fusion reactor in the city to test extreme power densities. Backed by DOE funding and experts like MIT's Dennis Whyte, the co-founders aim for a commercial pilot by 2028-2029, with byproducts like gold potentially making fusion plants profitable. While skeptics highlight scaling and regulatory hurdles, the milestones signal real progress toward practical fusion.", "summary_zh": "Marathon Fusion 报告实验成功：利用聚变反应产生的中子将汞-198 嬗变为金-197，速率约为 CERN 纪录的 10 倍。上月他们还在等离子体离心机中演示高速率同位素富集，打破苏联保持约 40 年的基准，并正于市内建造聚变堆以测试极端功率密度。项目获能源部资助，并有麻省理工 Dennis Whyte 等专家支持；联合创始人目标 2028–2029 年商业试点，金等副产品或有助于聚变电厂盈利。怀疑者强调放大与监管障碍，但里程碑仍被视为迈向实用聚变的实质进展。", "body_en": "Marathon Fusion Turns Mercury to Gold in Fusion Breakthroughs.\n\nA San Francisco startup just announced turning mercury into stable gold at record rates, blending nuclear fusion with a touch of alchemy. Their lab demos have fusion fans buzzing about clean power plus precious byproducts.\n\nMarathon Fusion reported experimental success transmuting mercury-198 into gold-197 using neutrons from fusion reactions, achieving rates 10 times faster than CERN's record. Last month, they demonstrated high-rate isotope enrichment in a plasma centrifuge, beating a 40-year Soviet benchmark, and they're now building a fusion reactor in the city to test extreme power densities.\n\nBacked by DOE funding and experts like MIT's Dennis Whyte, the co-founders aim for a commercial pilot by 2028-2029, with byproducts like gold potentially making fusion plants profitable. While skeptics highlight scaling and regulatory hurdles, the milestones signal real progress toward practical fusion.", "body_zh": "Marathon Fusion：聚变中把汞变成金，刷新转化速率。\n\n旧金山初创宣布以创纪录速率将汞转化为稳定金，把核聚变与一点「炼金」想象结合；实验室演示令聚变拥趸振奋。\n\nMarathon Fusion 报告实验成功：利用聚变反应产生的中子将汞-198 嬗变为金-197，速率约为 CERN 纪录的 10 倍。上月他们还在等离子体离心机中演示高速率同位素富集，打破苏联保持约 40 年的基准，并正于市内建造聚变堆以测试极端功率密度。\n\n项目获能源部资助，并有麻省理工 Dennis Whyte 等专家支持；联合创始人目标 2028–2029 年商业试点，金等副产品或有助于聚变电厂盈利。怀疑者强调放大与监管障碍，但里程碑仍被视为迈向实用聚变的实质进展。", "url": "https://x.com/i/trending/2113023570280329511", "category": "News", "topics": ["Science"], "updated_at": "2026-10-21T21:51:23.000Z"}, {"id": "2113014997437861976", "domain": "科学", "title_en": "Trump Signs Order for New NIH Women's Health Division", "title_zh": "特朗普签署行政令设立 NIH 女性健康新部门", "hook_en": "In the Rose Garden, President Trump expressed surprise that the government lacked a dedicated women's health unit, asking, 'Who the hell wouldn’t have a woman’s health division?'", "hook_zh": "在玫瑰园，特朗普总统对政府竟无专门女性健康部门表示惊讶：「谁他妈会不设女性健康司？」", "summary_en": "On October 19, President Donald Trump and First Lady Melania Trump signed an executive order creating a new Women’s Health Division at the National Institutes of Health and a White House task force co-chaired by HHS Secretary Robert F. Kennedy Jr. and Chief of Staff Susie Wiles. The initiative targets conditions like endometriosis, menopause, maternal health, and autoimmune diseases, aiming to translate research into better care across women's lives while rescinding prior Biden-era efforts. Supporters praised it as a vital step, though critics noted the existing NIH Office of Research on Women’s Health since 1990 and called for more funding focus there.", "summary_zh": "10 月 19 日，唐纳德·特朗普总统与第一夫人梅拉尼娅·特朗普签署行政令，在国立卫生研究院设立新的女性健康司，并成立由卫生与公众服务部长罗伯特·F·肯尼迪 Jr. 与幕僚长苏茜·威尔斯共同主持的白宫工作组。倡议针对子宫内膜异位、更年期、孕产妇健康与自身免疫等病症，旨在把研究转化为全生命周期更好照护，同时撤销拜登时期部分相关安排。支持者称其为关键一步；批评者指出 NIH 自 1990 年起已有女性健康研究办公室，呼吁把更多资金聚焦既有机制。", "body_en": "Trump Signs Order for New NIH Women's Health Division.\n\nIn the Rose Garden, President Trump expressed surprise that the government lacked a dedicated women's health unit, asking, 'Who the hell wouldn’t have a woman’s health division?'\n\nOn October 19, President Donald Trump and First Lady Melania Trump signed an executive order creating a new Women’s Health Division at the National Institutes of Health and a White House task force co-chaired by HHS Secretary Robert F. Kennedy Jr.\n\nand Chief of Staff Susie Wiles. The initiative targets conditions like endometriosis, menopause, maternal health, and autoimmune diseases, aiming to translate research into better care across women's lives while rescinding prior Biden-era efforts. Supporters praised it as a vital step, though critics noted the existing NIH Office of Research on Women’s Health since 1990 and called for more funding focus there.", "body_zh": "特朗普签署行政令设立 NIH 女性健康新部门。\n\n在玫瑰园，特朗普总统对政府竟无专门女性健康部门表示惊讶：「谁他妈会不设女性健康司？」\n\n10 月 19 日，唐纳德·特朗普总统与第一夫人梅拉尼娅·特朗普签署行政令，在国立卫生研究院设立新的女性健康司，并成立由卫生与公众服务部长罗伯特·F·肯尼迪 Jr. 与幕僚长苏茜·威尔斯共同主持的白宫工作组。\n\n倡议针对子宫内膜异位、更年期、孕产妇健康与自身免疫等病症，旨在把研究转化为全生命周期更好照护，同时撤销拜登时期部分相关安排。支持者称其为关键一步；批评者指出 NIH 自 1990 年起已有女性健康研究办公室，呼吁把更多资金聚焦既有机制。", "url": "https://x.com/i/trending/2113014997437861976", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-21T21:18:11.000Z"}, {"id": "2112946155130904714", "domain": "科学", "title_en": "Coherence Neuro Raises $45M for Adaptive Brain Cancer Implant", "title_zh": "Coherence Neuro为适应性脑癌植入物筹集了4500万美元$", "hook_en": "Co-founders Ben Woodington and Elise Jenkins are turning brain-computer tech into a smart implant that tracks and fights glioblastoma in real time. Jenkins celebrated the news simply: 'We did a thing!'", "hook_zh": "联合创始人本·伍丁顿（ Ben Woodington ）和伊丽莎白·詹金斯（ Elise Jenkins ）正在将脑机技术转变为一种智能植入物，可以实时跟踪和抗击胶质母细胞瘤。詹金斯只是简单地庆祝这个消息： “我们做了一件事！”", "summary_en": "The San Francisco startup raised $45 million in Series A funding, co-led by Founders Fund and OpenAI Startup Fund, to build the SOMA platform—a coin-sized skull implant that records tumor electrical signals, delivers targeted stimulation to disrupt growth, and adjusts via an app and wearable. It builds on early prototype tests in three patients at Royal Melbourne Hospital, confirming basic performance, with plans for longer-term trials in glioblastoma cases. Investors praised the team's rigorous approach to bioelectronic cancer therapy, which offers live disease tracking, while the company hires to expand in San Francisco and Cambridge, UK.", "summary_zh": "这家旧金山初创公司在Founders Fund和OpenAI Startup Fund的共同领导下筹集了4500万美元的A轮融资，用于构建SOMA平台，这是一个硬币大小的头骨植入物，可记录肿瘤电信号，提供有针对性的刺激以破坏增长，并通过应用程序和可穿戴设备进行调整。 它建立在皇家墨尔本医院三名患者的早期原型测试的基础上，确认了基本性能，并计划在胶质母细胞瘤病例中进行长期试验。投资者赞扬该团队对生物电子癌症治疗的严格方法，该方法提供实时疾病跟踪，而该公司则在旧金山和英国剑桥进行扩张。", "body_en": "Co-founders Ben Woodington and Elise Jenkins are turning brain-computer tech into a smart implant that tracks and fights glioblastoma in real time. Jenkins celebrated the news simply: 'We did a thing!'\n\nThe San Francisco startup raised $45 million in Series A funding, co-led by Founders Fund and OpenAI Startup Fund, to build the SOMA platform—a coin-sized skull implant that records tumor electrical signals, delivers targeted stimulation to disrupt growth, and adjusts via an app and wearable.\n\nIt builds on early prototype tests in three patients at Royal Melbourne Hospital, confirming basic performance, with plans for longer-term trials in glioblastoma cases. Investors praised the team's rigorous approach to bioelectronic cancer therapy, which offers live disease tracking, while the company hires to expand in San Francisco and Cambridge, UK.", "body_zh": "联合创始人本·伍丁顿（ Ben Woodington ）和伊丽莎白·詹金斯（ Elise Jenkins ）正在将脑机技术转变为一种智能植入物，可以实时跟踪和抗击胶质母细胞瘤。詹金斯只是简单地庆祝这个消息： “我们做了一件事！”\n\n这家旧金山初创公司在Founders Fund和OpenAI Startup Fund的共同领导下筹集了4500万美元的A轮融资，用于构建SOMA平台，这是一个硬币大小的头骨植入物，可记录肿瘤电信号，提供有针对性的刺激以破坏增长，并通过应用程序和可穿戴设备进行调整。\n\n它建立在皇家墨尔本医院三名患者的早期原型测试的基础上，确认了基本性能，并计划在胶质母细胞瘤病例中进行长期试验。投资者赞扬该团队对生物电子癌症治疗的严格方法，该方法提供实时疾病跟踪，而该公司则在旧金山和英国剑桥进行扩张。", "url": "https://x.com/i/trending/2112946155130904714", "category": "News", "topics": ["Business & Finance", "Technology", "Biotech"], "updated_at": "2026-10-21T19:57:20.000Z"}, {"id": "2112968032066920582", "domain": "科学", "title_en": "Biosphere 2's Oxygen Crisis and Chaotic Missions Recounted", "title_zh": "回顾生物圈 2 号氧气危机与混乱任务", "hook_en": "Eight people sealed themselves inside a massive glass world in Arizona, dreaming of self-sustaining life like on Mars. But falling oxygen and hungry goats turned their two-year stay into a survival test.", "hook_zh": "八人把自己封进亚利桑那巨型玻璃世界，梦想如火星般自给自足；氧气下降与饥饿山羊却把两年驻留变成生存考验。", "summary_en": "Biosphere 2, a $150 million glass complex with rainforests, oceans, and farms, launched its first mission on September 26, 1991, with eight crew members facing sharp oxygen drops to 14% from soil microbes and food shortages that led to weight loss and reliance on goat milk. Pigs were culled amid struggles, while the second 1994 mission achieved food self-sufficiency before bankers led by Steve Bannon took over, sparking a break-in by original crew and an early end. Today, the University of Arizona runs it as a research site, with the story's real dramas echoing the 1996 comedy Bio-Dome and lessons from the 2020 documentary Spaceship Earth.", "summary_zh": "造价约 1.5 亿美元、含雨林海洋与农场的生物圈 2 号，于 1991 年 9 月 26 日启动首次任务；八名乘员遭遇土壤微生物导致氧气骤降至 14%、食物短缺引发体重下降并依赖羊奶。猪只被扑杀，1994 年第二次任务曾实现食物自给，随后由史蒂夫·班农主导的银行方接管，原班成员破门而入，任务提前结束。如今由亚利桑那大学用作研究设施；真实波折呼应 1996 年喜剧《Bio-Dome》，也见于 2020 年纪录片《地球号飞船》的教训。", "body_en": "Biosphere 2's Oxygen Crisis and Chaotic Missions Recounted.\n\nEight people sealed themselves inside a massive glass world in Arizona, dreaming of self-sustaining life like on Mars. But falling oxygen and hungry goats turned their two-year stay into a survival test.\n\nBiosphere 2, a $150 million glass complex with rainforests, oceans, and farms, launched its first mission on September 26, 1991, with eight crew members facing sharp oxygen drops to 14% from soil microbes and food shortages that led to weight loss and reliance on goat milk.\n\nPigs were culled amid struggles, while the second 1994 mission achieved food self-sufficiency before bankers led by Steve Bannon took over, sparking a break-in by original crew and an early end. Today, the University of Arizona runs it as a research site, with the story's real dramas echoing the 1996 comedy Bio-Dome and lessons from the 2020 documentary Spaceship Earth.", "body_zh": "回顾生物圈 2 号氧气危机与混乱任务。\n\n八人把自己封进亚利桑那巨型玻璃世界，梦想如火星般自给自足；氧气下降与饥饿山羊却把两年驻留变成生存考验。\n\n造价约 1.5 亿美元、含雨林海洋与农场的生物圈 2 号，于 1991 年 9 月 26 日启动首次任务；八名乘员遭遇土壤微生物导致氧气骤降至 14%、食物短缺引发体重下降并依赖羊奶。\n\n猪只被扑杀，1994 年第二次任务曾实现食物自给，随后由史蒂夫·班农主导的银行方接管，原班成员破门而入，任务提前结束。如今由亚利桑那大学用作研究设施；真实波折呼应 1996 年喜剧《Bio-Dome》，也见于 2020 年纪录片《地球号飞船》的教训。", "url": "https://x.com/i/trending/2112968032066920582", "category": "News", "topics": ["News", "Science"], "updated_at": "2026-10-21T18:10:40.000Z"}, {"id": "2112905930044317939", "domain": "科学", "title_en": "NVIDIA and UW Unveil RFD4-Proteina for Faster Protein Design", "title_zh": "英伟达与华盛顿大学发布 RFD4-Proteina，加速蛋白质设计", "hook_en": "Nobel laureate David Baker sees a new era: designing proteins from scratch, not just discovering nature's own. This tool makes it faster and more reliable than ever.", "hook_zh": "英伟达与华盛顿大学科学家推出新的 AI 工具，可更快、更好地设计蛋白质，已被寄望加速药物发现。", "summary_en": "NVIDIA and the University of Washington's Institute for Protein Design released RFD4-Proteina, an open model that generates proteins and biomolecules up to 13 times faster than prior tools like RFdiffusion3. Born from a year-long collaboration between Baker Lab and NVIDIA’s GenAIR team, it unifies amino acids, sugars, DNA, and RNA in one space, enabling designs for drug binders and enzymes—including one that helps synthesize the HIV drug lenacapavir. Fully open-source on GitHub and Hugging Face, with free GPU access for two weeks, it promises to boost fields from drug discovery to industrial enzymes and protein design competitions.", "summary_zh": "RFD4-Proteina 由英伟达 GenAIR 团队与华盛顿大学蛋白质设计研究所 Baker 实验室合作一年而成，在共享潜空间中协同设计蛋白质序列与结构。它可处理结合物设计、酶支架、基序条件化，以及 DNA、RNA 或小分子相关任务，在速度、质量与湿实验成功率上优于此前模型。该工具在柏林 GTC 以开源形式登陆 GitHub 与 Hugging Face，并作为英伟达 NIM 微服务提供，还与 Tamarind Bio 等伙伴集成以便使用。研究人员称结果「令人惊叹」，是生物学与医学的前沿跃升。", "body_en": "NVIDIA and UW Unveil RFD4-Proteina for Faster Protein Design.\n\nScientists at NVIDIA and the University of Washington just dropped a powerful new AI tool that designs proteins quicker and better than before. It's already drawing cheers for speeding up drug discovery.\n\nRFD4-Proteina, born from a year-long collaboration between NVIDIA's GenAIR team and the Baker Lab at UW's Institute for Protein Design, co-designs protein sequences and structures in a shared latent space. It handles binder design, enzyme scaffolding, motif conditioning, and work with DNA, RNA, or small molecules, outperforming prior models in speed, quality, and wet-lab success rates.\n\nReleased open source on GitHub and Hugging Face at GTC Berlin, it's available as an NVIDIA NIM microservice and integrated with partners like Tamarind Bio for easy use. Researchers called the results 'astonishing' and a state-of-the-art leap for biology and medicine.", "body_zh": "英伟达与华盛顿大学发布 RFD4-Proteina，加速蛋白质设计。\n\n英伟达与华盛顿大学科学家推出新的 AI 工具，可更快、更好地设计蛋白质，已被寄望加速药物发现。\n\nRFD4-Proteina 由英伟达 GenAIR 团队与华盛顿大学蛋白质设计研究所 Baker 实验室合作一年而成，在共享潜空间中协同设计蛋白质序列与结构。它可处理结合物设计、酶支架、基序条件化，以及 DNA、RNA 或小分子相关任务，在速度、质量与湿实验成功率上优于此前模型。\n\n该工具在柏林 GTC 以开源形式登陆 GitHub 与 Hugging Face，并作为英伟达 NIM 微服务提供，还与 Tamarind Bio 等伙伴集成以便使用。研究人员称结果「令人惊叹」，是生物学与医学的前沿跃升。", "url": "https://x.com/i/trending/2112905930044317939", "category": "News", "topics": ["Technology", "Biotech"], "updated_at": "2026-10-21T19:42:52.000Z"}, {"id": "2112623559876952326", "domain": "科学", "title_en": "Reflect Orbital Simulates Orbital Sunlight in California Desert Test", "title_zh": "Reflect Orbital 在加州模拟轨道阳光", "hook_en": "In a dark desert near Mount Whitney, powerful spotlights turned night into a moonlit glow, mimicking future satellites beaming sunlight to Earth.", "hook_zh": "惠特尼山附近暗夜沙漠中，强光把夜色照成月色，预演未来阳光卫星。", "summary_en": "On October 10, California startup Reflect Orbital tested ground-based lights along Horseshoe Meadows Road near Lone Pine, illuminating three miles of terrain to aid nighttime search-and-rescue exercises with China Lake Mountain Rescue teams. The demo previews a satellite constellation with reflective mirrors to deliver targeted sunlight for emergencies or solar farms. While supporters highlight rescue benefits, astronomers worry about light pollution harming stargazing and wildlife, and skeptics question economics and environmental impacts as the company plans launches with India's Skyroot Aerospace.", "summary_zh": "10 月 10 日，加州初创公司 Reflect Orbital 在孤松镇附近 Horseshoe Meadows Road 沿线用地面灯具试验，照亮约三英里地形，协助 China Lake 山地救援队开展夜间搜救演练。演示预示将以反射镜卫星星座向应急场景或太阳能电站投送定向阳光。支持者强调救援价值，天文学家担忧光污染影响观星与野生动物，亦有人质疑经济性与环境影响；公司计划与印度 Skyroot Aerospace 合作发射。", "body_en": "Reflect Orbital Simulates Orbital Sunlight in California Desert Test.\n\nIn a dark desert near Mount Whitney, powerful spotlights turned night into a moonlit glow, mimicking future satellites beaming sunlight to Earth.\n\nOn October 10, California startup Reflect Orbital tested ground-based lights along Horseshoe Meadows Road near Lone Pine, illuminating three miles of terrain to aid nighttime search-and-rescue exercises with China Lake Mountain Rescue teams.\n\nThe demo previews a satellite constellation with reflective mirrors to deliver targeted sunlight for emergencies or solar farms. While supporters highlight rescue benefits, astronomers worry about light pollution harming stargazing and wildlife, and skeptics question economics and environmental impacts as the company plans launches with India's Skyroot Aerospace.", "body_zh": "Reflect Orbital 在加州模拟轨道阳光。\n\n惠特尼山附近暗夜沙漠中，强光把夜色照成月色，预演未来阳光卫星。\n\n10 月 10 日，加州初创公司 Reflect Orbital 在孤松镇附近 Horseshoe Meadows Road 沿线用地面灯具试验，照亮约三英里地形，协助 China Lake 山地救援队开展夜间搜救演练。\n\n演示预示将以反射镜卫星星座向应急场景或太阳能电站投送定向阳光。支持者强调救援价值，天文学家担忧光污染影响观星与野生动物，亦有人质疑经济性与环境影响；公司计划与印度 Skyroot Aerospace 合作发射。", "url": "https://x.com/i/trending/2112623559876952326", "category": "News", "topics": ["Technology", "Space"], "updated_at": "2026-10-21T00:18:52.000Z"}, {"id": "2112820742060495085", "domain": "科学", "title_en": "Rizhao Residents Watch Rocket Launch from Home Windows", "title_zh": "日照市民在家门口「看火箭」升空", "hook_en": "People in Rizhao, China, peered out their bedroom windows to see a rocket soar into the sky over the Yellow Sea. It was a stunning, everyday view of space history unfolding right outside.", "hook_zh": "中国日照居民透过卧室窗户，便能看见火箭从黄海上空腾起——航天发射成了海边日常景观。", "summary_en": "On October 21, 2026, Galactic Energy’s Ceres-1S Y8 rocket lifted off at 11:39 a.m. Beijing Time from an offshore platform near Rizhao in Shandong Province, successfully placing the XiGuang-4-01 Earth-observation satellite into a 541-kilometer orbit. The satellite features high-resolution cameras and sensors to support monitoring in areas like the Guangdong-Hong Kong-Macao Greater Bay Area and along the Maritime Silk Road. This seventh sea-based mission for the Ceres-1 series used a new shore-based command center, giving coastal residents a clear, front-row view of the liftoff from their homes.", "summary_zh": "2026 年 10 月 21 日北京时间 11:39，银河动力（Galactic Energy）的朱雀一号（Ceres-1S）Y8 运载火箭在山东日照附近海上平台升空，成功将「羲光四号 01」对地观测卫星送入约 541 公里轨道。卫星搭载高分相机与传感器，服务粤港澳大湾区及海上丝绸之路等监测需求。这是朱雀一号系列第七次海上发射，并启用新的岸基指挥中心，让沿海居民能在家清晰目睹发射。", "body_en": "Rizhao Residents Watch Rocket Launch from Home Windows.\n\nPeople in Rizhao, China, peered out their bedroom windows to see a rocket soar into the sky over the Yellow Sea. It was a stunning, everyday view of space history unfolding right outside.\n\nOn October 21, 2026, Galactic Energy’s Ceres-1S Y8 rocket lifted off at 11:39 a.m. Beijing Time from an offshore platform near Rizhao in Shandong Province, successfully placing the XiGuang-4-01 Earth-observation satellite into a 541-kilometer orbit.\n\nThe satellite features high-resolution cameras and sensors to support monitoring in areas like the Guangdong-Hong Kong-Macao Greater Bay Area and along the Maritime Silk Road. This seventh sea-based mission for the Ceres-1 series used a new shore-based command center, giving coastal residents a clear, front-row view of the liftoff from their homes.", "body_zh": "日照市民在家门口「看火箭」升空。\n\n中国日照居民透过卧室窗户，便能看见火箭从黄海上空腾起——航天发射成了海边日常景观。\n\n2026 年 10 月 21 日北京时间 11:39，银河动力（Galactic Energy）的朱雀一号（Ceres-1S）Y8 运载火箭在山东日照附近海上平台升空，成功将「羲光四号 01」对地观测卫星送入约 541 公里轨道。\n\n卫星搭载高分相机与传感器，服务粤港澳大湾区及海上丝绸之路等监测需求。这是朱雀一号系列第七次海上发射，并启用新的岸基指挥中心，让沿海居民能在家清晰目睹发射。", "url": "https://x.com/i/trending/2112820742060495085", "category": "News", "topics": ["Space"], "updated_at": "2026-10-21T08:24:00.000Z"}, {"id": "2112552619117891920", "domain": "科学", "title_en": "Review Details Antiparasitic Drugs' Potential Cancer Mechanisms", "title_zh": "综述梳理抗寄生虫药潜在抗癌机制", "hook_en": "Imagine affordable drugs already on pharmacy shelves quietly targeting cancer in lab studies. A new review compiles dozens of ways ivermectin and mebendazole might disrupt tumor growth.", "hook_zh": "药房货架上本已可及的平价药，实验室中却不断出现干扰肿瘤生长的线索；新综述汇总数十条可能路径。", "summary_en": "Researchers, including Nicolas Hulscher of the McCullough Foundation, released a 44-page paper this week outlining 29 anticancer mechanisms for ivermectin across 20 cancer types and 26 for mebendazole across 17 types. These include halting cell division, triggering cell death, blocking tumor blood vessels, and boosting immune responses, with both drugs showing decades of safety data and low costs. Patient stories highlight hope, like a Polish woman with multiple myeloma seeing no disease markers after six months on ivermectin, fenbendazole, and mebendazole, while an observational group of 197 patients reported an 84.4% clinical benefit rate. Proponents call for clinical trials, but experts stress the need for randomized studies to confirm benefits alongside standard care.", "summary_zh": "包括 McCullough Foundation 的 Nicolas Hulscher 在内的研究者本周发布约 44 页论文，梳理伊维菌素在约 20 种癌型中的 29 条抗癌机制，以及甲苯咪唑在约 17 种癌型中的 26 条机制，含抑制分裂、诱导死亡、阻断肿瘤血管与增强免疫等，并强调数十年安全性与低成本。患者故事如波兰多发性骨髓瘤患者联用伊维菌素、芬苯达唑与甲苯咪唑六个月后未见疾病标志；一项 197 人观察性数据称临床获益率约 84.4%。支持者呼吁临床试验，专家则强调需随机研究才能确认是否可与标准治疗并用。", "body_en": "Review Details Antiparasitic Drugs' Potential Cancer Mechanisms.\n\nImagine affordable drugs already on pharmacy shelves quietly targeting cancer in lab studies. A new review compiles dozens of ways ivermectin and mebendazole might disrupt tumor growth.\n\nResearchers, including Nicolas Hulscher of the McCullough Foundation, released a 44-page paper this week outlining 29 anticancer mechanisms for ivermectin across 20 cancer types and 26 for mebendazole across 17 types. These include halting cell division, triggering cell death, blocking tumor blood vessels, and boosting immune responses, with both drugs showing decades of safety data and low costs.\n\nPatient stories highlight hope, like a Polish woman with multiple myeloma seeing no disease markers after six months on ivermectin, fenbendazole, and mebendazole, while an observational group of 197 patients reported an 84.4% clinical benefit rate. Proponents call for clinical trials, but experts stress the need for randomized studies to confirm benefits alongside standard care.", "body_zh": "综述梳理抗寄生虫药潜在抗癌机制。\n\n药房货架上本已可及的平价药，实验室中却不断出现干扰肿瘤生长的线索；新综述汇总数十条可能路径。\n\n包括 McCullough Foundation 的 Nicolas Hulscher 在内的研究者本周发布约 44 页论文，梳理伊维菌素在约 20 种癌型中的 29 条抗癌机制，以及甲苯咪唑在约 17 种癌型中的 26 条机制，含抑制分裂、诱导死亡、阻断肿瘤血管与增强免疫等，并强调数十年安全性与低成本。\n\n患者故事如波兰多发性骨髓瘤患者联用伊维菌素、芬苯达唑与甲苯咪唑六个月后未见疾病标志；一项 197 人观察性数据称临床获益率约 84.4%。支持者呼吁临床试验，专家则强调需随机研究才能确认是否可与标准治疗并用。", "url": "https://x.com/i/trending/2112552619117891920", "category": "News", "topics": ["Health & Fitness"], "updated_at": "2026-10-21T17:22:35.000Z"}, {"id": "2112331788529840225", "domain": "科学", "title_en": "Trump Cuts Weather Satellite Plans, Sparking Expert Divide", "title_zh": "特朗普削减气象卫星计划，引发专家分歧", "hook_en": "Experts warn that trimming U.S. weather satellites could rewind forecasting by a decade, while supporters say it sharpens focus on what matters most.", "hook_zh": "专家警告说，削减美国气象卫星可能会使预测倒退十年，而支持者表示，这会使人们更加关注最重要的事情。", "summary_en": "The Trump administration scaled back the GeoXO satellite program from six to four spacecraft and cut three instruments, dropping costs from $19.6 billion to $13 billion. A Government Accountability Office report from October 16, 2026, raised concerns about coverage gaps until 2032 and potential shortfalls in capabilities like air quality, ocean monitoring, and lightning mapping. Critics, including Democratic lawmakers, fear weaker predictions for extreme weather, but meteorologists like Ryan Maue call media coverage misleading and praise the refocus on core forecasting.", "summary_zh": "特朗普政府将GeoXO卫星计划从6个减少到4个，并削减了3个仪器，将成本从196亿美元降至130亿美元。政府问责局2026年10月16日的一份报告对2032年之前的覆盖缺口以及空气质量、海洋监测和闪电测绘等能力的潜在短缺提出了担忧。 包括民主党议员在内的批评人士担心极端天气的预测会减弱，但Ryan Maue等气象学家称媒体报道具有误导性，并赞扬重新关注核心预测。", "body_en": "Trump Cuts Weather Satellite Plans, Sparking Expert Divide.\n\nExperts warn that trimming U.S. weather satellites could rewind forecasting by a decade, while supporters say it sharpens focus on what matters most.\n\nThe Trump administration scaled back the GeoXO satellite program from six to four spacecraft and cut three instruments, dropping costs from $19.6 billion to $13 billion.\n\nA Government Accountability Office report from October 16, 2026, raised concerns about coverage gaps until 2032 and potential shortfalls in capabilities like air quality, ocean monitoring, and lightning mapping. Critics, including Democratic lawmakers, fear weaker predictions for extreme weather, but meteorologists like Ryan Maue call media coverage misleading and praise the refocus on core forecasting.", "body_zh": "专家警告说，削减美国气象卫星可能会使预测倒退十年，而支持者表示，这会使人们更加关注最重要的事情。\n\n特朗普政府将GeoXO卫星计划从6个减少到4个，并削减了3个仪器，将成本从196亿美元降至130亿美元。\n\n政府问责局2026年10月16日的一份报告对2032年之前的覆盖缺口以及空气质量、海洋监测和闪电测绘等能力的潜在短缺提出了担忧。包括民主党议员在内的批评人士担心极端天气的预测会减弱，但Ryan Maue等气象学家称媒体报道具有误导性，并赞扬重新关注核心预测。", "url": "https://x.com/i/trending/2112331788529840225", "category": "News", "topics": ["News", "Politics"], "updated_at": "2026-10-21T17:06:32.000Z"}]};
